--SELECT * FROM #TRANSLOG
IF OBJECT_ID('TEMPDB..#TRANSLOG_UNDERGRP') IS NOT NULL   
	DROP TABLE #TRANSLOG_UNDERGRP
	
CREATE TABLE #TRANSLOG_UNDERGRP(
	CODE NVARCHAR(15),
	NAME NVARCHAR(500)
)
DECLARE @OPBALTEXT NVARCHAR(4000) 
SET @OPBALTEXT ='
INSERT INTO #TRANSLOG_UNDERGRP
SELECT CODE, NAME FROM ' + @OPBALTABLE + ' WHERE CODE LIKE ' + CHAR(39) + 'M%' + CHAR(39) + ''
--PRINT(@OPBALTEXT)
EXEC(@OPBALTEXT)

IF OBJECT_ID('TEMPDB..#TRANSLOG_OPBAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_OPBAL

CREATE TABLE #TRANSLOG_OPBAL (
	ACCTCODE NVARCHAR(15),
	OPBAL DECIMAL(18,2),
	OPBALDR DECIMAL(18,2),
	OPBALCR DECIMAL(18,2),
)
--DECLARE @OPBALTEXT NVARCHAR(4000) 
SET @OPBALTEXT ='
INSERT INTO #TRANSLOG_OPBAL
SELECT	CODE,
		ISNULL([' + @CMPCITYCODE + 'OP],0), 
		OPBALDR = CASE WHEN ISNULL([' + @CMPCITYCODE + 'OP],0)  >= 0 THEN ISNULL([' + @CMPCITYCODE + 'OP],0) ELSE 0 END,
		OPBALCR = CASE WHEN ISNULL([' + @CMPCITYCODE + 'OP],0)  < 0 THEN ISNULL(ABS([' + @CMPCITYCODE + 'OP]),0) ELSE 0 END
FROM	'+ @OPBALTABLE +''
--PRINT(@OPBALTEXT)  
EXEC(@OPBALTEXT)              

--SELECT * FROM #TRANSLOG_OPBAL

/* COLLECTION OF ALL ACCOUNT FROM TRANSACTION LOG AND OPENING BALANCE*/
IF OBJECT_ID('TEMPDB..#TRANSLOG_ACCOUNT') IS NOT NULL   
	DROP TABLE #TRANSLOG_ACCOUNT
	
CREATE TABLE #TRANSLOG_ACCOUNT(                      
		ACCTCODE NVARCHAR(15),
		ACCTNAME NVARCHAR(500),
		GROUPCODE NVARCHAR(100)
		) 

INSERT	INTO #TRANSLOG_ACCOUNT	
SELECT	DISTINCT #TRANSLOG.ACCTCODE,
		ISNULL(LTRIM(RTRIM(EXP_MASTER.EXP_NAME)),'') +  ISNULL(LTRIM(RTRIM(SUPPLIER_MASTER.SUP_NAME)),'') +   ISNULL(LTRIM(RTRIM(GENACCT_MASTER.ACCTNAME)),'') AS ACCNAME,
		CASE WHEN GENACCT_MASTER.ACCTNAME IS NOT NULL THEN UNDERGROUP
			WHEN EXP_MASTER.EXP_NAME IS NOT NULL THEN 'M000028'
			WHEN SUPPLIER_MASTER.SUP_NAME IS NOT NULL THEN 'M000029' ELSE '' END
FROM	#TRANSLOG 
		LEFT OUTER JOIN DBO.EXP_MASTER ON #TRANSLOG.ACCTCODE = DBO.EXP_MASTER.EXP_CODE
		LEFT OUTER JOIN DBO.SUPPLIER_MASTER ON #TRANSLOG.ACCTCODE = DBO.SUPPLIER_MASTER.SUP_CODE
		LEFT OUTER JOIN DBO.GENACCT_MASTER ON #TRANSLOG.ACCTCODE = DBO.GENACCT_MASTER.ACCTCODE

INSERT INTO #TRANSLOG_ACCOUNT
SELECT	DISTINCT #TRANSLOG_OPBAL.ACCTCODE,
		ISNULL(LTRIM(RTRIM(EXP_MASTER.EXP_NAME)),'') +  ISNULL(LTRIM(RTRIM(SUPPLIER_MASTER.SUP_NAME)),'') +   ISNULL(LTRIM(RTRIM(GENACCT_MASTER.ACCTNAME)),'') AS ACCNAME,
		CASE WHEN GENACCT_MASTER.ACCTNAME IS NOT NULL THEN UNDERGROUP
			WHEN EXP_MASTER.EXP_NAME IS NOT NULL THEN 'M000028'
			WHEN SUPPLIER_MASTER.SUP_NAME IS NOT NULL THEN 'M000029' ELSE '' END                          
FROM	#TRANSLOG_OPBAL 
		LEFT OUTER JOIN DBO.EXP_MASTER ON #TRANSLOG_OPBAL.ACCTCODE = DBO.EXP_MASTER.EXP_CODE
		LEFT OUTER JOIN DBO.SUPPLIER_MASTER ON #TRANSLOG_OPBAL.ACCTCODE = DBO.SUPPLIER_MASTER.SUP_CODE
		LEFT OUTER JOIN DBO.GENACCT_MASTER ON #TRANSLOG_OPBAL.ACCTCODE = DBO.GENACCT_MASTER.ACCTCODE
WHERE	#TRANSLOG_OPBAL.ACCTCODE NOT IN (SELECT #TRANSLOG_ACCOUNT.ACCTCODE FROM #TRANSLOG_ACCOUNT)
--GROUP BY ACCTCODE                              
--SELECT * FROM #TRANSLOG_ACCOUNT

IF OBJECT_ID('TEMPDB..#TRANSLOG_PREV') IS NOT NULL   
	DROP TABLE #TRANSLOG_PREV
	
CREATE TABLE #TRANSLOG_PREV(                      
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                              
	CRAMT DECIMAL(18,2)) 
INSERT INTO #TRANSLOG_PREV	
SELECT	ACCTCODE,                               
		ISNULL(SUM(ISNULL(DRAMT,0)),0) DRAMT,                               
		ISNULL(SUM(ISNULL(CRAMT,0)),0) CRAMT                              
FROM	#TRANSLOG 
WHERE	[DBO].[RPT_YYYYMMDD](TRANSDATE) BETWEEN @FDATE AND @USR_DATE_START_LAST
GROUP BY ACCTCODE                              

IF OBJECT_ID('TEMPDB..#TRANSLOG_CURR') IS NOT NULL   
	DROP TABLE #TRANSLOG_CURR
	
CREATE TABLE #TRANSLOG_CURR(                      
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                              
	CRAMT DECIMAL(18,2)) 
INSERT INTO #TRANSLOG_CURR
SELECT	ACCTCODE,                               
		ISNULL(SUM(ISNULL(DRAMT,0)),0) DRAMT,                               
		ISNULL(SUM(ISNULL(CRAMT,0)),0) CRAMT                              
FROM	#TRANSLOG 
WHERE	[DBO].[RPT_YYYYMMDD](TRANSDATE) BETWEEN @USR_DATE_START_FIRST AND @TDATE
GROUP BY ACCTCODE                              
-- */
--SELECT * FROM #TRANSLOG_UNDERGRP
--SELECT * FROM #TRANSLOG_OPBAL
--SELECT * FROM #TRANSLOG_PREV
--SELECT * FROM #TRANSLOG_CURR
--SELECT * FROM #TRANSLOG_ACCOUNT

IF OBJECT_ID('TEMPDB..#TRANSLOG_FINAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_FINAL

CREATE TABLE #TRANSLOG_FINAL(
	SEQ NVARCHAR(5),
	GROUPCODE NVARCHAR(15),
	GROUPNAME NVARCHAR(500),	
	ACCTCODE NVARCHAR(15),
	ACCTNAME NVARCHAR(500),
	OPBLDR DECIMAL(18,2),                              
	OPBLCR DECIMAL(18,2),
	PREVDR DECIMAL(18,2),                              
	PREVCR DECIMAL(18,2),
	CURRDR DECIMAL(18,2),                              
	CURRCR DECIMAL(18,2),
	CLBLDR DECIMAL(18,2),                              
	CLBLCR DECIMAL(18,2)	
	) 

INSERT INTO #TRANSLOG_FINAL
SELECT	'000',
		GROUPCODE = CASE WHEN LEN(GROUPCODE) =0 THEN 'AAAA' ELSE GROUPCODE END, 
		GROUPNAME = ISNULL((SELECT NAME FROM #TRANSLOG_UNDERGRP WHERE #TRANSLOG_UNDERGRP.CODE = GROUPCODE),'  Non Group'),
		ACCTCODE, 
		ACCTNAME,		
		OPBLDR = ISNULL((SELECT OPBALDR FROM #TRANSLOG_OPBAL WHERE #TRANSLOG_OPBAL.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		OPBLCR = ISNULL((SELECT OPBALCR FROM #TRANSLOG_OPBAL WHERE #TRANSLOG_OPBAL.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		PREVDR = ISNULL((SELECT DRAMT FROM #TRANSLOG_PREV WHERE #TRANSLOG_PREV.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		PREVCR = ISNULL((SELECT CRAMT FROM #TRANSLOG_PREV WHERE #TRANSLOG_PREV.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		CURRDR = ISNULL((SELECT DRAMT FROM #TRANSLOG_CURR WHERE #TRANSLOG_CURR.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		CURRCR = ISNULL((SELECT CRAMT FROM #TRANSLOG_CURR WHERE #TRANSLOG_CURR.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		0,
		0
FROM	#TRANSLOG_ACCOUNT
WHERE	ACCTCODE NOT LIKE  'M%'
ORDER BY ACCTNAME


UPDATE	#TRANSLOG_FINAL 
SET		CLBLDR = CASE WHEN (OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR)) >= 0 THEN (OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR)) ELSE 0 END,
		CLBLCR = CASE WHEN (OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR)) < 0 THEN ABS((OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR))) ELSE 0 END

IF OBJECT_ID('TEMPDB..#TRANSLOG_REPORT') IS NOT NULL   
	DROP TABLE #TRANSLOG_REPORT

CREATE TABLE #TRANSLOG_REPORT(
	SEQ NVARCHAR(5),
	GROUPCODE NVARCHAR(15),
	GROUPNAME NVARCHAR(500),	
	ACCTCODE NVARCHAR(15),
	ACCTNAME NVARCHAR(500),
	OPBLDR DECIMAL(18,2),                              
	OPBLCR DECIMAL(18,2),
	PREVDR DECIMAL(18,2),                              
	PREVCR DECIMAL(18,2),
	CURRDR DECIMAL(18,2),                              
	CURRCR DECIMAL(18,2),
	CLBLDR DECIMAL(18,2),                              
	CLBLCR DECIMAL(18,2)	
	) 

INSERT INTO #TRANSLOG_REPORT	
SELECT	SEQ,
		GROUPCODE,GROUPNAME,
		ACCTCODE,ACCTNAME,
		OPBLDR,OPBLCR,
		PREVDR,PREVCR,
		CURRDR,CURRCR,
		CLBLDR, CLBLCR
FROM	#TRANSLOG_FINAL

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		GROUPCODE,GROUPNAME,
		'  Total',
		'  ',
		SUM(OPBLDR), SUM(OPBLCR),
		SUM(PREVDR), SUM(PREVCR),
		SUM(CURRDR), SUM(CURRCR),
		SUM(CLBLDR), SUM(CLBLCR)
FROM	#TRANSLOG_FINAL
GROUP BY GROUPCODE,GROUPNAME

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		GROUPCODE,GROUPNAME,
		'',NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL
FROM	#TRANSLOG_FINAL
GROUP BY GROUPCODE,GROUPNAME

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		'ZZZZZZZ','ZZZZZZZ',
		'','GRAND TOTAL',
		SUM(OPBLDR), SUM(OPBLCR),
		SUM(PREVDR), SUM(PREVCR),
		SUM(CURRDR), SUM(CURRCR),
		SUM(CLBLDR), SUM(CLBLCR)
FROM	#TRANSLOG_FINAL

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		'ZZZZZZZ','ZZZZZZZ',
		'',NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL
--FROM	#TRANSLOG_FINAL

SELECT  'Group' = CASE WHEN ACCTCODE = '  TOTAL' THEN GROUPNAME ELSE '' END,
		'Code' = CASE WHEN ACCTCODE = '  TOTAL' THEN '' ELSE ACCTCODE END, 
		'Particular' = CASE WHEN ACCTCODE = '  TOTAL' THEN '  TOTAL' ELSE ACCTNAME END, 
		OPBLDR 'Opening Bal. Dr.',
		OPBLCR 'Opening Bal. Cr.',
		PREVDR 'Previous Dr.',
		PREVCR 'Previous Cr.',
		CURRDR 'Current Dr.',
		CURRCR 'Current Cr.',
		CLBLDR 'Closing Bal. Dr.', 
		CLBLCR 'Closing Bal. Cr.'
FROM	#TRANSLOG_REPORT
--where GROUPCODE='AAAA' and ACCTNAME is not null
ORDER BY GROUPNAME,ACCTNAME


DECLARE @HEADER NVARCHAR(1000), @STRCMP NVARCHAR(100), @PREV NVARCHAR(200)

SELECT	DISTINCT TOP 1 @STRCMP = CMP_NAME
FROM	CMP_ADDRESS
WHERE   CMP_CODE=@COMPANYCODE

SELECT TOP 1 @STRCMP = @STRCMP + ' ' + CITYNAME FROM CITY WHERE CITYCODE1=@CITYCODE

IF @FIN_DATE_START = CONVERT(VARCHAR,DATEADD(D,0,(DBO.CONVERTDATE_IN_US(@USR_DATE_START,'/'))),103)
	SET @PREV = 'Previous Total N/A'
ELSE
	SET @PREV = 'Previous Total From:  ' +  @FIN_DATE_START + ' To: ' + CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
	
SET @HEADER =	'<b>' + @STRCMP + ' </b><BR><BR>' +
				'Financial Year ' + @FIN_DATE_START + ' - ' + @FIN_DATE_END + ' <BR>' + 
				'Opening Balance as on ' + @FIN_DATE_START + ' <BR>' +
				@PREV + ' <BR>' +
				'Current Total From: ' + @USR_DATE_START + ' To: ' + @USR_DATE_END  + ' <BR>' + 
				'Trial Balance Report Generated On ' + CONVERT(VARCHAR,GETDATE(),103) + ' ' + CONVERT(VARCHAR,GETDATE(),108) + ' <BR><BR>' + ''
				
SELECT @HEADER 'HEADER'



GO


ALTER PROCEDURE [dbo].[USP_ACCT_RPT_TRIALBALANCE_DATEWISE_ALL] --'1-APR-2006', '31-MAR-2007', '01', '101'                 
--DECLARE                
@USR_DATE_START NVARCHAR(12),    
@USR_DATE_END NVARCHAR(12),
@FIN_DATE_START NVARCHAR(12),                              
@FIN_DATE_END NVARCHAR(12),                              
@COMPANYCODE NVARCHAR(2)
AS /*  
SET @USR_DATE_START = '01/04/2009'
SET @USR_DATE_END	= '31/03/2010'
SET @FIN_DATE_START = '01/04/2009'                          
SET @FIN_DATE_END	= '31/03/2010'                          
SET @COMPANYCODE	= '01'     
--  */           
DECLARE @FDATE NVARCHAR(10),
		@TDATE NVARCHAR(10),
		@OPBALST NVARCHAR(20),
		@OPBALTABLE VARCHAR(100),
		@CMPCITYCODE NVARCHAR(5),
		@USR_DATE_START_LAST NVARCHAR(10),
		@USR_DATE_START_FIRST NVARCHAR(10)

SET @OPBALST =	SUBSTRING(@FIN_DATE_START,1,2) +  SUBSTRING(@FIN_DATE_START,4,2) + SUBSTRING(@FIN_DATE_START,7,4) +
				SUBSTRING(@FIN_DATE_END,1,2) +  SUBSTRING(@FIN_DATE_END,4,2) + SUBSTRING(@FIN_DATE_END,8,3)

SET @OPBALTABLE='TBL_MASTER_'+ @OPBALST +'_ALLGL'      

SET @FDATE = SUBSTRING(@FIN_DATE_START,7,4) +  SUBSTRING(@FIN_DATE_START,4,2) + SUBSTRING(@FIN_DATE_START,1,2)
SET @TDATE = SUBSTRING(@USR_DATE_END,7,4) +  SUBSTRING(@USR_DATE_END,4,2) + SUBSTRING(@USR_DATE_END,1,2)

SET @USR_DATE_START_LAST = CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
SET @USR_DATE_START_LAST = SUBSTRING(@USR_DATE_START_LAST,7,4) +  SUBSTRING(@USR_DATE_START_LAST,4,2) + SUBSTRING(@USR_DATE_START_LAST,1,2)
SET @USR_DATE_START_FIRST = SUBSTRING(@USR_DATE_START,7,4) +  SUBSTRING(@USR_DATE_START,4,2) + SUBSTRING(@USR_DATE_START,1,2)
SET @CMPCITYCODE = @COMPANYCODE --+ @CITYCODE




--SELECT @OPBALTABLE, @FDATE, @TDATE, @CMPCITYCODE, @USR_DATE_START_LAST
---/*
--////////////////////////////////                                 
IF OBJECT_ID('TEMPDB..#TRANSLOG') IS NOT NULL   
	DROP TABLE #TRANSLOG
/* CREAT TABLE WHERE CLIENT ID'S WILL BE THERE AND HIS TOTAL DEBIT AND TOTAL CREDIT */                              
CREATE TABLE #TRANSLOG(                              
	TRANSTYPE NVARCHAR(3), 
	TRANSCODE NVARCHAR(15),
	TRANSDATE NVARCHAR(12),
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                               
	CRAMT DECIMAL(18,2)                              
)                                
/* STEP 1: STANDARD INVOICE ONLY CREDIT ALL CHARGES                              
CLIENT A/C          DR   XXXX.XX                              
CHARGES A/C                      XXXX.XXX                              

*/                                
INSERT INTO #TRANSLOG                        
SELECT	'1II',                        
		INV_NO,     
		INV_DATE,                   
		INV_CLIENT,                         
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) FROM ACC_INVCHARGE  WHERE ACC_INVCHARGE.INV_NO = ACC_INVOICE.INV_NO) +
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) FROM ACC_INVCHARGE1 WHERE ACC_INVCHARGE1.INV_NO = ACC_INVOICE.INV_NO),
		0
FROM	ACC_INVOICE WITH(READPAST)                      
WHERE   [DBO].[RPT_YYYYMMDD](INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(INV_NO,1,5)  = @CMPCITYCODE             

INSERT INTO #TRANSLOG  
SELECT	'2II',                    
		ACC_INVOICE.INV_NO, 
		ACC_INVOICE.INV_DATE,
		ACC_INVCHARGE.INV_ACCOUNT,                    
		0,                     
		CONVERT(FLOAT,ACC_INVCHARGE.INV_INRAMT) 
FROM	ACC_INVCHARGE WITH(READPAST)                     
		LEFT OUTER JOIN ACC_INVOICE ON ACC_INVOICE.INV_NO =  ACC_INVCHARGE.INV_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_INVOICE.INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_INVOICE.INV_NO,1,2)  = @CMPCITYCODE 
		AND ACC_INVCHARGE.INV_INRAMT <> '0'   

INSERT INTO #TRANSLOG  
SELECT	'2II',                    
		ACC_INVOICE.INV_NO, 
		ACC_INVOICE.INV_DATE,
		ACC_INVCHARGE.INV_ACCOUNT,                    
		0,                     
		CONVERT(FLOAT,ACC_INVCHARGE.INV_INRAMT) 
FROM	ACC_INVCHARGE1 ACC_INVCHARGE WITH(READPAST)
		LEFT OUTER JOIN ACC_INVOICE ON ACC_INVOICE.INV_NO =  ACC_INVCHARGE.INV_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_INVOICE.INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_INVOICE.INV_NO,1,2)  = @CMPCITYCODE 
		AND ACC_INVCHARGE.INV_INRAMT <> '0'   

--////////////////////////////////////////                    
/* STEP 2: CASH BOOK MAIN TABLE   */                               
INSERT INTO #TRANSLOG                              
SELECT	'2' + ACC_BANK.STATUS,                              
		ACC_BANK.ENTRYNO, 
		ACC_BANK.ENTRYDT,                              
		OURBANK,                              
		DRAMT = CASE  ACC_BANK.STATUS                               
					WHEN 'BR' THEN CONVERT (FLOAT, ACTUALAMOUNT)                              
					WHEN 'CR' THEN CONVERT (FLOAT, ACTUALAMOUNT)                                
					WHEN 'BP' THEN 0                              
					WHEN 'CP' THEN 0                              
					WHEN 'CE' THEN 0 END,                               
		CRAMT = CASE  ACC_BANK.STATUS                               
					WHEN 'BP' THEN CONVERT (FLOAT, ACTUALAMOUNT)                              
					WHEN 'CP' THEN CONVERT (FLOAT, ACTUALAMOUNT)                                
					WHEN 'BR' THEN 0                              
					WHEN 'CR' THEN 0                              
					WHEN 'CE' THEN CONVERT (FLOAT, ACTUALAMOUNT)                              
					END                              
FROM	ACC_BANK WITH(READPAST)                               
		LEFT OUTER JOIN DBO.GENACCT_MASTER ON ACC_BANK.OURBANK = DBO.GENACCT_MASTER.ACCTCODE                              
WHERE	[DBO].[RPT_YYYYMMDD](ACC_BANK.ENTRYDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BANK.ENTRYNO,1,2)  = @CMPCITYCODE 

/* STEP 3: CASH BOOK CHILD TABLE */                              
INSERT INTO #TRANSLOG                              
SELECT	'2' + ACC_BANK.STATUS AS 'TRANSTYPE' , 
		ACC_BANKDTLS.ENTRYNO 'TRANSCODE',                      
		ACC_BANK.ENTRYDT,       
		CLIENT 'ACCODE',                              
		DRAMT = CASE  ACC_BANK.STATUS                               
					WHEN 'BR' THEN CONVERT (FLOAT, DEDUCTION)                              
					WHEN 'CR' THEN CONVERT (FLOAT, DEDUCTION)                                
					WHEN 'BP' THEN CONVERT (FLOAT, AMOUNT)                              
					WHEN 'CP' THEN CONVERT (FLOAT, AMOUNT)                              
					WHEN 'CE' THEN CONVERT (FLOAT, AMOUNT)                              
					END,                            
		CRAMT = CASE  ACC_BANK.STATUS                               
			WHEN 'BP' THEN CONVERT (FLOAT, DEDUCTION)                              
			WHEN 'CP' THEN CONVERT (FLOAT, DEDUCTION)                                
			WHEN 'BR' THEN CONVERT (FLOAT, AMOUNT)                              
			WHEN 'CR' THEN CONVERT (FLOAT, AMOUNT)                              
			WHEN 'CP' THEN 0                                
			END                              
FROM	ACC_BANKDTLS WITH(READPAST)                               
		INNER JOIN ACC_BANK ON ACC_BANK.ENTRYNO =  ACC_BANKDTLS.ENTRYNO                                
WHERE   [DBO].[RPT_YYYYMMDD](ACC_BANK.ENTRYDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BANK.ENTRYNO,1,2)  = @CMPCITYCODE

/* STEP 4: JOURNAL VOUCHER TABLE */                              
INSERT INTO #TRANSLOG   
SELECT	'3JV' AS 'TRANSTYPE',                               
		ACC_JOURNALVOUCDTLS.JVCODE 'TRANSCODE',
		ACC_JOURNALVOUC.JV_DATE,                              
		JV_ACCOUNT 'ACCODE',                               
		CONVERT (FLOAT, JV_DEBIT)'DRAMT',                               
		CONVERT (FLOAT, JV_CREDIT) 'CRAMT'                        
FROM	ACC_JOURNALVOUCDTLS WITH(READPAST)                               
		INNER JOIN ACC_JOURNALVOUC ON ACC_JOURNALVOUC.JVCODE = ACC_JOURNALVOUCDTLS.JVCODE                               
WHERE	[DBO].[RPT_YYYYMMDD](ACC_JOURNALVOUC.JV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_JOURNALVOUC.JVCODE,1,5)  = @CMPCITYCODE
		
/* STEP 5: CREDIT NOTE TABLE */               
INSERT INTO #TRANSLOG                        
SELECT	'4CN' TRANSTYPE,                        
		ACC_CREDITNOTE.CRT_NO 'TRANSCODE',  
		ACC_CREDITNOTE.CRT_DATE,                      
		ACC_CREDITNOTE.CRT_CLIENT 'CLIENTCODE',                         
		0 'DRAMT',                        
		CONVERT(FLOAT,ISNULL(TOTALAMT,0))                      
		'CRAMT'                        
FROM	ACC_CREDITNOTE WITH(READPAST)                        
WHERE   [DBO].[RPT_YYYYMMDD](ACC_CREDITNOTE.CRT_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_CREDITNOTE.CRT_NO,1,2)  = @CMPCITYCODE

INSERT INTO #TRANSLOG            
SELECT	'4CN' AS 'TRANSTYPE',                    
		ACC_CREDITNOTE.CRT_NO 'TRANSCODE',   
		ACC_CREDITNOTE.CRT_DATE,                 
		ACC_CRTCHARGE.CRT_ACCOUNT 'CLIENTCODE',
		CONVERT(FLOAT,ISNULL(ACC_CRTCHARGE.CRT_INRAMT,0)) 'DRAMT',                     
		0 'CRAMT'                    
FROM	ACC_CRTCHARGE  WITH(READPAST)                    
		LEFT OUTER JOIN ACC_CREDITNOTE ON ACC_CREDITNOTE.CRT_NO =  ACC_CRTCHARGE.CRT_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_CREDITNOTE.CRT_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_CREDITNOTE.CRT_NO,1,2)  = @CMPCITYCODE
		AND ACC_CRTCHARGE.CRT_INRAMT <> '0' 

INSERT INTO #TRANSLOG            
SELECT  '4CN' AS 'TRANSTYPE',                    
		ACC_CREDITNOTE.CRT_NO 'TRANSCODE',    
		ACC_CREDITNOTE.CRT_DATE,		                
		ACC_CRTCHARGE1.CRT_ACCOUNT 'CLIENTCODE',
		CONVERT(FLOAT,ISNULL(ACC_CRTCHARGE1.CRT_INRAMT,0)) 'DRAMT',                     
		0 'CRAMT'                    
FROM	ACC_CRTCHARGE1   WITH(READPAST)                   
		LEFT OUTER JOIN ACC_CREDITNOTE ON ACC_CREDITNOTE.CRT_NO =  ACC_CRTCHARGE1.CRT_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_CREDITNOTE.CRT_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_CREDITNOTE.CRT_NO,1,2)  = @CMPCITYCODE
		AND ACC_CRTCHARGE1.CRT_INRAMT <> '0' 

--////////////////////////////////////////                          

/* STEP 6: STORAGE INVOICE */                              
INSERT INTO #TRANSLOG                              
SELECT	'6SI' TRANSTYPE,                              
		BILLNO 'TRANSCODE',
		ACC_STORAGE.BILLDT,                              
		CLIENT 'CLIENTCODE',            
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(AMOUNT,0))) ,0)                              
FROM	ACC_STOREDTLS    WITH(READPAST)                            
WHERE	ACC_STOREDTLS.BILLNO = ACC_STORAGE.BILLNO) 'DRAMT',                              
		0 'CRAMT'                              
FROM	ACC_STORAGE                          
WHERE	[DBO].[RPT_YYYYMMDD](ACC_STORAGE.BILLDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_STORAGE.BILLNO,1,2)  = @CMPCITYCODE

INSERT INTO #TRANSLOG                                
SELECT  '6SI' AS TRANSTYPE, 
		ACC_STOREDTLS.BILLNO AS TRANSCODE,
		ACC_STORAGE.BILLDT, 
		ACC_STOREDTLS.ACCOUNT AS CLIENTCODE, 
		0 AS DRAMT,             
		ACC_STOREDTLS.AMOUNT AS CRAMT            
FROM	ACC_STORAGE  WITH(READPAST)
		INNER JOIN DBO.ACC_STOREDTLS ON DBO.ACC_STORAGE.BILLNO = DBO.ACC_STOREDTLS.BILLNO            
WHERE	[DBO].[RPT_YYYYMMDD](ACC_STORAGE.BILLDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_STORAGE.BILLNO,1,2)  = @CMPCITYCODE
		
/* STEP 7: BROKERAGE INVOICE */                              

INSERT INTO #TRANSLOG                              
SELECT	'7BI' TRANSTYPE,                              
		ACC_BROKERAGE.BROK_NO 'TRANSCODE',
		ACC_BROKERAGE.BROK_DT,                              
		BROK_EXPCODE 'CLIENTCODE',                               
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(BRKAMT,0))) ,0) FROM ACC_BRKGDTL WHERE  ACC_BROKERAGE.BROK_NO = ACC_BRKGDTL.BROK_NO) 'DRAMT',                              
		0 'CRAMT'                              
FROM	ACC_BROKERAGE  WITH(READPAST)                             
WHERE	[DBO].[RPT_YYYYMMDD](ACC_BROKERAGE.BROK_DT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BROKERAGE.BROK_NO,1,2)  = @CMPCITYCODE
-- /////////////////////////////////////            

INSERT INTO #TRANSLOG                              
SELECT	'7BI' AS TRANSTYPE,
		DBO.ACC_BROKERAGE.BROK_NO AS TRANSCODE,
		ACC_BROKERAGE.BROK_DT,
		DBO.ACC_BRKGDTL.BRKACCOUNT AS CLIENTCODE,
		0 AS DRAMT,             
		--DBO.ACC_BRKGDTL.BRKAMT AS CRAMT            
		CONVERT(FLOAT,ISNULL(BRKAMT,0)) AS CRAMT            
FROM    DBO.ACC_BROKERAGE  WITH(READPAST)
		INNER JOIN DBO.ACC_BRKGDTL ON DBO.ACC_BROKERAGE.BROK_NO = DBO.ACC_BRKGDTL.BROK_NO                              
WHERE	[DBO].[RPT_YYYYMMDD](ACC_BROKERAGE.BROK_DT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BROKERAGE.BROK_NO,1,2)  = @CMPCITYCODE
--/////////////////////////////////////            


/* STEP 8: PURCHASE INVOICE - MAIN TABLE */                              

INSERT INTO #TRANSLOG                              
SELECT	'1PI' TRANSTYPE,                              
		PUR_CODE 'TRANSCODE',
		ACC_PURCHASE.PUR_DATE,                              
		PUR_SUPPLIER 'CLIENTCODE',                               
		0 'DRAMT',                              
		TOTALAMT 'CRAMT'                              
FROM	ACC_PURCHASE   WITH(READPAST)                            
WHERE	[DBO].[RPT_YYYYMMDD](ACC_PURCHASE.PUR_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_PURCHASE.PUR_CODE,1,2)  = @CMPCITYCODE

INSERT INTO #TRANSLOG            
SELECT	'2PI' AS TRANSTYPE,            
		DBO.ACC_PURCHASEDTLS.PUR_CODE AS 'TRANSCODE',       
		ACC_PURCHASE.PUR_DATE,       
		DBO.ACC_PURCHASEDTLS.PUR_ACCOUNT AS CLIENTCODE,             
		CONVERT(NUMERIC(18,2),DBO.ACC_PURCHASEDTLS.PUR_AMOUNT) AS DRAMT,--- CONVERT(NUMERIC(18,2),DBO.ACC_PURCHASEDTLS.PUR_DEDUCTION)  AS DRAMT,                     
		CONVERT(NUMERIC(18,2),DBO.ACC_PURCHASEDTLS.PUR_DEDUCTION) AS CRAMT        
FROM    DBO.ACC_PURCHASE WITH(READPAST)
		INNER JOIN DBO.ACC_PURCHASEDTLS ON DBO.ACC_PURCHASE.PUR_CODE = DBO.ACC_PURCHASEDTLS.PUR_CODE            
WHERE	[DBO].[RPT_YYYYMMDD](ACC_PURCHASE.PUR_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_PURCHASE.PUR_CODE,1,2)  = @CMPCITYCODE      

--*/ 
-- /*
-----------------------------            
-- 
--SELECT *  FROM #TRANSLOG
IF OBJECT_ID('TEMPDB..#TRANSLOG_UNDERGRP') IS NOT NULL   
	DROP TABLE #TRANSLOG_UNDERGRP
	
CREATE TABLE #TRANSLOG_UNDERGRP(
	CODE NVARCHAR(15),
	NAME NVARCHAR(500)
)
DECLARE @OPBALTEXT NVARCHAR(4000) 
SET @OPBALTEXT ='
INSERT INTO #TRANSLOG_UNDERGRP
SELECT CODE, NAME FROM ' + @OPBALTABLE + ' WHERE CODE LIKE ' + CHAR(39) + 'M%' + CHAR(39) + ''
--PRINT(@OPBALTEXT)
EXEC(@OPBALTEXT)

IF OBJECT_ID('TEMPDB..#TRANSLOG_OPBAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_OPBAL

DECLARE @CMPCITYCODEOP NVARCHAR(500)
SET @CMPCITYCODEOP = ''
SELECT	@CMPCITYCODEOP = @CMPCITYCODEOP + 'ISNULL([' + CMP_CODE + CMP_CTYCODE + 'OP],0) + ' 
FROM	CMP_ADDRESS 
WHERE	CMP_CODE= @CMPCITYCODE 
		AND ACTIVECMP=1
		AND CMP_CTYCODE <> '108'
		
SET @CMPCITYCODEOP = SUBSTRING(@CMPCITYCODEOP,1,LEN(@CMPCITYCODEOP)-2)

--SELECT @CMPCITYCODEOP
CREATE TABLE #TRANSLOG_OPBAL (
	ACCTCODE NVARCHAR(15),
	OPBAL DECIMAL(18,2),
	OPBALDR DECIMAL(18,2),
	OPBALCR DECIMAL(18,2),
)
--DECLARE @OPBALTEXT NVARCHAR(4000) 
SET @OPBALTEXT ='
INSERT INTO #TRANSLOG_OPBAL
SELECT	CODE,
		(' + @CMPCITYCODEOP + '), 
		0,
		0
FROM	'+ @OPBALTABLE +''
--PRINT(@OPBALTEXT)  
EXEC(@OPBALTEXT)              

UPDATE #TRANSLOG_OPBAL
	SET OPBALDR = CASE WHEN OPBAL >= 0 THEN OPBAL ELSE 0 END,
		OPBALCR = CASE WHEN OPBAL < 0 THEN ABS(OPBAL) ELSE 0 END

--SELECT * FROM #TRANSLOG_OPBAL

/* COLLECTION OF ALL ACCOUNT FROM TRANSACTION LOG AND OPENING BALANCE*/
IF OBJECT_ID('TEMPDB..#TRANSLOG_ACCOUNT') IS NOT NULL   
	DROP TABLE #TRANSLOG_ACCOUNT
	
CREATE TABLE #TRANSLOG_ACCOUNT(                      
		ACCTCODE NVARCHAR(15),
		ACCTNAME NVARCHAR(500),
		GROUPCODE NVARCHAR(100)
		) 

INSERT	INTO #TRANSLOG_ACCOUNT	
SELECT	DISTINCT #TRANSLOG.ACCTCODE,
		ISNULL(LTRIM(RTRIM(EXP_MASTER.EXP_NAME)),'') +  ISNULL(LTRIM(RTRIM(SUPPLIER_MASTER.SUP_NAME)),'') +   ISNULL(LTRIM(RTRIM(GENACCT_MASTER.ACCTNAME)),'') AS ACCNAME,
		CASE WHEN GENACCT_MASTER.ACCTNAME IS NOT NULL THEN UNDERGROUP
			WHEN EXP_MASTER.EXP_NAME IS NOT NULL THEN 'M000028'
			WHEN SUPPLIER_MASTER.SUP_NAME IS NOT NULL THEN 'M000029' ELSE '' END
FROM	#TRANSLOG 
		LEFT OUTER JOIN DBO.EXP_MASTER ON #TRANSLOG.ACCTCODE = DBO.EXP_MASTER.EXP_CODE
		LEFT OUTER JOIN DBO.SUPPLIER_MASTER ON #TRANSLOG.ACCTCODE = DBO.SUPPLIER_MASTER.SUP_CODE
		LEFT OUTER JOIN DBO.GENACCT_MASTER ON #TRANSLOG.ACCTCODE = DBO.GENACCT_MASTER.ACCTCODE

INSERT INTO #TRANSLOG_ACCOUNT
SELECT	DISTINCT #TRANSLOG_OPBAL.ACCTCODE,
		ISNULL(LTRIM(RTRIM(EXP_MASTER.EXP_NAME)),'') +  ISNULL(LTRIM(RTRIM(SUPPLIER_MASTER.SUP_NAME)),'') +   ISNULL(LTRIM(RTRIM(GENACCT_MASTER.ACCTNAME)),'') AS ACCNAME,
		CASE WHEN GENACCT_MASTER.ACCTNAME IS NOT NULL THEN UNDERGROUP
			WHEN EXP_MASTER.EXP_NAME IS NOT NULL THEN 'M000028'
			WHEN SUPPLIER_MASTER.SUP_NAME IS NOT NULL THEN 'M000029' ELSE '' END                          
FROM	#TRANSLOG_OPBAL 
		LEFT OUTER JOIN DBO.EXP_MASTER ON #TRANSLOG_OPBAL.ACCTCODE = DBO.EXP_MASTER.EXP_CODE
		LEFT OUTER JOIN DBO.SUPPLIER_MASTER ON #TRANSLOG_OPBAL.ACCTCODE = DBO.SUPPLIER_MASTER.SUP_CODE
		LEFT OUTER JOIN DBO.GENACCT_MASTER ON #TRANSLOG_OPBAL.ACCTCODE = DBO.GENACCT_MASTER.ACCTCODE
WHERE	#TRANSLOG_OPBAL.ACCTCODE NOT IN (SELECT #TRANSLOG_ACCOUNT.ACCTCODE FROM #TRANSLOG_ACCOUNT)
--GROUP BY ACCTCODE                              
--SELECT * FROM #TRANSLOG_ACCOUNT

IF OBJECT_ID('TEMPDB..#TRANSLOG_PREV') IS NOT NULL   
	DROP TABLE #TRANSLOG_PREV
	
CREATE TABLE #TRANSLOG_PREV(                      
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                              
	CRAMT DECIMAL(18,2)) 
INSERT INTO #TRANSLOG_PREV	
SELECT	ACCTCODE,                               
		ISNULL(SUM(ISNULL(DRAMT,0)),0) DRAMT,                               
		ISNULL(SUM(ISNULL(CRAMT,0)),0) CRAMT                              
FROM	#TRANSLOG 
WHERE	[DBO].[RPT_YYYYMMDD](TRANSDATE) BETWEEN @FDATE AND @USR_DATE_START_LAST
GROUP BY ACCTCODE                              

IF OBJECT_ID('TEMPDB..#TRANSLOG_CURR') IS NOT NULL   
	DROP TABLE #TRANSLOG_CURR
	
CREATE TABLE #TRANSLOG_CURR(                      
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                              
	CRAMT DECIMAL(18,2)) 
INSERT INTO #TRANSLOG_CURR
SELECT	ACCTCODE,                               
		ISNULL(SUM(ISNULL(DRAMT,0)),0) DRAMT,                               
		ISNULL(SUM(ISNULL(CRAMT,0)),0) CRAMT                              
FROM	#TRANSLOG 
WHERE	[DBO].[RPT_YYYYMMDD](TRANSDATE) BETWEEN @USR_DATE_START_FIRST AND @TDATE
GROUP BY ACCTCODE                              
-- */
--SELECT * FROM #TRANSLOG_UNDERGRP
--SELECT * FROM #TRANSLOG_OPBAL
--SELECT * FROM #TRANSLOG_PREV
--SELECT * FROM #TRANSLOG_CURR
--SELECT * FROM #TRANSLOG_ACCOUNT

IF OBJECT_ID('TEMPDB..#TRANSLOG_FINAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_FINAL

CREATE TABLE #TRANSLOG_FINAL(
	SEQ NVARCHAR(5),
	GROUPCODE NVARCHAR(15),
	GROUPNAME NVARCHAR(500),	
	ACCTCODE NVARCHAR(15),
	ACCTNAME NVARCHAR(500),
	OPBLDR DECIMAL(18,2),                              
	OPBLCR DECIMAL(18,2),
	PREVDR DECIMAL(18,2),                              
	PREVCR DECIMAL(18,2),
	CURRDR DECIMAL(18,2),                              
	CURRCR DECIMAL(18,2),
	CLBLDR DECIMAL(18,2),                              
	CLBLCR DECIMAL(18,2)	
	) 

INSERT INTO #TRANSLOG_FINAL
SELECT	'000',
		GROUPCODE = CASE WHEN LEN(GROUPCODE) =0 THEN 'AAAA' ELSE GROUPCODE END, 
		GROUPNAME = ISNULL((SELECT NAME FROM #TRANSLOG_UNDERGRP WHERE #TRANSLOG_UNDERGRP.CODE = GROUPCODE),'  Non Group'),
		ACCTCODE, 
		ACCTNAME,		
		OPBLDR = ISNULL((SELECT OPBALDR FROM #TRANSLOG_OPBAL WHERE #TRANSLOG_OPBAL.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		OPBLCR = ISNULL((SELECT OPBALCR FROM #TRANSLOG_OPBAL WHERE #TRANSLOG_OPBAL.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		PREVDR = ISNULL((SELECT DRAMT FROM #TRANSLOG_PREV WHERE #TRANSLOG_PREV.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		PREVCR = ISNULL((SELECT CRAMT FROM #TRANSLOG_PREV WHERE #TRANSLOG_PREV.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		CURRDR = ISNULL((SELECT DRAMT FROM #TRANSLOG_CURR WHERE #TRANSLOG_CURR.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		CURRCR = ISNULL((SELECT CRAMT FROM #TRANSLOG_CURR WHERE #TRANSLOG_CURR.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		0,
		0
FROM	#TRANSLOG_ACCOUNT
WHERE	ACCTCODE NOT LIKE  'M%'
ORDER BY ACCTNAME


UPDATE	#TRANSLOG_FINAL 
SET		CLBLDR = CASE WHEN (OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR)) >= 0 THEN (OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR)) ELSE 0 END,
		CLBLCR = CASE WHEN (OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR)) < 0 THEN ABS((OPBLDR - OPBLCR) + ((PREVDR + CURRDR) - (PREVCR + CURRCR))) ELSE 0 END

IF OBJECT_ID('TEMPDB..#TRANSLOG_REPORT') IS NOT NULL   
	DROP TABLE #TRANSLOG_REPORT

CREATE TABLE #TRANSLOG_REPORT(
	SEQ NVARCHAR(5),
	GROUPCODE NVARCHAR(15),
	GROUPNAME NVARCHAR(500),	
	ACCTCODE NVARCHAR(15),
	ACCTNAME NVARCHAR(500),
	OPBLDR DECIMAL(18,2),                              
	OPBLCR DECIMAL(18,2),
	PREVDR DECIMAL(18,2),                              
	PREVCR DECIMAL(18,2),
	CURRDR DECIMAL(18,2),                              
	CURRCR DECIMAL(18,2),
	CLBLDR DECIMAL(18,2),                              
	CLBLCR DECIMAL(18,2)	
	) 

INSERT INTO #TRANSLOG_REPORT	
SELECT	SEQ,
		GROUPCODE,GROUPNAME,
		ACCTCODE,ACCTNAME,
		OPBLDR,OPBLCR,
		PREVDR,PREVCR,
		CURRDR,CURRCR,
		CLBLDR, CLBLCR
FROM	#TRANSLOG_FINAL

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		GROUPCODE,GROUPNAME,
		'  Total',
		'  ',
		SUM(OPBLDR), SUM(OPBLCR),
		SUM(PREVDR), SUM(PREVCR),
		SUM(CURRDR), SUM(CURRCR),
		SUM(CLBLDR), SUM(CLBLCR)
FROM	#TRANSLOG_FINAL
GROUP BY GROUPCODE,GROUPNAME

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		GROUPCODE,GROUPNAME,
		'',NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL
FROM	#TRANSLOG_FINAL
GROUP BY GROUPCODE,GROUPNAME

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		'ZZZZZZZ','ZZZZZZZ',
		'','GRAND TOTAL',
		SUM(OPBLDR), SUM(OPBLCR),
		SUM(PREVDR), SUM(PREVCR),
		SUM(CURRDR), SUM(CURRCR),
		SUM(CLBLDR), SUM(CLBLCR)
FROM	#TRANSLOG_FINAL

INSERT INTO #TRANSLOG_REPORT
SELECT	'',
		'ZZZZZZZ','ZZZZZZZ',
		'',NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL,
		NULL, NULL
--FROM	#TRANSLOG_FINAL

SELECT  'Group' = CASE WHEN ACCTCODE = '  TOTAL' THEN GROUPNAME ELSE '' END,
		'Code' = CASE WHEN ACCTCODE = '  TOTAL' THEN '' ELSE ACCTCODE END, 
		'Particular' = CASE WHEN ACCTCODE = '  TOTAL' THEN '  TOTAL' ELSE ACCTNAME END, 
		OPBLDR 'Opening Bal. Dr.',
		OPBLCR 'Opening Bal. Cr.',
		PREVDR 'Previous Dr.',
		PREVCR 'Previous Cr.',
		CURRDR 'Current Dr.',
		CURRCR 'Current Cr.',
		CLBLDR 'Closing Bal. Dr.', 
		CLBLCR 'Closing Bal. Cr.'
FROM	#TRANSLOG_REPORT
--where GROUPCODE='AAAA' and ACCTNAME is not null
ORDER BY GROUPNAME,ACCTNAME


DECLARE @HEADER NVARCHAR(1000), @STRCMP NVARCHAR(100), @PREV NVARCHAR(200)

SELECT	DISTINCT TOP 1 @STRCMP = CMP_NAME
FROM	CMP_ADDRESS
WHERE   CMP_CODE=@COMPANYCODE

--SELECT TOP 1 @STRCMP = @STRCMP + ' ' + CITYNAME FROM CITY WHERE CITYCODE1=@CITYCODE

IF @FIN_DATE_START = CONVERT(VARCHAR,DATEADD(D,0,(DBO.CONVERTDATE_IN_US(@USR_DATE_START,'/'))),103)
	SET @PREV = 'Previous Total N/A'
ELSE
	SET @PREV = 'Previous Total From:  ' +  @FIN_DATE_START + ' To: ' + CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
	
SET @HEADER =	'<b>' + @STRCMP + ' </b><BR><BR>' +

				'Financial Year ' + @FIN_DATE_START + ' - ' + @FIN_DATE_END + ' <BR>' + 
				'Opening Balance as on ' + @FIN_DATE_START + ' <BR>' +
				@PREV + ' <BR>' +
				'Current Total From: ' + @USR_DATE_START + ' To: ' + @USR_DATE_END  + ' <BR>' + 
				'Trial Balance Report Generated On ' + CONVERT(VARCHAR,GETDATE(),103) + ' ' + CONVERT(VARCHAR,GETDATE(),108) + ' <BR><BR>' + ''
				
SELECT @HEADER 'HEADER'



GO


ALTER PROCEDURE [dbo].[USP_ACCT_RPT_TRIALBALANCE_PROVISION]
--DECLARE   
--@FK_LOGID NVARCHAR(50),                               
@USR_DATE_START NVARCHAR(12),    
@USR_DATE_END NVARCHAR(12),
@FIN_DATE_START NVARCHAR(12),                              
@FIN_DATE_END NVARCHAR(12),                              
@COMPANYCODE NVARCHAR(2),                              
@CITYCODE NVARCHAR(3)

AS /*  
--SET @FK_LOGID = 337
--01-10-2010 TO 30-11-2010

SET @USR_DATE_START = '01/04/2010'
SET @USR_DATE_END	= '28/02/2011'
SET @FIN_DATE_START = '01/04/2010'                          
SET @FIN_DATE_END	= '31/03/2011'   
SET @COMPANYCODE	= '01'                           
SET @CITYCODE		= '101'    
--  */     
      
SET NOCOUNT ON

DECLARE @FDATE NVARCHAR(10),
		@TDATE NVARCHAR(10),
		@OPBALST NVARCHAR(20),
		@OPBALTABLE VARCHAR(100),
		@CMPCITYCODE NVARCHAR(5),
		@USR_DATE_START_LAST NVARCHAR(10),
		@USR_DATE_START_FIRST NVARCHAR(10),@DESC NVARCHAR(100)


SET @OPBALST =	SUBSTRING(@FIN_DATE_START,1,2) +  SUBSTRING(@FIN_DATE_START,4,2) + SUBSTRING(@FIN_DATE_START,7,4) +
				SUBSTRING(@FIN_DATE_END,1,2) +  SUBSTRING(@FIN_DATE_END,4,2) + SUBSTRING(@FIN_DATE_END,8,3)

SET @OPBALTABLE='TBL_MASTER_'+ @OPBALST +'_ALLGL'      

SET @FDATE = SUBSTRING(@FIN_DATE_START,7,4) +  SUBSTRING(@FIN_DATE_START,4,2) + SUBSTRING(@FIN_DATE_START,1,2)
SET @TDATE = SUBSTRING(@USR_DATE_END,7,4) +  SUBSTRING(@USR_DATE_END,4,2) + SUBSTRING(@USR_DATE_END,1,2)

SET @USR_DATE_START_LAST = CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
SET @USR_DATE_START_LAST = SUBSTRING(@USR_DATE_START_LAST,7,4) +  SUBSTRING(@USR_DATE_START_LAST,4,2) + SUBSTRING(@USR_DATE_START_LAST,1,2)
SET @USR_DATE_START_FIRST = SUBSTRING(@USR_DATE_START,7,4) +  SUBSTRING(@USR_DATE_START,4,2) + SUBSTRING(@USR_DATE_START,1,2)
SET @CMPCITYCODE = @COMPANYCODE + @CITYCODE

--SELECT  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) USR_DATE_START , 
--		[DBO].[RPT_YYYYMMDD](@USR_DATE_END) USR_DATE_END,
--		@USR_DATE_START_LAST USR_DATE_START_LAST,
--		@USR_DATE_START_LAST USR_DATE_START_LAST,
--		@USR_DATE_START_FIRST USR_DATE_START_FIRST

--SELECT @OPBALTABLE, @FDATE, @TDATE, @CMPCITYCODE, @USR_DATE_START_LAST
---/*
--////////////////////////////////                                 
IF OBJECT_ID('TEMPDB..#TRANSLOG') IS NOT NULL   
	DROP TABLE #TRANSLOG
/* CREAT TABLE WHERE CLIENT ID'S WILL BE THERE AND HIS TOTAL DEBIT AND TOTAL CREDIT */                              
CREATE TABLE #TRANSLOG(                              
	TRANSTYPE NVARCHAR(3), 
	TRANSCODE NVARCHAR(15),
	TRANSDATE NVARCHAR(12),
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                               
	CRAMT DECIMAL(18,2)                              
)                                
/* STEP 1: STANDARD INVOICE ONLY CREDIT ALL CHARGES                              
CLIENT A/C          DR   XXXX.XX                              
CHARGES A/C                      XXXX.XXX                              
*/                                
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM ACCOUNTS'
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM INVOICE'

INSERT INTO #TRANSLOG                        
SELECT	'1II',                        
		INV_NO,     
		INV_DATE,                   
		INV_CLIENT,                         
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) FROM ACC_INVCHARGE WITH(READPAST) WHERE ACC_INVCHARGE.INV_NO = ACC_INVOICE.INV_NO) +
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) FROM ACC_INVCHARGE1 WITH(READPAST) WHERE ACC_INVCHARGE1.INV_NO = ACC_INVOICE.INV_NO),
		0
FROM	ACC_INVOICE  WITH(READPAST)                        
WHERE   [DBO].[RPT_YYYYMMDD](INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(INV_NO,1,5)  = @CMPCITYCODE             
	
--	SET @DESC = 'NO. OF RECORD FOUND IN INVOICE -	' + CONVERT(VARCHAR,@@ROWCOUNT)------------COMPLETED INVOICE
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM INVOICE CHARGE 1' ------------STARTED INVOICE CHARGE                 
	

INSERT INTO #TRANSLOG  
SELECT	'2II',                    
		ACC_INVOICE.INV_NO, 
		ACC_INVOICE.INV_DATE,
		ACC_INVCHARGE.INV_ACCOUNT,                    
		0,                     
		CONVERT(FLOAT,ACC_INVCHARGE.INV_INRAMT) 
FROM	ACC_INVCHARGE   WITH(READPAST)                    
		LEFT OUTER JOIN ACC_INVOICE WITH(READPAST) ON ACC_INVOICE.INV_NO =  ACC_INVCHARGE.INV_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_INVOICE.INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_INVOICE.INV_NO,1,5)  = @CMPCITYCODE 
		AND ACC_INVCHARGE.INV_INRAMT <> '0'   

--	SET @DESC = 'NO. OF RECORDS FOUND IN INVOICE CHARGE 1 -' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM INVOICE CHARGE 2'

INSERT INTO #TRANSLOG  
SELECT	'2II',                    
		ACC_INVOICE.INV_NO, 
		ACC_INVOICE.INV_DATE,
		ACC_INVCHARGE.INV_ACCOUNT,                    
		0,                     
		CONVERT(FLOAT,ACC_INVCHARGE.INV_INRAMT) 
FROM	ACC_INVCHARGE1 ACC_INVCHARGE WITH(READPAST) 
		LEFT OUTER JOIN ACC_INVOICE WITH(READPAST) ON ACC_INVOICE.INV_NO =  ACC_INVCHARGE.INV_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_INVOICE.INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_INVOICE.INV_NO,1,5)  = @CMPCITYCODE 
		AND ACC_INVCHARGE.INV_INRAMT <> '0'   

--	SET @DESC = 'NO. OF RECORDS FOUND IN INVOICE CHARGE 2 -' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM CASH AND BANK BOOK'


--////////////////////////////////////////                    
/* STEP 2: CASH BOOK MAIN TABLE   */                               
INSERT INTO #TRANSLOG                              
SELECT	'2' + ACC_BANK.STATUS,                              
		ACC_BANK.ENTRYNO, 
		ACC_BANK.ENTRYDT,                              
		OURBANK,                              
		DRAMT = CASE  ACC_BANK.STATUS                               
					WHEN 'BR' THEN CONVERT (FLOAT, ACTUALAMOUNT)                              
					WHEN 'CR' THEN CONVERT (FLOAT, ACTUALAMOUNT)                                
					WHEN 'BP' THEN 0                              
					WHEN 'CP' THEN 0                              
					WHEN 'CE' THEN 0 END,                               
		CRAMT = CASE  ACC_BANK.STATUS                               
					WHEN 'BP' THEN CONVERT (FLOAT, ACTUALAMOUNT)                              
					WHEN 'CP' THEN CONVERT (FLOAT, ACTUALAMOUNT)                                
					WHEN 'BR' THEN 0                              
					WHEN 'CR' THEN 0                              
					WHEN 'CE' THEN CONVERT (FLOAT, ACTUALAMOUNT)                              
					END                              
FROM	ACC_BANK  WITH(READPAST)                               
		LEFT OUTER JOIN DBO.GENACCT_MASTER WITH(READPAST) ON ACC_BANK.OURBANK = DBO.GENACCT_MASTER.ACCTCODE                              
WHERE	[DBO].[RPT_YYYYMMDD](ACC_BANK.ENTRYDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BANK.ENTRYNO,1,5)  = @CMPCITYCODE 

--	SET @DESC = 'NO. OF RECORDS FOUND IN CASH AND BANK - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM CASH AND BANK BOOK DETAILS'


/* STEP 3: CASH BOOK CHILD TABLE */                              
INSERT INTO #TRANSLOG                              
SELECT	'2' + ACC_BANK.STATUS AS 'TRANSTYPE' , 
		ACC_BANKDTLS.ENTRYNO 'TRANSCODE',                      
		ACC_BANK.ENTRYDT,       
		CLIENT 'ACCODE',                              
		DRAMT = CASE  ACC_BANK.STATUS                               
					WHEN 'BR' THEN CONVERT (FLOAT, DEDUCTION)                              
					WHEN 'CR' THEN CONVERT (FLOAT, DEDUCTION)                                
					WHEN 'BP' THEN CONVERT (FLOAT, AMOUNT)                              
					WHEN 'CP' THEN CONVERT (FLOAT, AMOUNT)                              
					WHEN 'CE' THEN CONVERT (FLOAT, AMOUNT)                              
					END,                            
		CRAMT = CASE  ACC_BANK.STATUS                               
			WHEN 'BP' THEN CONVERT (FLOAT, DEDUCTION)                              
			WHEN 'CP' THEN CONVERT (FLOAT, DEDUCTION)                                
			WHEN 'BR' THEN CONVERT (FLOAT, AMOUNT)                              
			WHEN 'CR' THEN CONVERT (FLOAT, AMOUNT)                              
			WHEN 'CP' THEN 0                                
			END                              
FROM	ACC_BANKDTLS  WITH(READPAST)                               
		INNER JOIN ACC_BANK WITH(READPAST) ON ACC_BANK.ENTRYNO =  ACC_BANKDTLS.ENTRYNO                                
WHERE   [DBO].[RPT_YYYYMMDD](ACC_BANK.ENTRYDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BANK.ENTRYNO,1,5)  = @CMPCITYCODE

--	SET @DESC = 'NO. OF RECORDS FOUND IN CASH AND BANK DETAILS - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM JOURNAL VOUCHER'

/* STEP 4: JOURNAL VOUCHER TABLE */                              
INSERT INTO #TRANSLOG   
SELECT	'3JV' AS 'TRANSTYPE',                               
		ACC_JOURNALVOUCDTLS.JVCODE 'TRANSCODE',
		ACC_JOURNALVOUC.JV_DATE,                              
		JV_ACCOUNT 'ACCODE',                               
		CONVERT (FLOAT, JV_DEBIT)'DRAMT',                               
		CONVERT (FLOAT, JV_CREDIT) 'CRAMT'                        
FROM	ACC_JOURNALVOUCDTLS  WITH(READPAST)                               
		INNER JOIN ACC_JOURNALVOUC WITH(READPAST) ON ACC_JOURNALVOUC.JVCODE = ACC_JOURNALVOUCDTLS.JVCODE                               
WHERE	[DBO].[RPT_YYYYMMDD](ACC_JOURNALVOUC.JV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_JOURNALVOUC.JVCODE,1,5)  = @CMPCITYCODE

--	SET @DESC = 'NO. OF RECORDS FOUND IN JOURNAL VOUCHER - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM CREDIT NOTE'

		
/* STEP 5: CREDIT NOTE TABLE */               
INSERT INTO #TRANSLOG                        
SELECT	'4CN' TRANSTYPE,                        
		ACC_CREDITNOTE.CRT_NO 'TRANSCODE',  
		ACC_CREDITNOTE.CRT_DATE,                      
		ACC_CREDITNOTE.CRT_CLIENT 'CLIENTCODE',                         
		0 'DRAMT',                        
		CONVERT(FLOAT,ISNULL(TOTALAMT,0))                      
		'CRAMT'                        
FROM	ACC_CREDITNOTE  WITH(READPAST)                        
WHERE   [DBO].[RPT_YYYYMMDD](ACC_CREDITNOTE.CRT_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_CREDITNOTE.CRT_NO,1,5)  = @CMPCITYCODE

--	SET @DESC = 'NO. OF RECORDS FOUND IN CREDIT NOTE - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM CREDIT NOTE CHARGE 1'

INSERT INTO #TRANSLOG            
SELECT	'4CN' AS 'TRANSTYPE',                    
		ACC_CREDITNOTE.CRT_NO 'TRANSCODE',   
		ACC_CREDITNOTE.CRT_DATE,                 
		ACC_CRTCHARGE.CRT_ACCOUNT 'CLIENTCODE',
		CONVERT(FLOAT,ISNULL(ACC_CRTCHARGE.CRT_INRAMT,0)) 'DRAMT',                     
		0 'CRAMT'                    
FROM	ACC_CRTCHARGE  WITH(READPAST)                     
		LEFT OUTER JOIN ACC_CREDITNOTE WITH(READPAST) ON ACC_CREDITNOTE.CRT_NO =  ACC_CRTCHARGE.CRT_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_CREDITNOTE.CRT_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_CREDITNOTE.CRT_NO,1,5)  = @CMPCITYCODE
		AND ACC_CRTCHARGE.CRT_INRAMT <> '0' 

--	SET @DESC = 'NO. OF RECORDS FOUND IN CREDIT NOTE CHARGE 1 - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM CREDIT NOTE CHARGE 2'

INSERT INTO #TRANSLOG            
SELECT  '4CN' AS 'TRANSTYPE',                    
		ACC_CREDITNOTE.CRT_NO 'TRANSCODE',    
		ACC_CREDITNOTE.CRT_DATE,		                
		ACC_CRTCHARGE1.CRT_ACCOUNT 'CLIENTCODE',
		CONVERT(FLOAT,ISNULL(ACC_CRTCHARGE1.CRT_INRAMT,0)) 'DRAMT',                     
		0 'CRAMT'                    
FROM	ACC_CRTCHARGE1  WITH(READPAST)                     
		LEFT OUTER JOIN ACC_CREDITNOTE WITH(READPAST) ON ACC_CREDITNOTE.CRT_NO =  ACC_CRTCHARGE1.CRT_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_CREDITNOTE.CRT_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_CREDITNOTE.CRT_NO,1,5)  = @CMPCITYCODE
		AND ACC_CRTCHARGE1.CRT_INRAMT <> '0' 

--	SET @DESC = 'NO. OF RECORDS FOUND IN CREDIT NOTE CHARGE 2 - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM STORAGE'

--////////////////////////////////////////                          

/* STEP 6: STORAGE INVOICE */                              
INSERT INTO #TRANSLOG                              
SELECT	'6SI' TRANSTYPE,                              
		BILLNO 'TRANSCODE',
		ACC_STORAGE.BILLDT,                              
		CLIENT 'CLIENTCODE',            
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(AMOUNT,0))) ,0)                              
FROM	ACC_STOREDTLS WITH(READPAST)                              
WHERE	ACC_STOREDTLS.BILLNO = ACC_STORAGE.BILLNO) 'DRAMT',                              
		0 'CRAMT'                              
FROM	ACC_STORAGE   WITH(READPAST)                         
WHERE	[DBO].[RPT_YYYYMMDD](ACC_STORAGE.BILLDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_STORAGE.BILLNO,1,5)  = @CMPCITYCODE

--	SET @DESC = 'NO. OF RECORDS FOUND IN STORAGE - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM STORAGE DETAILS'

INSERT INTO #TRANSLOG                                
SELECT  '6SI' AS TRANSTYPE, 
		ACC_STOREDTLS.BILLNO AS TRANSCODE,
		ACC_STORAGE.BILLDT, 
		ACC_STOREDTLS.ACCOUNT AS CLIENTCODE, 
		0 AS DRAMT,             
		ACC_STOREDTLS.AMOUNT AS CRAMT            
FROM	ACC_STORAGE  WITH(READPAST) 
		INNER JOIN DBO.ACC_STOREDTLS WITH(READPAST) ON DBO.ACC_STORAGE.BILLNO = DBO.ACC_STOREDTLS.BILLNO            
WHERE	[DBO].[RPT_YYYYMMDD](ACC_STORAGE.BILLDT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_STORAGE.BILLNO,1,5)  = @CMPCITYCODE

--	SET @DESC = 'NO. OF RECORDS FOUND IN STORAGE DETAILS - ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM BROKERAGE'
		
/* STEP 7: BROKERAGE INVOICE */                              

INSERT INTO #TRANSLOG                              
SELECT	'7BI' TRANSTYPE,                              
		ACC_BROKERAGE.BROK_NO 'TRANSCODE',
		ACC_BROKERAGE.BROK_DT,                              
		BROK_EXPCODE 'CLIENTCODE',                               
		CONVERT(DECIMAL (18,2),(SELECT ISNULL(SUM(CONVERT(DECIMAL (18,2),ISNULL(BRKAMT,0))) ,0) FROM ACC_BRKGDTL WITH(READPAST) WHERE  ACC_BROKERAGE.BROK_NO = ACC_BRKGDTL.BROK_NO)) 'DRAMT',                              
		0 'CRAMT'                              
FROM	ACC_BROKERAGE  WITH(READPAST)                              
WHERE	[DBO].[RPT_YYYYMMDD](ACC_BROKERAGE.BROK_DT) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_BROKERAGE.BROK_NO,1,5)  = @CMPCITYCODE
