/* STEP 8: PURCHASE INVOICE - MAIN TABLE */               

INSERT INTO #TRANSLOG            
SELECT	'1PI' AS TRANSTYPE,            
		APD.PUR_CODE AS 'TRANSCODE',       
		AP.PUR_DATE,       
		AP.PUR_SUPPLIER AS CLIENTCODE,             
		0 AS DRAMT,--- CONVERT(NUMERIC(18,2),DBO.ACC_PURCHASEDTLS.PUR_DEDUCTION)  AS DRAMT,                     
		((CONVERT(NUMERIC(18,2),APD.PUR_AMOUNT) - CONVERT(NUMERIC(18,2),APD.PUR_DEDUCTION))) AS CRAMT
FROM    ACC_PURCHASE AP WITH(READPAST) 
		INNER JOIN ACC_PURCHASEDTLS APD WITH(READPAST) ON AP.PUR_CODE = APD.PUR_CODE            
WHERE	[DBO].[RPT_YYYYMMDD](AP.PUR_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(AP.PUR_CODE	,1,5)  = @CMPCITYCODE    
		AND RTRIM(LTRIM(PUR_ACCOUNT)) +  RTRIM(LTRIM(PUR_JOBNO)) NOT IN (SELECT RTRIM(LTRIM(PRO_ACCOUNT)) + RTRIM(LTRIM(PRO_JOBNO)) FROM ACC_PROVISION WHERE ISAUTHORISED = 'Y' AND MAWBNO IS NOT NULL)

INSERT INTO #TRANSLOG            
SELECT	'2PI' AS TRANSTYPE,            
		APD.PUR_CODE AS 'TRANSCODE',       
		AP.PUR_DATE,       
		APD.PUR_ACCOUNT AS CLIENTCODE,             
		CONVERT(NUMERIC(18,2),APD.PUR_AMOUNT) AS DRAMT,--- CONVERT(NUMERIC(18,2),DBO.ACC_PURCHASEDTLS.PUR_DEDUCTION)  AS DRAMT,                     
		CONVERT(NUMERIC(18,2),APD.PUR_DEDUCTION) AS CRAMT
FROM    ACC_PURCHASE AP WITH(READPAST) 
		INNER JOIN ACC_PURCHASEDTLS APD WITH(READPAST) ON AP.PUR_CODE = APD.PUR_CODE            
WHERE	[DBO].[RPT_YYYYMMDD](AP.PUR_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(AP.PUR_CODE,1,5)  = @CMPCITYCODE    
		AND RTRIM(LTRIM(PUR_ACCOUNT)) +  RTRIM(LTRIM(PUR_JOBNO)) NOT IN (SELECT RTRIM(LTRIM(PRO_ACCOUNT)) + RTRIM(LTRIM(PRO_JOBNO)) FROM ACC_PROVISION WHERE ISAUTHORISED = 'Y' AND MAWBNO IS NOT NULL)

