		ACC_PURCHASEDTLS.PUR_CODE AS 'TRANSCODE',       
		ACC_PURCHASE.PUR_DATE,    
		ACC_PURCHASE.PUR_SUPPLIER,   
		ACC_PURCHASEDTLS.PUR_ACCOUNT AS CLIENTCODE,             
		CONVERT(NUMERIC(18,2),ACC_PURCHASEDTLS.PUR_AMOUNT) AS DRAMT,
		CONVERT(NUMERIC(18,2),ACC_PURCHASEDTLS.PUR_DEDUCTION) AS CRAMT,
		PUR_JOBNO        
FROM    ACC_PURCHASE  WITH(READPAST) 
		INNER JOIN DBO.ACC_PURCHASEDTLS WITH(READPAST) ON ACC_PURCHASE.PUR_CODE = ACC_PURCHASEDTLS.PUR_CODE            
WHERE	SUBSTRING(ACC_PURCHASE.PUR_CODE,1,5)  = @CMPCITYCODE      
		AND RTRIM(LTRIM(PUR_ACCOUNT)) +  RTRIM(LTRIM(PUR_JOBNO)) IN (SELECT RTRIM(LTRIM(PRO_ACCOUNT)) + RTRIM(LTRIM(PRO_JOBNO)) FROM ACC_PROVISION WHERE ISAUTHORISED = 'Y' AND MAWBNO IS NOT NULL AND [DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN @FDATE AND @TDATE )
		AND [DBO].[RPT_YYYYMMDD](ACC_PURCHASE.PUR_DATE) BETWEEN @FDATE AND @TDATE

