CREATE TABLE #TRANSLOG_PREV_LOG(                      
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                              
	CRAMT DECIMAL(18,2)) 

INSERT INTO #TRANSLOG_PREV_LOG	
SELECT	ACCTCODE,                               
		ISNULL(SUM(ISNULL(DRAMT,0)),0) DRAMT,                               
		ISNULL(SUM(ISNULL(CRAMT,0)),0) CRAMT                              
FROM	#TRANSLOG 
WHERE	[DBO].[RPT_YYYYMMDD](TRANSDATE) BETWEEN @FDATE AND @USR_DATE_START_LAST
GROUP BY ACCTCODE 

/**
--/*Condition 1*/
--(1) IF PURCHASE AND PROVISION PRESENT DURING ABOVE PERIOD
-- TAKE PURCHASE AND IGNORE PROVISION
Insert into #Translog
Fatch PUR_CODE,PUR_DATE,pur_Accoutcode,sum(pur_dramr)
where condition1 = '1'
**/
INSERT INTO #TRANSLOG_PREV_LOG
SELECT	ACCTCODE,
		ISNULL(SUM(ISNULL(PUR_AMT,0)),0) DRAMT,
		ISNULL(SUM(ISNULL(PUR_DEDUCTION,0)),0) CRAMT
FROM	#TRANSLOG_PUR_PRO_FINAL 
WHERE	PREV_IS_PUR_PRO_EXIST=1 
GROUP BY ACCTCODE

INSERT INTO #TRANSLOG_PREV_LOG
SELECT	TRASLOG_SUPPLIER,
		0 DRAMT,
		(ISNULL(SUM(ISNULL(TRASLOG_DRAMT,0)),0) - ISNULL(SUM(ISNULL(TRASLOG_CRAMT,0)),0)) CRAMT
FROM	#TRANSLOG_PUR_PRO_SUPPLIER
WHERE	PREV_IS_PUR_PRO_EXIST=1 
GROUP BY TRASLOG_SUPPLIER



