			0
	FROM	#TRANSLOG_PUR_PRO_FINAL 
	WHERE	PREV_IS_PRO_EXIST_PUR_EXIST_AFTER=1 
	GROUP BY ACCTCODE                              

INSERT INTO #TRANSLOG_PREV_LOG
