SELECT	SEQ,
		GROUPCODE,GROUPNAME,
		ACCTCODE,ACCTNAME,
		OPBLDR,OPBLCR,
		PREVDR,PREVCR,
		CURRDR,CURRCR,
		CLBLDR, CLBLCR
FROM	#TRANSLOG_FINAL

