		NULL, NULL
--FROM	#TRANSLOG_FINAL

--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'COMPLETED CALCULATION'
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'GENERATING REPORT'


	---START HEADER CREATION----

	IF OBJECT_ID('TEMPDB..#HEADER') IS NOT NULL 
	DROP TABLE #HEADER
	CREATE TABLE #HEADER(ID INT IDENTITY,HEADER NVARCHAR(100))
	

	DECLARE @HEADER NVARCHAR(1000), @STRCMP NVARCHAR(100), @PREV NVARCHAR(200),@PREVDT NVARCHAR(200)

	SELECT	DISTINCT TOP 1 @STRCMP = RTRIM(CMP_NAME)
	FROM	CMP_ADDRESS
	WHERE   CMP_CODE=@COMPANYCODE
	SELECT TOP 1 @STRCMP = @STRCMP + ' ' + CITYNAME FROM CITY WHERE CITYCODE1=@CITYCODE	

	
	IF @FIN_DATE_START = CONVERT(VARCHAR,DATEADD(D,0,(DBO.CONVERTDATE_IN_US(@USR_DATE_START,'/'))),103)
	BEGIN
		SET @PREV = 'Previous Total N/A'
		SET @PREVDT = 'N/A'
	END
	ELSE
	BEGIN
		SET @PREV = 'Previous Total From:  ' +  @FIN_DATE_START + ' To: ' + CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
		SET @PREVDT = @FIN_DATE_START + ' - ' + CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
	END
	

	INSERT INTO #HEADER(HEADER)
	SELECT @STRCMP
	INSERT INTO #HEADER(HEADER)----FOR EMPTY ROW
	SELECT ''
	INSERT INTO #HEADER(HEADER)----FOR EMPTY ROW
	SELECT ''
	

	INSERT INTO #HEADER(HEADER)
	SELECT ('Financial Year ' + @FIN_DATE_START + ' - ' + @FIN_DATE_END)

	INSERT INTO #HEADER(HEADER)
	SELECT ('Opening Balance as on ' + @FIN_DATE_START)

	INSERT INTO #HEADER(HEADER)
	SELECT @PREV
	

	INSERT INTO #HEADER(HEADER)
	SELECT ('Current Total From: ' + @USR_DATE_START + ' To: ' + @USR_DATE_END)

	INSERT INTO #HEADER(HEADER)
	SELECT ('Trial Balance Report Generated On ' + CONVERT(VARCHAR,GETDATE(),103) + ' ' + CONVERT(VARCHAR,GETDATE(),108))
	
	INSERT INTO #HEADER(HEADER)
	SELECT @PREVDT

	INSERT INTO #HEADER(HEADER)
	SELECT (@USR_DATE_START + ' - ' + @USR_DATE_END)

	---END HEADER CREATION----

	--------RESULT SETS--------

	---HEADER DETAILS
	SELECT HEADER FROM #HEADER 
	
	---MAIN DATA DETAILS
	SELECT  'GROUP'= CASE WHEN ACCTNAME = '  <b>TOTAL</b>'  OR ACCTNAME IS NULL THEN '' ELSE GROUPNAME END,
			ACCTCODE 'CODE', --= CASE WHEN ACCTCODE = '  TOTAL' THEN '' ELSE ACCTCODE END, 
			ACCTNAME 'PARTICULAR',-- = CASE WHEN ACCTCODE = '  TOTAL' THEN '  TOTAL' ELSE ACCTNAME END, 
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(OPBLDR))+'</b>' ELSE convert(varchar,ABS(OPBLDR)) END [Debit],
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(OPBLCR))+'</b>' ELSE convert(varchar,ABS(OPBLCR)) END [Credit],
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(PREVDR))+'</b>' ELSE convert(varchar,ABS(PREVDR)) END [Debit],
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(PREVCR))+'</b>' ELSE convert(varchar,ABS(PREVCR)) END [Credit],
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(CURRDR))+'</b>' ELSE convert(varchar,ABS(CURRDR)) END [Debit],
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(CURRCR))+'</b>' ELSE convert(varchar,ABS(CURRCR)) END [Credit],
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(CLBLDR))+'</b>' ELSE convert(varchar,ABS(CLBLDR)) END [Debit], 
			CASE WHEN SEQ='002' THEN '<b>'+convert(varchar,ABS(CLBLCR))+'</b>' ELSE convert(varchar,ABS(CLBLCR)) END [Credit]
	FROM	#TRANSLOG_REPORT
	WHERE	OPBLDR <>0.00
			OR OPBLCR <>0.00 
			OR PREVDR <>0.00 
			OR PREVCR <>0.00 
			OR CURRDR <>0.00 
			OR CURRCR <>0.00 
			OR CLBLDR <>0.00 
			OR CLBLCR <>0.00 
			OR ACCTNAME IS NULL
	--where GROUPCODE='AAAA' and ACCTNAME is not null
	ORDER BY GROUPNAME,SEQ,ACCTNAME
		
	-------END RESULT SETS-----

