	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                               
	CRAMT DECIMAL(18,2)                              
)                                
/* STEP 1: STANDARD INVOICE ONLY CREDIT ALL CHARGES                              
CLIENT A/C          DR   XXXX.XX                              
CHARGES A/C                      XXXX.XXX                              

*/                                
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM ACCOUNTS'
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM INVOICE'

INSERT INTO #TRANSLOG                        
SELECT	'1II',                        
		INV_NO,     
		INV_DATE,                   
		INV_CLIENT,                         
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) FROM ACC_INVCHARGE WITH(READPAST) WHERE ACC_INVCHARGE.INV_NO = ACC_INVOICE.INV_NO) +
		(SELECT ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) FROM ACC_INVCHARGE1 WITH(READPAST) WHERE ACC_INVCHARGE1.INV_NO = ACC_INVOICE.INV_NO),
		0
FROM	ACC_INVOICE WITH(READPAST)                      
WHERE   [DBO].[RPT_YYYYMMDD](INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(INV_NO,1,2)  = @CMPCITYCODE             

--	SET @DESC = 'NO. OF RECORD FOUND IN INVOICE -	' + CONVERT(VARCHAR,@@ROWCOUNT)------------COMPLETED INVOICE
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM INVOICE CHARGE 1' ------------STARTED INVOICE CHARGE

INSERT INTO #TRANSLOG  
SELECT	'2II',                    
		ACC_INVOICE.INV_NO, 
		ACC_INVOICE.INV_DATE,
		ACC_INVCHARGE.INV_ACCOUNT,                    
		0,                     
		CONVERT(FLOAT,ACC_INVCHARGE.INV_INRAMT) 
FROM	ACC_INVCHARGE WITH(READPAST)                     
		LEFT OUTER JOIN ACC_INVOICE WITH(READPAST) ON ACC_INVOICE.INV_NO =  ACC_INVCHARGE.INV_NO                    
WHERE	[DBO].[RPT_YYYYMMDD](ACC_INVOICE.INV_DATE) BETWEEN @FDATE AND @TDATE
		AND SUBSTRING(ACC_INVOICE.INV_NO,1,2)  = @CMPCITYCODE 
		AND ACC_INVCHARGE.INV_INRAMT <> '0'   

