	PUR_CODE NVARCHAR(15), 
	PUR_DATE NVARCHAR(12),
	PUR_AMT DECIMAL(18,2), 
	PUR_DEDUCTION DECIMAL(18,2)                               
)

INSERT INTO #TRANSLOG_PUR_PRO (ACCTCODE,JOBNO,PRO_CODE,PRO_DATE,PRO_AMT,PUR_CODE,PUR_DATE,PUR_AMT,PUR_DEDUCTION)
SELECT	ACCTCODE, 
		JOBNO,
		PRO_CODE = TRANSCODE,
		PRO_DATE = TRANSDATE,
		PRO_AMT = DRAMT,
		PUR_CODE = (SELECT	MAX(TRANSCODE) 
					FROM	#TRANSLOG1 PRO 
					WHERE	PRO.JOBNO =  PUR.JOBNO 
							AND PRO.ACCTCODE = PUR.ACCTCODE 
							AND TRANSTYPE='2PI'),		
		PUR_DATE = (SELECT	CONVERT(VARCHAR,MAX(CONVERT(DATETIME,TRANSDATE,103)),103) 
					FROM	#TRANSLOG1 PRO 
					WHERE	PRO.JOBNO =  PUR.JOBNO 
							AND PRO.ACCTCODE = PUR.ACCTCODE 
							AND TRANSTYPE='2PI'),
		PUR_AMT = (SELECT	SUM(DRAMT)
					FROM	#TRANSLOG1 PRO 
					WHERE	PRO.JOBNO =  PUR.JOBNO 
							AND PRO.ACCTCODE = PUR.ACCTCODE 
							AND TRANSTYPE='2PI'),
		PUR_DEDUCTION=(SELECT	SUM(CRAMT)
					   FROM		#TRANSLOG1 PRO 
					   WHERE	PRO.JOBNO =  PUR.JOBNO 
								AND PRO.ACCTCODE = PUR.ACCTCODE 
								AND TRANSTYPE='2PI')					
FROM	#TRANSLOG1 PUR
WHERE	TRANSTYPE='PP'
		AND LEN(JOBNO) = 15 
ORDER BY [DBO].[RPT_YYYYMMDD](TRANSDATE)	


IF OBJECT_ID('TEMPDB..#TRANSLOG_PUR_PRO_FINAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_PUR_PRO_FINAL
CREATE TABLE #TRANSLOG_PUR_PRO_FINAL( 
	ID INT IDENTITY(1,1),   
	ACCTCODE  NVARCHAR(15),  
	JOBNO  NVARCHAR(15),          
	PRO_CODE NVARCHAR(15), 
	PRO_DATE NVARCHAR(12),
	PRO_AMT DECIMAL(18,2),	
	PUR_CODE NVARCHAR(15), 
	PUR_DATE NVARCHAR(12),
	PUR_AMT DECIMAL(18,2),
	PUR_DEDUCTION DECIMAL(18,2),
	PREV_IS_PUR_PRO_EXIST NVARCHAR(1), 
	PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	PREV_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1),	
	CURR_IS_PUR_PRO_EXIST NVARCHAR(1), 
	CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	CURR_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1)                             

)


