INSERT INTO #TRANSLOG_PUR_PRO_FINAL
SELECT	--[DBO].[RPT_YYYYMMDD](PRO_DATE),
		ACCTCODE,
		JOBNO,
		PRO_CODE,
		PRO_DATE,
		PRO_AMT, 
		PUR_CODE,
		PUR_DATE,
		PUR_AMT,
		PUR_DEDUCTION,
		PREV_IS_PUR_PRO_EXIST = CASE WHEN -- ONLY PURCHASE
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN  (@FDATE) AND  (@USR_DATE_START_LAST) AND 
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  (@FDATE) AND  (@USR_DATE_START_LAST) 
							THEN 1 ELSE 0 END,
		PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST = CASE WHEN  --- IGNOURE BOTH
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN ( (@FDATE)) AND ( (@USR_DATE_START_LAST)) 
									AND [DBO].[RPT_YYYYMMDD](PRO_DATE) <  (@FDATE)
							THEN 1 ELSE 0 END,
		PREV_IS_PRO_EXIST_PUR_EXIST_AFTER = CASE WHEN -- PROVISION
									[DBO].[RPT_YYYYMMDD](PUR_DATE) >  (@USR_DATE_START_LAST) AND
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  (@FDATE) AND  (@USR_DATE_START_LAST)
							THEN 1 ELSE 0 END,		
		CURR_IS_PUR_PRO_EXIST = CASE WHEN -- ONLY PURCHASE
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) AND  [DBO].[RPT_YYYYMMDD](@USR_DATE_END) AND 
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) AND  [DBO].[RPT_YYYYMMDD](@USR_DATE_END) 
							THEN 1 ELSE 0 END,
		CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST = CASE WHEN  --- IGNOURE BOTH
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN ( [DBO].[RPT_YYYYMMDD](@USR_DATE_START)) AND ( [DBO].[RPT_YYYYMMDD](@USR_DATE_END)) 
									AND [DBO].[RPT_YYYYMMDD](PRO_DATE) <  [DBO].[RPT_YYYYMMDD](@USR_DATE_START)
							THEN 1 ELSE 0 END,
		CURR_IS_PRO_EXIST_PUR_EXIST_AFTER = CASE WHEN -- PROVISION
									[DBO].[RPT_YYYYMMDD](PUR_DATE) >  [DBO].[RPT_YYYYMMDD](@USR_DATE_END) AND
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) AND  [DBO].[RPT_YYYYMMDD](@USR_DATE_END)
							THEN 1 ELSE 0 END							
FROM	#TRANSLOG_PUR_PRO


IF OBJECT_ID('TEMPDB..#TRANSLOG_PUR_PRO_SUPPLIER') IS NOT NULL   
	DROP TABLE #TRANSLOG_PUR_PRO_SUPPLIER

CREATE TABLE #TRANSLOG_PUR_PRO_SUPPLIER( 
	ID INT,   
	ACCTCODE  NVARCHAR(15),  
	JOBNO  NVARCHAR(15),          
	PRO_CODE NVARCHAR(15), 
	PRO_SUPPLIER_TOP_1 NVARCHAR(15), 
	PRO_DATE NVARCHAR(12),
	PRO_AMT DECIMAL(18,2),	
	PUR_CODE NVARCHAR(15), 
	PUR_DATE NVARCHAR(12),
	PUR_AMT DECIMAL(18,2),
	PUR_DEDUCTION DECIMAL(18,2),
	PREV_IS_PUR_PRO_EXIST NVARCHAR(1), 
	PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	PREV_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1),	
	CURR_IS_PUR_PRO_EXIST NVARCHAR(1), 
	CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	CURR_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1),
	TRASLOG_TRANSTYPE NVARCHAR(3), 
	TRASLOG_TRANSCODE NVARCHAR(15),
	TRASLOG_TRANSDATE NVARCHAR(12),
	TRASLOG_SUPPLIER NVARCHAR(15),
	TRASLOG_ACCTCODE NVARCHAR(15),                              
	TRASLOG_DRAMT DECIMAL(18,2),                               
	TRASLOG_CRAMT DECIMAL(18,2),
	TRASLOG_JOBNO NVARCHAR(15)               
)

INSERT INTO #TRANSLOG_PUR_PRO_SUPPLIER
SELECT	PRO.ID,   
		PRO.ACCTCODE,  
		PRO.JOBNO,          
		PRO.PRO_CODE, 
		PRO_SUPPLIER_TOP_1 = ISNULL((SELECT TOP 1 SUPPLIER FROM #TRANSLOG1 SUP WHERE SUP.JOBNO = PRO.JOBNO AND SUP.ACCTCODE = PRO.ACCTCODE AND SUP.TRANSTYPE = '2PI'),'G101625'),		
		PRO.PRO_DATE,
		PRO.PRO_AMT,	
		PRO.PUR_CODE, 
		PRO.PUR_DATE,
		PRO.PUR_AMT,
		PRO.PUR_DEDUCTION,
		PRO.PREV_IS_PUR_PRO_EXIST,
		PRO.PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST, 
		PRO.PREV_IS_PRO_EXIST_PUR_EXIST_AFTER, 
		PRO.CURR_IS_PUR_PRO_EXIST, 
		PRO.CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST,
		PRO.CURR_IS_PRO_EXIST_PUR_EXIST_AFTER,
		LO.TRANSTYPE,
		LO.TRANSCODE,
		LO.TRANSDATE,		
		ISNULL(LO.SUPPLIER,'G101625'),
		LO.ACCTCODE,
		LO.DRAMT,
		LO.CRAMT,
		LO.JOBNO
FROM	#TRANSLOG_PUR_PRO_FINAL PRO
		LEFT OUTER JOIN #TRANSLOG1 LO ON LO.JOBNO = PRO.JOBNO AND LO.ACCTCODE = PRO.ACCTCODE AND LO.TRANSTYPE = '2PI'
ORDER BY PRO.ID

