IF OBJECT_ID('TEMPDB..#TRANSLOG_FINAL_BEFORE') IS NOT NULL   
	DROP TABLE #TRANSLOG_FINAL_BEFORE

CREATE TABLE #TRANSLOG_FINAL_BEFORE(
	SEQ NVARCHAR(5),
	GROUPCODE NVARCHAR(15),
	GROUPNAME NVARCHAR(500),	
	ACCTCODE NVARCHAR(15),
	ACCTNAME NVARCHAR(500),
	OPBLDR DECIMAL(18,2),                              
	OPBLCR DECIMAL(18,2),
	PREVDR DECIMAL(18,2),                              
	PREVCR DECIMAL(18,2),
	CURRDR DECIMAL(18,2),                              
	CURRCR DECIMAL(18,2),
	CLBLDR DECIMAL(18,2),                              
	CLBLCR DECIMAL(18,2)	
	) 

INSERT INTO #TRANSLOG_FINAL_BEFORE
SELECT	'000',
		GROUPCODE = CASE WHEN LEN(GROUPCODE) =0 THEN 'AAAA' ELSE GROUPCODE END, 
		GROUPNAME = ISNULL((SELECT TOP 1 NAME FROM #TRANSLOG_UNDERGRP WHERE #TRANSLOG_UNDERGRP.CODE = GROUPCODE),'  Non Group'),
		ACCTCODE, 
		ACCTNAME,		
		OPBLDR = ISNULL((SELECT SUM(ISNULL(OPBALDR,0)) FROM #TRANSLOG_OPBAL WHERE #TRANSLOG_OPBAL.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		OPBLCR = ISNULL((SELECT SUM(ISNULL(OPBALCR,0)) FROM #TRANSLOG_OPBAL WHERE #TRANSLOG_OPBAL.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		PREVDR = ISNULL((SELECT SUM(ISNULL(DRAMT,0)) FROM #TRANSLOG_PREV WHERE #TRANSLOG_PREV.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		PREVCR = ISNULL((SELECT SUM(ISNULL(CRAMT,0)) FROM #TRANSLOG_PREV WHERE #TRANSLOG_PREV.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		CURRDR = ISNULL((SELECT SUM(ISNULL(DRAMT,0)) FROM #TRANSLOG_CURR WHERE #TRANSLOG_CURR.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		CURRCR = ISNULL((SELECT SUM(ISNULL(CRAMT,0)) FROM #TRANSLOG_CURR WHERE #TRANSLOG_CURR.ACCTCODE=#TRANSLOG_ACCOUNT.ACCTCODE),0),
		0,
		0
FROM	#TRANSLOG_ACCOUNT
WHERE	ACCTCODE NOT LIKE  'M%'
ORDER BY ACCTNAME


IF OBJECT_ID('TEMPDB..#TRANSLOG_FINAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_FINAL

CREATE TABLE #TRANSLOG_FINAL(
	SEQ NVARCHAR(5),
	GROUPCODE NVARCHAR(15),
	GROUPNAME NVARCHAR(500),	
	ACCTCODE NVARCHAR(15),
	ACCTNAME NVARCHAR(500),
	OPBLDR DECIMAL(18,2),                              
	OPBLCR DECIMAL(18,2),
	PREVDR DECIMAL(18,2),                              
	PREVCR DECIMAL(18,2),
	CURRDR DECIMAL(18,2),                              
	CURRCR DECIMAL(18,2),
	CLBLDR DECIMAL(18,2),                              
	CLBLCR DECIMAL(18,2)	
	) 

INSERT INTO #TRANSLOG_FINAL
SELECT	SEQ,
		GROUPCODE, 
		GROUPNAME,
		ACCTCODE, 
		ACCTNAME,		
		OPBLDR,
		OPBLCR,
		PREVDR,
		PREVCR,
		CURRDR,
		CURRCR,
		0,
		0
FROM	#TRANSLOG_FINAL_BEFORE
WHERE	OPBLDR <> 0 or 
		OPBLCR <> 0 or 
		PREVDR <> 0 or 
		PREVCR <> 0 or 
		CURRDR <> 0 or 
		CURRCR <> 0
ORDER BY ACCTNAME

