	---START HEADER CREATION----

	IF OBJECT_ID('TEMPDB..#HEADER') IS NOT NULL 
	DROP TABLE #HEADER
	CREATE TABLE #HEADER(ID INT IDENTITY,HEADER NVARCHAR(100))
	

	DECLARE @HEADER NVARCHAR(1000), @STRCMP NVARCHAR(100), @PREV NVARCHAR(200),@PREVDT NVARCHAR(200)

	SELECT	DISTINCT TOP 1 @STRCMP = RTRIM(CMP_NAME)
	FROM	CMP_ADDRESS
	WHERE   CMP_CODE=@COMPANYCODE
	---SELECT TOP 1 @STRCMP = @STRCMP + ' ' + CITYNAME FROM CITY WHERE CITYCODE1=@CITYCODE	
	
	IF @FIN_DATE_START = CONVERT(VARCHAR,DATEADD(D,0,(DBO.CONVERTDATE_IN_US(@USR_DATE_START,'/'))),103)
	BEGIN
		SET @PREV = 'Previous Total N/A'
		SET @PREVDT = 'N/A'
	END
	ELSE
	BEGIN
		SET @PREV = 'Previous Total From:  ' +  @FIN_DATE_START + ' To: ' + CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
		SET @PREVDT = @FIN_DATE_START + ' - ' + CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
	END
	

	INSERT INTO #HEADER(HEADER)
	SELECT @STRCMP
	INSERT INTO #HEADER(HEADER)----FOR EMPTY ROW
	SELECT ''
	

	INSERT INTO #HEADER(HEADER)
	SELECT ('Financial Year ' + @FIN_DATE_START + ' - ' + @FIN_DATE_END)

	INSERT INTO #HEADER(HEADER)
	SELECT ('Opening Balance as on ' + @FIN_DATE_START)

	INSERT INTO #HEADER(HEADER)
	SELECT @PREV

	INSERT INTO #HEADER(HEADER)
	SELECT ('Current Total From: ' + @USR_DATE_START + ' To: ' + @USR_DATE_END)

	INSERT INTO #HEADER(HEADER)
	SELECT ('Trial Balance Report Generated On ' + CONVERT(VARCHAR,GETDATE(),103) + ' ' + CONVERT(VARCHAR,GETDATE(),108))

	INSERT INTO #HEADER(HEADER)
	SELECT @PREVDT

	INSERT INTO #HEADER(HEADER)
	SELECT (@USR_DATE_START + ' - ' + @USR_DATE_END)
	---END HEADER CREATION----


--------RESULT SETS--------
	---HEADER DETAILS
	SELECT HEADER FROM #HEADER 
	
	---MAIN DATA DETAILS
	SELECT  'GROUP' = CASE WHEN ACCTCODE = '  TOTAL' THEN GROUPNAME ELSE '' END,
			'CODE' = CASE WHEN ACCTCODE = '  TOTAL' THEN '' ELSE ACCTCODE END, 
			'PARTICULAR' = CASE WHEN ACCTCODE = '  TOTAL' THEN '  TOTAL' ELSE ACCTNAME END, 
			ABS(OPBLDR) 'OpeningBalDr',
			ABS(OPBLCR) 'OpeningBalCr',
			ABS(PREVDR) 'PreviousDr',
			ABS(PREVCR) 'PreviousCr',
			ABS(CURRDR) 'CurrentDr',
			ABS(CURRCR) 'CurrentCr',
			ABS(CLBLDR) 'ClosingBalDr', 
			ABS(CLBLCR) 'ClosingBalCr'
	FROM	#TRANSLOG_REPORT
	--where GROUPCODE='AAAA' and ACCTNAME is not null
	WHERE	OPBLDR <>0.00
			OR OPBLCR <>0.00 
			OR PREVDR <>0.00 
			OR PREVCR <>0.00 
			OR CURRDR <>0.00 
			OR CURRCR <>0.00 
			OR CLBLDR <>0.00 
			OR CLBLCR <>0.00 
	ORDER BY GROUPNAME,ACCTNAME
-------END RESULT SETS-----
