ALTER PROCEDURE [dbo].[USP_ACCT_RPT_TRIALBALANCE_PROVISION_TRANS]
--DECLARE   
@USR_DATE_START NVARCHAR(12),    
@USR_DATE_END NVARCHAR(12),
@FIN_DATE_START NVARCHAR(12),                              
@FIN_DATE_END NVARCHAR(12),                              
@COMPANYCODE NVARCHAR(2),                              
@CITYCODE NVARCHAR(3)

AS /*  
--01-10-2010 TO 30-11-2010

SET @USR_DATE_START = '01/11/2010'
SET @USR_DATE_END	= '30/11/2010'
SET @FIN_DATE_START = '01/04/2010'                          
SET @FIN_DATE_END	= '31/03/2011'   
SET @COMPANYCODE	= '01'                           
SET @CITYCODE		= '101'     
--  */     
      
SET NOCOUNT ON

DECLARE @FDATE NVARCHAR(10),
		@TDATE NVARCHAR(10),
		@OPBALST NVARCHAR(20),
		@OPBALTABLE VARCHAR(100),
		@CMPCITYCODE NVARCHAR(5),
		@USR_DATE_START_LAST NVARCHAR(10),
		@USR_DATE_START_FIRST NVARCHAR(10),@DESC NVARCHAR(100)


SET @OPBALST =	SUBSTRING(@FIN_DATE_START,1,2) +  SUBSTRING(@FIN_DATE_START,4,2) + SUBSTRING(@FIN_DATE_START,7,4) +
				SUBSTRING(@FIN_DATE_END,1,2) +  SUBSTRING(@FIN_DATE_END,4,2) + SUBSTRING(@FIN_DATE_END,8,3)

SET @OPBALTABLE='TBL_MASTER_'+ @OPBALST +'_ALLGL'      

SET @FDATE = SUBSTRING(@FIN_DATE_START,7,4) +  SUBSTRING(@FIN_DATE_START,4,2) + SUBSTRING(@FIN_DATE_START,1,2)
SET @TDATE = SUBSTRING(@USR_DATE_END,7,4) +  SUBSTRING(@USR_DATE_END,4,2) + SUBSTRING(@USR_DATE_END,1,2)

SET @USR_DATE_START_LAST = CONVERT(VARCHAR,DATEADD(D,-1,(dbo.ConvertDate_IN_US(@USR_DATE_START,'/'))),103)
SET @USR_DATE_START_LAST = SUBSTRING(@USR_DATE_START_LAST,7,4) +  SUBSTRING(@USR_DATE_START_LAST,4,2) + SUBSTRING(@USR_DATE_START_LAST,1,2)
SET @USR_DATE_START_FIRST = SUBSTRING(@USR_DATE_START,7,4) +  SUBSTRING(@USR_DATE_START,4,2) + SUBSTRING(@USR_DATE_START,1,2)
SET @CMPCITYCODE = @COMPANYCODE + @CITYCODE

--SELECT  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) USR_DATE_START , 
--		[DBO].[RPT_YYYYMMDD](@USR_DATE_END) USR_DATE_END,
--		@USR_DATE_START_LAST USR_DATE_START_LAST,
--		@USR_DATE_START_LAST USR_DATE_START_LAST,
--		@USR_DATE_START_FIRST USR_DATE_START_FIRST

/*********************** START OF CONDITION *******************************/

/*
From :Jolly / MP-Bom <jolly@manilal.com>
Date: 11 November 2010 17:45
Subject: EFFECT OF PROVISION IN TRIAL BALANCE (PROVISION) AND DEPARTMENTWISE PROFIT

(1) if purchase and provision present during above period
 take purchase and ignore provision
 
(2) if provision exists earlier than above period and purchase
 exists during above period ... ignore both for 
 reporting above period
 
(3) if provision present during above period and  purchase exists
 after above period then consider provision

SELECT * FROM #TRANSLOG1 WHERE TRANSTYPE='2PI' ORDER BY [DBO].[RPT_YYYYMMDD](TRANSDATE) 
SELECT * FROM #TRANSLOG1 WHERE TRANSTYPE='PP' ORDER BY [DBO].[RPT_YYYYMMDD](TRANSDATE) 

air freight..... mawb dt. 28-10-2010
provision dated 28-10-2010
purchase date 20-11-2010
 
reporting period (a) 01-10-2010 to 31-10-2010
     **** condition 3 applies here 

reporting period (b) 01-11-2010 to 30-11-2010
     **** condition 2 applies here 

reporting period (c) 01-10-2010 to 30-11-2010
     **** condition 1 applies here 

*/


IF OBJECT_ID('TEMPDB..#TRANSLOG1') IS NOT NULL   
	DROP TABLE #TRANSLOG1
/* CREAT TABLE WHERE CLIENT ID'S WILL BE THERE AND HIS TOTAL DEBIT AND TOTAL CREDIT */                              
CREATE TABLE #TRANSLOG1(                              
	TRANSTYPE NVARCHAR(3), 
	TRANSCODE NVARCHAR(15),
	TRANSDATE NVARCHAR(12),
	SUPPLIER NVARCHAR(15),
	ACCTCODE NVARCHAR(15),                              
	DRAMT DECIMAL(18,2),                               
	CRAMT DECIMAL(18,2) ,
	JOBNO NVARCHAR(15)                             
)                                
                        
--	SET @DESC = 'NO. OF RECORDS FOUND IN PURCHASE - ' + CONVERT(VARCHAR,@@ROWCOUNT)              
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC 
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'READING FROM PURCHASE DETAILS'

INSERT INTO #TRANSLOG1            
SELECT	'2PI' AS TRANSTYPE,            
		ACC_PURCHASEDTLS.PUR_CODE AS 'TRANSCODE',       
		ACC_PURCHASE.PUR_DATE,    
		ACC_PURCHASE.PUR_SUPPLIER,   
		ACC_PURCHASEDTLS.PUR_ACCOUNT AS CLIENTCODE,             
		CONVERT(NUMERIC(18,2),ACC_PURCHASEDTLS.PUR_AMOUNT) AS DRAMT,
		CONVERT(NUMERIC(18,2),ACC_PURCHASEDTLS.PUR_DEDUCTION) AS CRAMT,
		PUR_JOBNO        
FROM    ACC_PURCHASE  WITH(READPAST) 
		INNER JOIN DBO.ACC_PURCHASEDTLS WITH(READPAST) ON ACC_PURCHASE.PUR_CODE = ACC_PURCHASEDTLS.PUR_CODE            
WHERE	SUBSTRING(ACC_PURCHASE.PUR_CODE,1,5)  = @CMPCITYCODE      
		AND RTRIM(LTRIM(PUR_ACCOUNT)) +  RTRIM(LTRIM(PUR_JOBNO)) IN (SELECT RTRIM(LTRIM(PRO_ACCOUNT)) + RTRIM(LTRIM(PRO_JOBNO)) FROM ACC_PROVISION WHERE ISAUTHORISED = 'Y' AND MAWBNO IS NOT NULL AND [DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN @FDATE AND @TDATE )
		AND [DBO].[RPT_YYYYMMDD](ACC_PURCHASE.PUR_DATE) BETWEEN @FDATE AND @TDATE

INSERT INTO #TRANSLOG1
SELECT  'PP',
		PRO_CODE,
		PRO_DATE,
		'',
		PRO_ACCOUNT,
		PRO_AMOUNT AS DRAMT,
		0 AS CRAMT,
		PRO_JOBNO
FROM    ACC_PROVISION WITH(READPAST) 
WHERE	SUBSTRING(PRO_CODE,1,5) = @CMPCITYCODE   
		--AND RTRIM(LTRIM(PRO_ACCOUNT)) + RTRIM(LTRIM(PRO_JOBNO)) IN (SELECT	RTRIM(LTRIM(#TRANSLOG1.ACCTCODE)) + RTRIM(LTRIM(#TRANSLOG1.JOBNO)) 
		--															FROM	#TRANSLOG1 
		--															WHERE	TRANSTYPE='2PI')
		AND ISAUTHORISED = 'Y'
		AND MAWBNO IS NOT NULL
		AND [DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN @FDATE AND @TDATE
		--SELECT SUM(DRAMT),SUM(CRAMT) FROM #TRANSLOG
		--SELECT SUM(DRAMT),SUM(CRAMT) FROM #TRANSLOG1
--SELECT * FROM #TRANSLOG1 WHERE JOBNO ='011011020000450'
--SELECT * FROM #TRANSLOG WHERE TRANSTYPE='2PI' ORDER BY [DBO].[RPT_YYYYMMDD](TRANSDATE) 

--	SET @DESC = 'NO. OF RECORDS FOUND IN PURCHASE DETAILS ' + CONVERT(VARCHAR,@@ROWCOUNT)
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', @DESC
--	EXEC USP_REPORT_LOG_SCRIPT @FK_LOGID, '', 'STARTED CALUCATION'

--SELECT * FROM #TRANSLOG1 WHERE acctcode='G100235' and TRANSTYPE='PP'
--/*

IF OBJECT_ID('TEMPDB..#TRANSLOG_PUR_PRO') IS NOT NULL   
	DROP TABLE #TRANSLOG_PUR_PRO

CREATE TABLE #TRANSLOG_PUR_PRO( 
	ID INT IDENTITY(1,1),   
	ACCTCODE  NVARCHAR(15),  
	JOBNO  NVARCHAR(15),          
	PRO_CODE NVARCHAR(15), 
	PRO_DATE NVARCHAR(12),
	PRO_AMT DECIMAL(18,2),	
	PUR_CODE NVARCHAR(15), 
	PUR_DATE NVARCHAR(12),
	PUR_AMT DECIMAL(18,2), 
	PUR_DEDUCTION DECIMAL(18,2)                               
)

INSERT INTO #TRANSLOG_PUR_PRO (ACCTCODE,JOBNO,PRO_CODE,PRO_DATE,PRO_AMT,PUR_CODE,PUR_DATE,PUR_AMT,PUR_DEDUCTION)
SELECT	ACCTCODE, 
		JOBNO,
		PRO_CODE = TRANSCODE,
		PRO_DATE = TRANSDATE,
		PRO_AMT = DRAMT,
		PUR_CODE = (SELECT	MAX(TRANSCODE) 
					FROM	#TRANSLOG1 PRO 
					WHERE	PRO.JOBNO =  PUR.JOBNO 
							AND PRO.ACCTCODE = PUR.ACCTCODE 
							AND TRANSTYPE='2PI'),		
		PUR_DATE = (SELECT	CONVERT(VARCHAR,MAX(CONVERT(DATETIME,TRANSDATE,103)),103) 
					FROM	#TRANSLOG1 PRO 
					WHERE	PRO.JOBNO =  PUR.JOBNO 
							AND PRO.ACCTCODE = PUR.ACCTCODE 
							AND TRANSTYPE='2PI'),
		PUR_AMT = (SELECT	SUM(DRAMT)
					FROM	#TRANSLOG1 PRO 
					WHERE	PRO.JOBNO =  PUR.JOBNO 
							AND PRO.ACCTCODE = PUR.ACCTCODE 
							AND TRANSTYPE='2PI'),
		PUR_DEDUCTION=(SELECT	SUM(CRAMT)
					   FROM		#TRANSLOG1 PRO 
					   WHERE	PRO.JOBNO =  PUR.JOBNO 
								AND PRO.ACCTCODE = PUR.ACCTCODE 
								AND TRANSTYPE='2PI')					
FROM	#TRANSLOG1 PUR
WHERE	TRANSTYPE='PP'
		AND LEN(JOBNO) = 15 
		AND [DBO].[RPT_YYYYMMDD](PUR.TRANSDATE) BETWEEN @FDATE AND @TDATE
ORDER BY [DBO].[RPT_YYYYMMDD](PUR.TRANSDATE)	


IF OBJECT_ID('TEMPDB..#TRANSLOG_PUR_PRO_FINAL') IS NOT NULL   
	DROP TABLE #TRANSLOG_PUR_PRO_FINAL
CREATE TABLE #TRANSLOG_PUR_PRO_FINAL( 
	ID INT IDENTITY(1,1),   
	ACCTCODE  NVARCHAR(15),  
	JOBNO  NVARCHAR(15),          
	PRO_CODE NVARCHAR(15), 
	PRO_DATE NVARCHAR(12),
	PRO_AMT DECIMAL(18,2),	
	PUR_CODE NVARCHAR(15), 
	PUR_DATE NVARCHAR(12),
	PUR_AMT DECIMAL(18,2),
	PUR_DEDUCTION DECIMAL(18,2),
	PREV_IS_PUR_PRO_EXIST NVARCHAR(1), 
	PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	PREV_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1),	
	CURR_IS_PUR_PRO_EXIST NVARCHAR(1), 
	CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	CURR_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1)                             
)

--SELECT	@FDATE FDATE,@USR_DATE_START_LAST USR_DATE_START_LAST,
--		@USR_DATE_START USR_DATE_START,@USR_DATE_END USR_DATE_END
--SELECT * FROM #TRANSLOG_PUR_PRO_FINAL
INSERT INTO #TRANSLOG_PUR_PRO_FINAL
SELECT	--[DBO].[RPT_YYYYMMDD](PRO_DATE),
		ACCTCODE,
		JOBNO,
		PRO_CODE,
		PRO_DATE,
		PRO_AMT, 
		PUR_CODE,
		PUR_DATE,
		PUR_AMT,
		PUR_DEDUCTION,
		PREV_IS_PUR_PRO_EXIST = CASE WHEN -- ONLY PURCHASE
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN  (@FDATE) AND  (@USR_DATE_START_LAST) AND 
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  (@FDATE) AND  (@USR_DATE_START_LAST) 
							THEN 1 ELSE 0 END,
		PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST = CASE WHEN  --- IGNOURE BOTH
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN ( (@FDATE)) AND ( (@USR_DATE_START_LAST)) 
									AND [DBO].[RPT_YYYYMMDD](PRO_DATE) <  (@FDATE)
							THEN 1 ELSE 0 END,
		PREV_IS_PRO_EXIST_PUR_EXIST_AFTER = CASE WHEN -- PROVISION
									([DBO].[RPT_YYYYMMDD](PUR_DATE) >  (@USR_DATE_START_LAST)  OR PUR_DATE IS NULL ) AND
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  (@FDATE) AND  (@USR_DATE_START_LAST)
							THEN 1 ELSE 0 END,		
		CURR_IS_PUR_PRO_EXIST = CASE WHEN -- ONLY PURCHASE
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) AND  [DBO].[RPT_YYYYMMDD](@USR_DATE_END) AND 
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) AND  [DBO].[RPT_YYYYMMDD](@USR_DATE_END) 
							THEN 1 ELSE 0 END,
		CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST = CASE WHEN  --- IGNOURE BOTH
									[DBO].[RPT_YYYYMMDD](PUR_DATE) BETWEEN ( [DBO].[RPT_YYYYMMDD](@USR_DATE_START)) AND ( [DBO].[RPT_YYYYMMDD](@USR_DATE_END)) 
									AND [DBO].[RPT_YYYYMMDD](PRO_DATE) <  [DBO].[RPT_YYYYMMDD](@USR_DATE_START)
							THEN 1 ELSE 0 END,
		CURR_IS_PRO_EXIST_PUR_EXIST_AFTER = CASE WHEN -- PROVISION
									([DBO].[RPT_YYYYMMDD](PUR_DATE) >  [DBO].[RPT_YYYYMMDD](@USR_DATE_END)  OR PUR_DATE IS NULL) AND
									[DBO].[RPT_YYYYMMDD](PRO_DATE) BETWEEN  [DBO].[RPT_YYYYMMDD](@USR_DATE_START) AND  [DBO].[RPT_YYYYMMDD](@USR_DATE_END)
							THEN 1 ELSE 0 END							
FROM	#TRANSLOG_PUR_PRO


IF OBJECT_ID('TEMPDB..#TRANSLOG_PUR_PRO_SUPPLIER') IS NOT NULL   
	DROP TABLE #TRANSLOG_PUR_PRO_SUPPLIER

CREATE TABLE #TRANSLOG_PUR_PRO_SUPPLIER( 
	ID INT,   
	ACCTCODE  NVARCHAR(15),  
	JOBNO  NVARCHAR(15),          
	PRO_CODE NVARCHAR(15), 
	PRO_SUPPLIER_TOP_1 NVARCHAR(15), 
	PRO_DATE NVARCHAR(12),
	PRO_AMT DECIMAL(18,2),	
	PUR_CODE NVARCHAR(15), 
	PUR_DATE NVARCHAR(12),
	PUR_AMT DECIMAL(18,2),
	PUR_DEDUCTION DECIMAL(18,2),
	PREV_IS_PUR_PRO_EXIST NVARCHAR(1), 
	PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	PREV_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1),	
	CURR_IS_PUR_PRO_EXIST NVARCHAR(1), 
	CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST NVARCHAR(1),
	CURR_IS_PRO_EXIST_PUR_EXIST_AFTER NVARCHAR(1),
	TRASLOG_TRANSTYPE NVARCHAR(3), 
	TRASLOG_TRANSCODE NVARCHAR(15),
	TRASLOG_TRANSDATE NVARCHAR(12),
	TRASLOG_SUPPLIER NVARCHAR(15),
	TRASLOG_ACCTCODE NVARCHAR(15),                              
	TRASLOG_DRAMT DECIMAL(18,2),                               
	TRASLOG_CRAMT DECIMAL(18,2),
	TRASLOG_JOBNO NVARCHAR(15)               
)

INSERT INTO #TRANSLOG_PUR_PRO_SUPPLIER
SELECT	PRO.ID,   
		PRO.ACCTCODE,  
		PRO.JOBNO,          
		PRO.PRO_CODE, 
		PRO_SUPPLIER_TOP_1 = ISNULL((SELECT TOP 1 SUPPLIER FROM #TRANSLOG1 SUP WHERE SUP.JOBNO = PRO.JOBNO AND SUP.ACCTCODE = PRO.ACCTCODE AND SUP.TRANSTYPE = '2PI'),'G101625')  ,
		PRO.PRO_DATE,
		PRO.PRO_AMT,	
		PRO.PUR_CODE, 
		PRO.PUR_DATE,
		PRO.PUR_AMT,
		PRO.PUR_DEDUCTION,
		PRO.PREV_IS_PUR_PRO_EXIST,
		PRO.PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST, 
		PRO.PREV_IS_PRO_EXIST_PUR_EXIST_AFTER, 
		PRO.CURR_IS_PUR_PRO_EXIST, 
		PRO.CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST,
		PRO.CURR_IS_PRO_EXIST_PUR_EXIST_AFTER,
		LO.TRANSTYPE,
		LO.TRANSCODE,
		LO.TRANSDATE,		
		ISNULL(LO.SUPPLIER,'G101625') SUPPLIER,
		LO.ACCTCODE,
		LO.DRAMT,
		LO.CRAMT,
		LO.JOBNO
FROM	#TRANSLOG_PUR_PRO_FINAL PRO
		LEFT OUTER JOIN #TRANSLOG1 LO ON LO.JOBNO = PRO.JOBNO AND LO.ACCTCODE = PRO.ACCTCODE AND LO.TRANSTYPE = '2PI'
ORDER BY PRO.ID

--SELECT * FROM GENACCT_MASTER ORDER BY 1 DESC

SELECT --* 
	TEMP.ACCTCODE  , 
	GM.ACCTNAME ,
	''''+TEMP.JOBNO JOBNO ,          
	TEMP.PRO_CODE ,
 	--TEMP.PRO_SUPPLIER_TOP_1 , 
	SM.SUP_NAME , 
	TEMP.PRO_DATE ,
	TEMP.PRO_AMT ,	
	''''+TEMP.PUR_CODE PURCHASE_CODE, 
	TEMP.PUR_DATE ,
	''''+TEMP.TRASLOG_JOBNO  TRASLOG_JOBNO ,
	TEMP.PUR_AMT ,
	TEMP.PUR_DEDUCTION ,
	TEMP.PREV_IS_PUR_PRO_EXIST PREV_PUR_PRO, 
	TEMP.PREV_IS_PRO_EXIST_EARLIER_PUR_EXIST ,
	TEMP.PREV_IS_PRO_EXIST_PUR_EXIST_AFTER ,	
	TEMP.CURR_IS_PUR_PRO_EXIST , 
	TEMP.CURR_IS_PRO_EXIST_EARLIER_PUR_EXIST ,
	TEMP.CURR_IS_PRO_EXIST_PUR_EXIST_AFTER 
--	TEMP.TRASLOG_TRANSTYPE , 
--	''''+TEMP.TRASLOG_TRANSCODE TRASLOG_TRANSCODE,
--	TEMP.TRASLOG_TRANSDATE ,
--	--TEMP.TRASLOG_SUPPLIER ,
--	SM.SUP_NAME,
--	TEMP.TRASLOG_ACCTCODE , 
--	GM.ACCTNAME,                           
--	TEMP.TRASLOG_DRAMT ,                               
--	TEMP.TRASLOG_CRAMT ,
	
FROM #TRANSLOG_PUR_PRO_SUPPLIER TEMP
LEFT OUTER JOIN GENACCT_MASTER GM ON TEMP.ACCTCODE=GM.ACCTCODE
LEFT OUTER JOIN SUPPLIER_MASTER SM ON TEMP.PRO_SUPPLIER_TOP_1=SM.SUP_CODE
ORDER BY [DBO].[RPT_YYYYMMDD](TEMP.PRO_DATE)	



 

SELECT	'T1 - ONLY PROVISION' TYPE,
		TRANS.ACCTCODE,
		GM.ACCTNAME ACCNAME,
		ISNULL(SUM(ISNULL(TRANS.PRO_AMT,0)),0) DRAMT,
		0 CRAMT
FROM	#TRANSLOG_PUR_PRO_FINAL TRANS
		LEFT OUTER JOIN GENACCT_MASTER  GM WITH(READPAST) ON GM.ACCTCODE = TRANS.ACCTCODE                              
WHERE	TRANS.PREV_IS_PRO_EXIST_PUR_EXIST_AFTER=1 
GROUP BY TRANS.ACCTCODE, GM.ACCTNAME
UNION ALL
SELECT	DISTINCT 'T2 - ONLY PROVISION' TYPE,
		TRANS.PRO_SUPPLIER_TOP_1,
		SUP_NAME ACCNAME,
		0 DRAMT,
		SUM(ISNULL((ISNULL(TRANS.PRO_AMT,0)),0)) CRAMT
FROM	#TRANSLOG_PUR_PRO_SUPPLIER TRANS
		LEFT OUTER JOIN SUPPLIER_MASTER SM ON SM.SUP_CODE = TRANS.PRO_SUPPLIER_TOP_1
WHERE	TRANS.PREV_IS_PRO_EXIST_PUR_EXIST_AFTER=1 
GROUP BY TRANS.PRO_SUPPLIER_TOP_1, SUP_NAME
UNION ALL
SELECT	'T3 - ONLY PURCHASE' TYPE,
		TRANS.ACCTCODE,
		GM.ACCTNAME ACCNAME,
		ISNULL(SUM(ISNULL(PUR_AMT,0)),0) DRAMT,
		ISNULL(SUM(ISNULL(PUR_DEDUCTION,0)),0) CRAMT
FROM	#TRANSLOG_PUR_PRO_FINAL TRANS
		LEFT OUTER JOIN GENACCT_MASTER  GM WITH(READPAST) ON GM.ACCTCODE = TRANS.ACCTCODE                              
WHERE	TRANS.CURR_IS_PUR_PRO_EXIST=1 
GROUP BY TRANS.ACCTCODE, GM.ACCTNAME
UNION ALL
SELECT	DISTINCT 'T4 - ONLY PURCHASE' TYPE,
		TRANS.PRO_SUPPLIER_TOP_1,
		SUP_NAME ACCNAME,
		0 DRAMT,
		(ISNULL(SUM(ISNULL(TRASLOG_DRAMT,0)),0) - ISNULL(SUM(ISNULL(TRASLOG_CRAMT,0)),0)) CRAMT 
FROM	#TRANSLOG_PUR_PRO_SUPPLIER TRANS
		LEFT OUTER JOIN SUPPLIER_MASTER SM ON SM.SUP_CODE = TRANS.PRO_SUPPLIER_TOP_1
WHERE	TRANS.CURR_IS_PUR_PRO_EXIST=1 
GROUP BY TRANS.PRO_SUPPLIER_TOP_1, SUP_NAME


GO



--EXEC [USP_ACCT_GETTRIALBALANCE_DIFF_CODE_WISE] '1-APR-2013', '31-MAR-2014', '01', '101' ,'31-MAR-2014' 

ALTER PROCEDURE [dbo].[usp_Acct_GetTrialbalance_Diff_Code_Wise] --'1-Apr-2013', '31-Mar-2014', '01', '101' ,'31-MAR-2014'                
--declare                    
 @Fin_StartDate datetime,                              
 @Fin_EndDate datetime,                              
 @CompanyCode nvarchar(20),                              
 @CityCode nvarchar(20),
 @UsrEndDt datetime     
        
AS /*  

set @Fin_StartDate='1-Apr-2013'                          
set @Fin_EndDate='31-Mar-2014'
set @UsrEndDt ='31-Mar-2014'                       
set @CompanyCode='01'                           
set @CityCode='101'   
           
  --*/           

declare @st varchar(20),@dd varchar(20),@mm varchar(20),@yy varchar(20),@opbalst varchar(40)      
  set @st=@Fin_StartDate             
  set @dd=day(@st)      
  if len(@dd)< 2      
 set @dd='0'+@dd              
  set @mm=month(@st)       
  if len(@mm)< 2      
 set @mm='0'+@mm             
  set @yy=substring(convert(varchar,year(@st)),1,4)              
  set @opbalst=@dd+@mm+@yy       
       
  set @st=@Fin_EndDate             
  set @dd=day(@st)      
  if len(@dd)< 2      
 set @dd='0'+@dd              
  set @mm=month(@st)       
  if len(@mm)< 2      
 set @mm='0'+@mm             
  set @yy=substring(convert(varchar,year(@st)),2,3)              
  set @opbalst=@opbalst+@dd+@mm+@yy      
      
      
declare @OpBalTable varchar(100)      
set @OpBalTable='tbl_Master_'+ @opbalst +'_AllGL' 
     
--==================================================================================                              
--**********************************************************************************
/* Creat table where Client id's will be there and his total debit and total credit */                              
--**********************************************************************************
--==================================================================================
IF OBJECT_ID ('tempdb..#TRANSACTION_LOG_STDInv') is not null    
drop table #TRANSACTION_LOG_STDInv
                            
CREATE TABLE #TRANSACTION_LOG_STDInv(                              
 transtype nvarchar(3),                              
 transcode nvarchar(15),                              
 clientcode nvarchar(15),                              
 DrAmt decimal(18,2),                               
 CrAmt decimal(18,2)                              
)                       

IF OBJECT_ID ('tempdb..#TRANSACTION_LOG_SI_BI') is not null    
drop table #TRANSACTION_LOG_SI_BI

CREATE TABLE #TRANSACTION_LOG_SI_BI(                              
 transtype nvarchar(3),                              
 transcode nvarchar(15),                              
 clientcode nvarchar(15),                              
 DrAmt decimal(18,2),                               
 CrAmt decimal(18,2)                              
)  

IF OBJECT_ID ('tempdb..#TRANSACTION_LOG_Purchase') is not null    
drop table #TRANSACTION_LOG_Purchase

CREATE TABLE #TRANSACTION_LOG_Purchase(                              
 transtype nvarchar(3),                              
 transcode nvarchar(15),                              
 clientcode nvarchar(15),                              
 DrAmt decimal(18,2),                               
 CrAmt decimal(18,2)                              
)                                

IF OBJECT_ID ('tempdb..#TRANSACTION_LOG_Vouchers') is not null    
drop table #TRANSACTION_LOG_Vouchers

CREATE TABLE #TRANSACTION_LOG_Vouchers(                              
 transtype nvarchar(3),                              
 transcode nvarchar(15),                              
 clientcode nvarchar(15),                              
 DrAmt decimal(18,2),                               
 CrAmt decimal(18,2)                              
)  

IF OBJECT_ID ('tempdb..#TRANSACTION_LOG_CN') is not null    
drop table #TRANSACTION_LOG_CN

CREATE TABLE #TRANSACTION_LOG_CN(                              
 transtype nvarchar(3),                              
 transcode nvarchar(15),                              
 clientcode nvarchar(15),                              
 DrAmt decimal(18,2),                               
 CrAmt decimal(18,2)                              
)  

--===========================================================================                             
      
/* STEP 1: STANDARD INVOICE Only CREDIT all Charges                              
  CLIENT A/C          DR   XXXX.XX                              
    CHARGES A/C                      XXXX.XXX                              
*/  
--================================acc_invoice==========================================                              
	INSERT INTO #TRANSACTION_LOG_STDInv                        
	Select  '1II' transtype,                        
			acc_invoice.inv_no 'transcode',                        
			acc_invoice.inv_client 'clientcode',                         
			--(select  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0) from  acc_invcharge  
			-- where  acc_invcharge.inv_no = acc_invoice.inv_no) +                         
			--(select ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0) from  acc_invcharge1 
			-- where  acc_invcharge1.inv_no = acc_invoice.inv_no)
			0 'DrAmt',                        
			0 'CrAmt'                        
	From acc_invoice                        
	where (dbo.ConvertDate_IN_US(inv_date,'/') >= @Fin_StartDate) --'')                         
	and (dbo.ConvertDate_IN_US(inv_date,'/') <= @Fin_EndDate ) --'')                         
	and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDt )
	--and substring(acc_invoice.inv_no,1,2)  = @CompanyCode  
	AND acc_invoice.cmpcode  = @CompanyCode                    
	and substring(acc_invoice.inv_no,3,3)  = @CityCode 
    
     /*  ADDED BY SUJIT FOR GETTING INV TOTAL AMOUNT AS DR AMOUNT */
    
    UPDATE A
	SET DRAMT = B.INV_INRAMT
	FROM #TRANSACTION_LOG_STDInv A INNER JOIN (SELECT INV_NO ,ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) INV_INRAMT                                  
											   FROM	ACC_INVCHARGE    
											   GROUP BY INV_NO) B ON A.TRANSCODE=B.INV_NO   

	UPDATE A
	SET DRAMT = DRAMT + B.INV_INRAMT
	FROM #TRANSACTION_LOG_STDInv A INNER JOIN (SELECT INV_NO ,ISNULL(SUM(CONVERT(FLOAT,ISNULL(INV_INRAMT,0))),0) INV_INRAMT                                  
											   FROM	ACC_INVCHARGE1    
											   GROUP BY INV_NO) B ON A.TRANSCODE=B.INV_NO 
	
	/*  END OF INV TOTAL AMOUNT UPDATE STATEMENT */
	                   
--==================acc_invcharge==================================
	INSERT INTO #TRANSACTION_LOG_STDInv  
	SELECT  '2II' as 'transtype',                    
			acc_invoice.inv_no 'Transcode',                    
			acc_invcharge.inv_account 'clientcode',                    
			0 'DrAmt',                     
			convert(float,acc_invcharge.inv_inramt) 'CrAmt'                    
	FROM  acc_invcharge                     
		  LEFT OUTER JOIN acc_invoice ON acc_invoice.inv_no =  acc_invcharge.inv_no                    
	WHERE (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
	and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @Fin_EndDate) --'31-Mar-2007')                     
	and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDt )
	--and substring(acc_invoice.inv_no,1,2) = @CompanyCode --'01'                    
	AND acc_invoice.cmpcode  = @CompanyCode 
	and substring(acc_invoice.inv_no,3,3)  = @CityCode --'101'                    
	AND acc_invcharge.inv_inramt <> '0'   
--================acc_invcharge1====================================
	INSERT INTO #TRANSACTION_LOG_STDInv  
	SELECT  '3II' as 'transtype',                    
			acc_invoice.inv_no 'Transcode',                    
			acc_invcharge1.inv_account 'clientcode',                    
			0 'DrAmt',                     
			convert(float,acc_invcharge1.inv_inramt) 'CrAmt'                    
	FROM  acc_invcharge1                     
	LEFT OUTER JOIN acc_invoice ON acc_invoice.inv_no =  acc_invcharge1.inv_no                    
	WHERE  --acc_invcharge.inv_account = @ClientCode and -- 'G100893' AND                     
	(dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
	and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @Fin_EndDate) --'31-Mar-2007')                     
	and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDt )
	--and substring(acc_invoice.inv_no,1,2) = @CompanyCode --'01'                    
	AND acc_invoice.cmpcode  = @CompanyCode 
	and substring(acc_invoice.inv_no,3,3)  = @CityCode --'101'                    
	AND acc_invcharge1.inv_inramt <> '0'   
                     
--======================END OF STANDARD INVOICE=============================================                  
--==========================================================================================
                              
--=====================STARTING OF STORAGE AND BROKERAGE INVOICE============================                             
/* STEP 2: STORAGE INVOICE */ 
--==========================================================================================
                             
	INSERT INTO #TRANSACTION_LOG_SI_BI                              
	Select  '6SI' transtype,                              
			billno 'transcode',                              
			client 'clientcode',            
			(select ISNULL(sum(convert(float,ISNULL(amount,0))) ,0)                              
			from  ACC_STOREDTLS                               
			where  ACC_STOREDTLS.BILLNO = ACC_STORAGE.billno) 'DrAmt',                              
			0 AS 'CrAmt'                              
	From ACC_STORAGE                          
	where (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                               
	and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'')  
	and (dbo.ConvertDate_IN_US(billdt,'/') <= @UsrEndDt )                             
	--and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode 
	and ACC_STORAGE.cmpcode  = @CompanyCode                             
	and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                              
--************************************             
	INSERT INTO #TRANSACTION_LOG_SI_BI                                
	SELECT  '6SI' AS transtype, 
			dbo.acc_storedtls.billno AS transcode, 
			dbo.acc_storedtls.account AS clientcode, 
			0 AS DrAmt,
			dbo.acc_storedtls.amount AS CrAmt            
	FROM  dbo.acc_storage INNER JOIN            
		  dbo.acc_storedtls ON dbo.acc_storage.billno = dbo.acc_storedtls.billno            
	where (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                               
	and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'') 
	and (dbo.ConvertDate_IN_US(billdt,'/') <= @UsrEndDt )                              
	--and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                              
	and ACC_STORAGE.cmpcode  = @CompanyCode                             
	and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                          
             
--============================================================================            
/* STEP 3: BROKERAGE INVOICE */                              
--============================================================================            
	INSERT INTO #TRANSACTION_LOG_SI_BI                              
	Select  '7BI' transtype,                              
			acc_brokerage.brok_no 'transcode',                              
			brok_expcode 'clientcode',                               
			(select ISNULL(sum(convert(float,ISNULL(brkamt,0))) ,0) from  acc_brkgdtl                               
			 where  acc_brokerage.brok_no = acc_brkgdtl.brok_no) 'DrAmt',                              
			0 'CrAmt'                              
	From acc_brokerage                              
	where (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                               
	and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'')    
	and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @UsrEndDt )                           
	--and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode                              
	and acc_brokerage.cmpcode  = @CompanyCode                             
	and substring(acc_brokerage.brok_no,3,3)  = @CityCode                              
--*****************************************************************
          
	INSERT INTO #TRANSACTION_LOG_SI_BI                              
	SELECT  '7BI' AS transtype, 
			dbo.acc_brokerage.brok_no AS transcode, 
			dbo.acc_brkgdtl.brkaccount AS clientcode, 0 AS DrAmt,             
			dbo.acc_brkgdtl.brkamt AS CrAmt            
	FROM  dbo.acc_brokerage INNER JOIN            
		  dbo.acc_brkgdtl ON dbo.acc_brokerage.brok_no = dbo.acc_brkgdtl.brok_no                              
	where (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                               
	 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'')    
	 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @UsrEndDt )                           
	 --and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode 
	 and acc_brokerage.cmpcode  = @CompanyCode                              
	 and substring(acc_brokerage.brok_no,3,3)  = @CityCode                              
--========================================================================
--=====================END OF STORAGE AND BROKERAGE INVOICE===============                  
--========================================================================
     

--=====================STARTING OF PURCHASE INVOICE=======================                            
/* STEP 4: PURCHASE INVOICE - MAIN TABLE */                              
--========================================================================
	INSERT INTO #TRANSACTION_LOG_Purchase                              
	Select	'1PI' transtype,                              
			PUR_CODE 'transcode',                              
			PUR_SUPPLIER 'clientcode',                               
			0 'DrAmt',                              
			TOTALAMT 'CrAmt'                              
	From acc_purchase                              
	where (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                               
	and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'') 
	and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @UsrEndDt )                              
	--and substring(PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                              
	and acc_purchase.cmpcode  = @CompanyCode 
	and substring(PUR_CODE,3,3)  = @CityCode                    
--*********************************************************            
            
	INSERT INTO #TRANSACTION_LOG_Purchase            
	SELECT	'2PI' AS transtype,            
			dbo.acc_purchasedtls.pur_code as 'transcode',              
			dbo.acc_purchasedtls.pur_account AS clientcode,             
			convert(numeric(18,2),dbo.acc_purchasedtls.pur_amount) AS DrAmt,
			convert(numeric(18,2),dbo.acc_purchasedtls.pur_deduction) AS CrAmt        
	FROM dbo.acc_purchase INNER JOIN            
		 dbo.acc_purchasedtls ON dbo.acc_purchase.pur_code = dbo.acc_purchasedtls.pur_code            
	where (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                               
	and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'') 
	and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @UsrEndDt )                              
	--and substring(acc_purchase.PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                              
	and acc_purchase.cmpcode  = @CompanyCode
	and substring(acc_purchase.PUR_CODE,3,3)  = @CityCode                
 
--=========================================================================
--=====================END OF PURCHASE INVOICE============================                             
--=========================================================================

--=====================STARTING OF STORAGE AND BROKERAGE INVOICE============                     
/* STEP 5: CASH BOOK MAIN Table   */
--=========================================================================
	INSERT INTO #TRANSACTION_LOG_Vouchers                              
	select  '2' + acc_bank.status as 'transtype',                              
			acc_bank.EntryNo AS 'Transcode',                               
			ourbank 'Accode',                              
			dramt = CASE  acc_bank.status                               
			WHEN 'BR' THEN convert (float, actualamount)                              
			WHEN 'CR' THEN convert (float, actualamount)                                
			WHEN 'BP' THEN 0                              
			WHEN 'CP' THEN 0                              
			WHEN 'CE' THEN 0  END,                               
			cramt = CASE  acc_bank.status                               
			WHEN 'BP' THEN convert (float, actualamount)                              
			WHEN 'CP' THEN convert (float, actualamount)                                
			WHEN 'BR' THEN 0                              
			WHEN 'CR' THEN 0                              
			WHEN 'CE' THEN convert (float, actualamount)  END                              
	from acc_bank                               
	LEFT OUTER JOIN dbo.genacct_master ON acc_bank.ourbank = dbo.genacct_master.acctcode                              
	where  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate                              
	and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  
	and (dbo.ConvertDate_IN_US(entrydt,'/') <= @UsrEndDt )                            
	--and substring(acc_bank.EntryNo,1,2)  = @CompanyCode  
	and acc_bank.cmpcode  = @CompanyCode                              
	and substring(acc_bank.EntryNo,3,3)  = @CityCode                              
                          
--=========================================================================
/* STEP 6: CASH BOOK CHILD Table */ 
--=========================================================================
                             
	INSERT INTO #TRANSACTION_LOG_Vouchers                              
	select  '2' + acc_bank.status as 'transtype' ,                              
			acc_bankdtls.EntryNo 'transcode',                      
			client 'Accode',                              
			dramt = CASE  acc_bank.status                               
			WHEN 'BR' THEN convert (float, deduction)                              
			WHEN 'CR' THEN convert (float, deduction)                                
			WHEN 'BP' THEN convert (float, amount)                              
			WHEN 'CP' THEN convert (float, amount)                              
			WHEN 'CE' THEN convert (float, amount) END,                            
			cramt = CASE  acc_bank.status                               
			WHEN 'BP' THEN convert (float, deduction)                              
			WHEN 'CP' THEN convert (float, deduction)                                
			WHEN 'BR' THEN convert (float, amount)                              
			WHEN 'CR' THEN convert (float, amount)                              
			WHEN 'CP' THEN 0  END                              
	from acc_bankdtls                               
	INNER JOIN acc_bank ON acc_bank.EntryNo =  acc_bankdtls.EntryNo                                
	where dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate --@Fin_StartDate                              
	and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  --@Fin_EndDate
	and (dbo.ConvertDate_IN_US(entrydt,'/') <= @UsrEndDt )                              
	--and substring(acc_bank.EntryNo,1,2)  = @CompanyCode  --@CompanyCode                              
	AND acc_bank.cmpcode= @CompanyCode
	and substring(acc_bank.EntryNo,3,3)  = @CityCode  --@CityCode                              
                        
--===========================================================      
/* STEP 7: JOURNAL VOUCHER Table */
--===========================================================      
                              
	INSERT INTO #TRANSACTION_LOG_Vouchers   
	select  '3JV' as 'transtype',                               
			acc_JournalVoucDtls.jvcode 'transcode',                              
			jv_account 'Accode',                               
			convert (float, jv_Debit)'dramt',                               
			convert (float, jv_Credit) 'cramt'                        
	from  acc_JournalVoucDtls                               
		INNER JOIN acc_JournalVouc ON acc_JournalVouc.jvcode = acc_JournalVoucDtls.jvcode                               
		LEFT OUTER JOIN dbo.exp_master ON acc_JournalVoucDtls.jv_account = dbo.exp_master.exp_code                               
		LEFT OUTER JOIN dbo.supplier_master ON acc_JournalVoucDtls.jv_account = dbo.supplier_master.sup_code                               
		LEFT OUTER JOIN dbo.genacct_master ON acc_JournalVoucDtls.jv_account = dbo.genacct_master.acctcode                              
	where  dbo.ConvertDate_IN_US(jv_Date,'/') >= @Fin_StartDate                              
	and dbo.ConvertDate_IN_US(jv_Date,'/') <= @Fin_EndDate            
	and (dbo.ConvertDate_IN_US(jv_Date,'/') <= @UsrEndDt )                  
	--and substring(acc_JournalVoucDtls.jvcode,1,2)  = @CompanyCode  
	and acc_JournalVouC.cmpcode  = @CompanyCode                              
	and substring(acc_JournalVoucDtls.jvcode,3,3)  =  @CityCode                              
                              
--===========================================================      
/* STEP 8: CREDIT NOTE Table */ 
--======================acc_creditnote=====================================      
                              
	INSERT INTO #TRANSACTION_LOG_CN                        
	Select	'4CN' as transtype,                        
			acc_creditnote.crt_no as 'transcode',                        
			acc_creditnote.crt_client as 'clientcode',                         
			0 as 'DrAmt',                        
			convert(float,isnull(totalamt,0)) as 'CrAmt'                        
	From acc_creditnote                        
	where (dbo.ConvertDate_IN_US(crt_date,'/') >= @Fin_StartDate) --'')                     
	and (dbo.ConvertDate_IN_US(crt_date,'/') <= @Fin_EndDate ) --'')                         
	and (dbo.ConvertDate_IN_US(crt_date,'/') <= @UsrEndDt )
	and substring(acc_creditnote.crt_no,1,2)  = @CompanyCode --@CompanyCode                        
	and substring(acc_creditnote.crt_no,3,3)  = @CityCode       
--=====================acc_crtcharge======================================      

	INSERT INTO #TRANSACTION_LOG_CN            
	SELECT  '4CN' as 'transtype',                    
			acc_creditnote.crt_no 'Transcode',                    
			acc_crtcharge.crt_account 'clientcode',
			convert(float,isnull(acc_crtcharge.crt_inramt,0)) 'DrAmt',                     
			0 'CrAmt'                    
	FROM  acc_crtcharge                     
	LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge.crt_no                    
	WHERE  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
	and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')                     
	and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @UsrEndDt )
	--and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'                    
	and acc_creditnote.cmpcode  = @CompanyCode                              
	and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
	AND acc_crtcharge.crt_inramt <> '0'  
--====================acc_crtcharge1======================================= 
     
	INSERT INTO #TRANSACTION_LOG_CN            
	SELECT  '4CN' as 'transtype',                    
			acc_creditnote.crt_no 'Transcode',                    
			acc_crtcharge1.crt_account 'clientcode',
			convert(float,isnull(acc_crtcharge1.crt_inramt,0)) 'DrAmt',                     
			0 'CrAmt'                    
	FROM  acc_crtcharge1                     
	LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge1.crt_no                    
	WHERE  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
	and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')                     
	and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @UsrEndDt )
	--and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'
	and acc_creditnote.cmpcode  = @CompanyCode                     
	and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
	AND acc_crtcharge1.crt_inramt <> '0' 
                 
--===========================================================      
--=============================================================================================
--Start getting any Difference From The Above Transaction
--=============================================================================================

	IF OBJECT_ID ('tempdb..#TempTranDiff_STDInv') is not null    
	drop table #TempTranDiff_STDInv

	IF OBJECT_ID ('tempdb..#TempTranDiff_SI_BI') is not null    
	drop table #TempTranDiff_SI_BI

	IF OBJECT_ID ('tempdb..#TempTranDiff_Purchase') is not null    
	drop table #TempTranDiff_Purchase

	IF OBJECT_ID ('tempdb..#TempTranDiff_Vouchers') is not null    
	drop table #TempTranDiff_Vouchers

	IF OBJECT_ID ('tempdb..#TempTranDiff_CN') is not null    
	drop table #TempTranDiff_CN

--========================================================================
	select '1II' AS Transtype,
			TRANSCODE,sum(DrAmt) as DrAmt,Sum(CrAmt) as CrAmt,(sum(DrAmt)- Sum(CrAmt)) as Diff
	INTO #TempTranDiff_STDInv
	from #TRANSACTION_LOG_STDInv --where transtype IN('3II','1II','2II')
	GROUP BY TRANSCODE
--================================
	select Transtype=CASE substring(TRANSCODE,10,1) 
						WHEN '2' THEN 'BI'  
						WHEN '3' THEN 'SI' END  ,
		   TRANSCODE,sum(DrAmt) as DrAmt,Sum(CrAmt) as CrAmt,(sum(DrAmt)- Sum(CrAmt)) as Diff
	INTO #TempTranDiff_SI_BI
	from #TRANSACTION_LOG_SI_BI --where transtype IN('SI','BI')
	GROUP BY TRANSCODE
--================================
	select Transtype=CASE substring(TRANSCODE,12,1) WHEN '9' THEN 'PI'  END  ,
		   TRANSCODE,sum(DrAmt) as DrAmt,Sum(CrAmt) as CrAmt,(sum(DrAmt)- Sum(CrAmt)) as Diff
	INTO #TempTranDiff_Purchase
	from #TRANSACTION_LOG_Purchase --where transtype IN('PI')
	GROUP BY TRANSCODE
--================================

	select transtype =CASE substring(TRANSCODE,12,1) 
						WHEN '1' THEN 'BR'  
						WHEN '2' THEN 'BP'
						WHEN '7' THEN 'CR'  
						WHEN '8' THEN 'CP'
						WHEN '9' THEN 'CE' END ,
	TRANSCODE,sum(DrAmt) as DrAmt,Sum(CrAmt) as CrAmt,(sum(DrAmt)- Sum(CrAmt)) as Diff
	INTO #TempTranDiff_Vouchers
	from #TRANSACTION_LOG_Vouchers 
	GROUP BY TRANSCODE
--================================

	SELECT transtype=CASE substring(TRANSCODE,10,1) WHEN '7' THEN 'CN' END, 
		   TRANSCODE,sum(DrAmt) as DrAmt,Sum(CrAmt) as CrAmt,(sum(DrAmt)- Sum(CrAmt)) as Diff
	INTO #TempTranDiff_CN
	from #TRANSACTION_LOG_CN 
	GROUP BY TRANSCODE
--=============================================================================================
select 'StdInvoice' as StdInvoice,* from #TempTranDiff_STDInv where diff<>0
select 'Storage/Brokerage Inv' as 'Storage/Brokerage Inv' ,* from #TempTranDiff_SI_BI where diff<>0
select 'Purchase' as 'Purchase',* from #TempTranDiff_Purchase where diff<>0
select 'CreditNote' as 'CreditNote',* from #TempTranDiff_CN where diff<>0
select 'Vouchers' as Vouchers ,* from #TempTranDiff_Vouchers where diff<>0

--=========================================================================
