create table #group (clientcode varchar(20),groupcode varchar(200))    
insert into #group (clientcode,groupcode)    
 select  acctcode,undergroup from genacct_master where undergroup<>'0'    
insert into #group (clientcode,groupcode)    
 select sup_code,sup_grpcode from supplier_master where sup_grpcode is not null    
insert into #group (clientcode,groupcode)    
 select exp_code,clientgrp from exp_master where clientgrp is not null 
----------------------------------    
  If(@ShowOpBal = 1)    
  Begin    
 SET @str3 = 'select case when exp_master.EXP_NAME  is not null then exp_master.EXP_NAME  
     when supplier_master.sup_name is not null then supplier_master.sup_name  
     when genacct_master.acctname is not null then genacct_master.acctname end as exp_name ,'+ @optbl +'.name,' + @colString1 +  ' into table3 from ##det     
    lEFT OUTER jOIN exp_master on exp_master.exp_code = ##det.Particulars  
 lEFT OUTER jOIN genacct_master on genacct_master.acctcode = ##det.Particulars   
 lEFT OUTER jOIN supplier_master on supplier_master.sup_code = ##det.Particulars
 left outer join #group on #group.clientcode= ##det.Particulars
 left outer join '+ @optbl +' on '+ @optbl +'.code= #group.groupcode 
  Order By exp_master.exp_code'    
  
/*  
   SET @str3 = 'select exp_master.EXP_NAME + supplier_master.sup_name + genacct_master.acctname,' + @colString1 +  ' into qw from ##det     
   lEFT OUTER jOIN exp_master on exp_master.exp_code = ##det.Particulars left outer join supplier_master on supplier_master.sup_code=##det.Particulars  
    lEFT OUTER jOIN genacct_master on  genacct_master.acctcode=##det.Particulars  
   Order By exp_master.EXP_NAME + supplier_master.sup_name + genacct_master.acctname'   
   --exec('select * from  qw')  
   --exec('select * into table3 from qw')  
  */ 
	print @str3   
   exec (@str3)    
  End    
  Else      
  Begin     
   SET @str3 = 'select exp_master.EXP_NAME,' + @colString +  ' into table3 from ##det     
   lEFT OUTER jOIN exp_master on exp_master.exp_code = ##det.Particulars Order By exp_master.EXP_NAME'    
   --print @str3    
   exec (@str3)    
  End     
