 if object_id('tempdb..##TempAllCity') is not null    
   drop table ##TempAllCity    
 declare @StrSql123 nvarchar(4000)    
 set @StrSql123 = ''    
 If(@cmpcount > 1)    
 Begin    
      
  declare @ColName varchar(50), @cnt int, @colStr varchar(8000), @StrSql varchar(8000)    
  declare @colStr1 varchar(8000)    
  declare @colStr2 varchar(8000)    
  declare @colStrAdCr varchar(8000)    
  declare @colStrOP varchar(8000)    
  declare @colStrTDr varchar(8000)    
  declare @colStrTCr varchar(8000)    
  declare @colStrCl varchar(8000)    
  declare @condition varchar(8000)    
  declare @condition1 varchar(8000)    
  declare @Coloumn varchar(8000)     
     
  set @cnt = 2    
  set @colStr = ''    
  set @colStr1 = ''    
  set @colStrAdCr = ''    
  set @colStrOP = ''    
  set @colStrTDr = ''    
  set @colStrTCr = ''    
  set @colStrCl = ''    
  set @condition = ''    
  set @Coloumn = ''    
    
  If(@ShowOpBal = '1')    
  Begin    
   SELECT @ColName = COL_NAME(OBJECT_ID('table3'), 1)    
     
   While @ColName is not null    
   begin     
    if(right(@ColName, 4) = 'OPDr')    
    Begin    
     SET @colStrOP = @colStrOP + 'IsNull(['+ @ColName + '], 0) - '    
    End    
    if(right(@ColName, 4) = 'OPCr')    
    Begin    
     SET @colStrOP = @colStrOP + 'IsNull(['+ @ColName + '], 0) + '    
    End     
    if(right(@ColName, 3) = 'TDR')    
    Begin    
     SET @colStrTDr = @colStrTDr + 'IsNull(['+ @ColName + '], 0) + '    
    End    
    if(right(@ColName, 3) = 'TCR')    
    Begin    
     SET @colStrTCr = @colStrTCr + 'IsNull(['+ @ColName + '], 0) + '    
    End      
    if(right(@ColName, 4) = 'ClDR')    
    Begin    
     SET @colStrCl = @colStrCl + 'IsNull(['+ @ColName + '], 0) - '    
    End    
    if(right(@ColName, 4) = 'ClCR')    
    Begin    
     SET @colStrCl = @colStrCl + 'IsNull(['+ @ColName + '], 0) + '    
    End    
        
    /*if(right(@ColName, 4) = 'AdCr')    
    Begin    
     SET @colStrAdCr = @colStrAdCr + 'IsNull(['+ @ColName + '], 0) + '    
    End*/        
        
    SELECT @ColName = COL_NAME(OBJECT_ID('table3'), @cnt)     
    --set @Coloumn = @Coloumn + ' sum(convert(decimal(15,2), isnull( ['+ @ColName + '] , 0))) as [' + @ColName + '] , '      
    set @cnt = @cnt + 1    
        
   end    
   
   Set @colStrTDr = SUBSTRING(@colStrTDr, 1, LEN(@colStrTDr) - 1)    
   Set @colStrTCr = SUBSTRING(@colStrTCr, 1, LEN(@colStrTCr) - 1)    
   --Set @colStrAdCr = SUBSTRING(@colStrAdCr, 1, LEN(@colStrAdCr) - 1)    
   Set @colStrOP = SUBSTRING(@colStrOP, 1, LEN(@colStrOP) - 1)    
   Set @colStrCl = SUBSTRING(@colStrCl, 1, LEN(@colStrCl) - 1)    
       
   set @condition = @colStrTDr + ' <> 0 OR ' + @colStrTCr + ' <> 0  OR ' + @colStrOP + ' <> 0 OR ' + @colStrCl --OR ' + @colStrAdCr + ' <> 0   
   set @condition = replace(@condition, '+', '<> 0 OR')    
   set @condition = replace(@condition, '-', '<> 0 OR')    
   set @condition = @condition + ' <> 0'    
       
       
    
   Set @StrSql = 'Select *, case when (' + @colStrOP + ') > 0 then abs(' + @colStrOP + ') end  as TotalOPDr, case when (' + @colStrOP + ') < 0 then abs(' + @colStrOP + ') end  as TotalOPCr, ' + @colStrTDr + ' as TotalTDR, ' + @colStrTCr + ' as TotalTCR,  
  
case when (' + @colStrCl + ') > 0 then abs(' + @colStrCl + ') end  as TotalClDr, case when (' + @colStrCl + ') < 0 then abs(' + @colStrCl + ') end  as TotalClCr  into ##TempAllCity from table3 where ' + @condition    
   
    print @StrSql 
   exec(@StrSql) 
    print @StrSql   
   select * from ##TempAllCity order by exp_name      
   set @StrSql123 = 'Select '''',  ' + @columnString1 + ' sum(isnull(TotalOPDr, 0)) as TotalOPDr, sum(isnull(TotalOPCr, 0)) , sum(isnull(TotalTDR, 0)) as TotalTDR, sum(isnull(TotalTCR, 0)) as TotalTCR,  sum(isnull(TotalClDr, 0)) as TotalClDr, sum(isnull(TotalClCr, 0)) as TotalClCr   from ##TempAllCity  ' --, sum(isnull(TotalAdCr, 0)) as TotalAdCr   
   
   exec(@StrSql123)    
      
   
    
  End    
  else    
  Begin    
   SELECT @ColName = COL_NAME(OBJECT_ID('table3'), 1)    
     
   While @ColName is not null    
   begin     
       
    if(right(@ColName, 4) = 'ClDR')     
    Begin    
     SET @colStr = @colStr + 'IsNull(['+ @ColName + '], 0) + '    
     SET @condition = @condition + ' [' + @ColName +  '] is not null or'     
    End    
    if(right(@ColName, 4) = 'ClCR')    
    Begin    
     SET @colStr1 = @colStr1 + 'IsNull(['+ @ColName + '], 0) + '    
     SET @condition = @condition + ' [' + @ColName +  '] is not null or'     
    End    
    /*if(right(@ColName, 4) = 'AdCr')    
    Begin    
     SET @colStrAdCr = @colStrAdCr + 'IsNull(['+ @ColName + '], 0) + '    
     SET @condition = @condition + ' [' + @ColName +  '] is not null or'     
    End*/    
    SELECT @ColName = COL_NAME(OBJECT_ID('table3'), @cnt)     
        
    set @cnt = @cnt + 1        
   end       
   
    
   Set @colStr = SUBSTRING(@colStr, 1, LEN(@colStr) - 1)    
   Set @colStr1 = SUBSTRING(@colStr1, 1, LEN(@colStr1) - 1)    
   --Set @colStrAdCr = SUBSTRING(@colStrAdCr, 1, LEN(@colStrAdCr) - 1)       
       
   Set @condition1 = REPLACE(@condition, 'is not null','<> 0')    
   Set @condition1 = SUBSTRING(rtrim(@condition1), 1, LEN(@condition1) - 3)    
    
   set @condition = @condition + ' ' + @condition1    
    
   Set @StrSql = 'Select *, ' + @colStr + ' as TotalClDR, ' + @colStr1 + ' as TotalClCR into ##TempAllCity  from  table3 where ' + @condition --, ' + @colStrAdCr + ' as TotalAdCr   
   exec(@StrSql)    
   select * from ##TempAllCity       
   set @StrSql123 = 'Select '''',  ' + @columnString + ' sum(isnull(TotalClDR, 0)) as TotalClDR, sum(isnull(TotalClCR, 0))  from ##TempAllCity  '  --, sum(isnull(TotalAdCr, 0)) as TotalAdCr  
   
   exec(@StrSql123)    
   
  End     
   
      
 End    
ELSE    
BEGIN    
	SET @CONDITION = ''    
	SET @CNT = 2       
	SET @COLOUMN = ''    
	SELECT @COLNAME = COL_NAME(OBJECT_ID('TABLE3'), 1)    

	WHILE @COLNAME IS NOT NULL    
	BEGIN      
		IF(RIGHT(@COLNAME, 4) = 'CLDR') OR (RIGHT(@COLNAME, 4) = 'CLCR') --OR (RIGHT(@COLNAME, 4) = 'ADCR')    
		BEGIN    
			SET @CONDITION = @CONDITION + ' [' + @COLNAME +  '] IS NOT NULL OR'      
		END     

		SELECT @COLNAME = COL_NAME(OBJECT_ID('TABLE3'), @CNT)    
		SET @COLOUMN = @COLOUMN + ' SUM(CONVERT(DECIMAL(15,2), ISNULL( ['+ @COLNAME + '] , 0))) AS [' + @COLNAME + '] , '     
		SET @CNT = @CNT + 1        
	END       

	SET @COLOUMN = SUBSTRING(@COLOUMN, 1, LEN(@COLOUMN)-1)    
	PRINT @COLOUMN    
	--PRINT @COLSTRADCR      
	SET @CONDITION1 = REPLACE(@CONDITION, 'IS NOT NULL','<> 0')    
	SET @CONDITION1 = SUBSTRING(RTRIM(@CONDITION1), 1, LEN(@CONDITION1) - 3)    

	SET @CONDITION = @CONDITION + ' ' + @CONDITION1    

	SET @STRSQL = 'SELECT * FROM TABLE3 WHERE ' + @CONDITION    
	EXEC(@STRSQL)    


	IF(@SHOWOPBAL = '1')    
	BEGIN    
		SET @COLUMNSTRING1 = SUBSTRING(@COLUMNSTRING1, 1, LEN(@COLUMNSTRING1)-1)    
		SET @STRSQL123 = 'SELECT '''',  ' + @COLUMNSTRING1 + ' FROM TABLE3  '    
	END    
	ELSE    
	BEGIN    
		SET @COLUMNSTRING = SUBSTRING(@COLUMNSTRING, 1, LEN(@COLUMNSTRING)-1)    
		SET @STRSQL123 = 'SELECT '''',  ' + @COLUMNSTRING + ' FROM TABLE3  '    
	END      

	EXEC(@STRSQL123)    


END    
   
drop table table3    
drop table #group




GO





--usp_Acct_RPT_Trialbalance_ALL_test '01-Apr-2007','31-Mar-2008','01101,02101,03101,04101,05101,07101,08101,','1'   

ALTER PROCEDURE [dbo].[usp_Acct_RPT_Trialbalance_bygrp_ALL]    
--declare  
 @Fin_StartDate datetime,    
 @Fin_EndDate datetime,    
 @CompanyCityCode nvarchar(200),    
 @ShowOpBal NVARCHAR(1)    
 --@CityCode nvarchar(20)    
AS    
/*
set @Fin_StartDate='01-Apr-2006'  
set @Fin_EndDate='31-Mar-2007'  
set @CompanyCityCode='01101,'  
set @ShowOpBal=0  0r --@ShowOpBal=0
*/
--//////////////////////////////// 

declare @st varchar(20),@dd varchar(20),@mm varchar(20),@yy varchar(20),@opbalst varchar(40),@colStringX varchar(4000),@colStringY varchar(4000)    
  set @st=@Fin_StartDate           
  set @dd=day(@st)    
  if len(@dd)< 2    
 set @dd='0'+@dd            
  set @mm=month(@st)     
  if len(@mm)< 2    
 set @mm='0'+@mm           
  set @yy=substring(convert(varchar,year(@st)),1,4)            
  set @opbalst=@dd+@mm+@yy     
     
  set @st=@Fin_EndDate           
  set @dd=day(@st)    
  if len(@dd)< 2    
 set @dd='0'+@dd            
  set @mm=month(@st)     
  if len(@mm)< 2    
 set @mm='0'+@mm           
  set @yy=substring(convert(varchar,year(@st)),2,3)            
  set @opbalst=@opbalst+@dd+@mm+@yy    
    
    
declare @optbl varchar(100)    
set @optbl='tbl_Master_'+ @opbalst +'_AllGL'    
--////////////////////////////////    
if object_id('tempdb..#TRANSLOG') is not null    
drop table #TRANSLOG    
    
 CREATE TABLE #TRANSLOG    
 (    
  transtype nvarchar(3),    
  transcode nvarchar(15),    
  clientcode nvarchar(15),    
  DrAmt DECIMAL(18,2),     
  CrAmt DECIMAL(18,2),    
  ACrAmt DECIMAL(18,2)    
 )    
    
    
 /* STEP 1: INVOICE Table */      
 INSERT INTO #TRANSLOG                    
select                          
 '1II' transtype,                                
 acc_invoice.inv_no 'transcode',                                
 Vw_invChargeCode.clientcode 'clientcode',                                 
 0 'DrAmt',                                
 convert(float,Vw_invChargeCode.amt)                                
  'CrAmt',    
    0 'ACrAmt'                             
From acc_invoice inner join Vw_invChargeCode on  acc_invoice.inv_no= Vw_invChargeCode.inv_no                             
where                                
 (dbo.ConvertDate_IN_US(inv_date,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(inv_date,'/') <=@Fin_EndDate  ) --'')                                 
 --and substring(acc_invoice.inv_no,1,2)  = @CompanyCode --@CompanyCode                                
-- and substring(acc_invoice.inv_no,3,3)  = @CityCode                  
--////////////////////////////////////////              
INSERT INTO #TRANSLOG                                
Select                                  
 '1II' transtype,                                
 acc_invoice.inv_no 'transcode',                                
 acc_invoice.inv_client 'clientcode',                                 
 (select  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0)                                
 from  acc_invcharge                                 
 where  acc_invcharge.inv_no = acc_invoice.inv_no) +                                 
 (select                                 
  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0)                                
 from  acc_invcharge1                                 
 where  acc_invcharge1.inv_no = acc_invoice.inv_no) 'DrAmt',                                
 0                                
  'CrAmt',  
   0 'ACrAmt'                                
From acc_invoice                                
where                                
 (dbo.ConvertDate_IN_US(inv_date,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(inv_date,'/') <= @Fin_EndDate ) --'')                                 
-- and substring(acc_invoice.inv_no,1,2)  = @CompanyCode --@CompanyCode                                
-- and substring(acc_invoice.inv_no,3,3)  = @CityCode    
     
     
     
/* STEP 2: CASH BOOK MAIN Table   */                                 
INSERT INTO #TRANSLOG                                
select   '2' + acc_bank.status as 'transtype',                                
  acc_bank.EntryNo AS 'Transcode',                                 
  ourbank 'Accode',                                
  dramt = CASE  acc_bank.status                                 
    WHEN 'BR' THEN convert (float, actualamount)                                
    WHEN 'CR' THEN convert (float, actualamount)                                  
    WHEN 'BP' THEN 0                                
    WHEN 'CP' THEN 0                                
    WHEN 'CE' THEN 0                                
   END,                                 
  cramt = CASE  acc_bank.status                                 
    WHEN 'BP' THEN convert (float, actualamount)                                
    WHEN 'CP' THEN convert (float, actualamount)                                  
    WHEN 'BR' THEN 0                                
    WHEN 'CR' THEN 0                                
    WHEN 'CE' THEN convert (float, actualamount)                                
   END,  
   0 'ACrAmt'                                
 from acc_bank                                 
 LEFT OUTER JOIN dbo.genacct_master ON acc_bank.ourbank = dbo.genacct_master.acctcode                                
 where  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate                                
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate                                
  --and substring(acc_bank.EntryNo,1,2)  = @CompanyCode                                
 -- and substring(acc_bank.EntryNo,3,3)  = @CityCode                                
                                
                                
/* STEP 3: CASH BOOK CHILD Table */                                
INSERT INTO #TRANSLOG                                
 select  '2' + acc_bank.status as 'transtype' ,                                
  acc_bankdtls.EntryNo 'transcode',                        
  client 'Accode',                                
  dramt = CASE  acc_bank.status                                 
    WHEN 'BR' THEN convert (float, deduction)                                
    WHEN 'CR' THEN convert (float, deduction)                                  
    WHEN 'BP' THEN convert (float, amount)                                
    WHEN 'CP' THEN convert (float, amount)                                
    WHEN 'CE' THEN convert (float, amount)                                
   END,                              
  cramt = CASE  acc_bank.status                                 
    WHEN 'BP' THEN convert (float, deduction)                                
    WHEN 'CP' THEN convert (float, deduction)                                  
    WHEN 'BR' THEN convert (float, amount)                                
    WHEN 'CR' THEN convert (float, amount)                                
    WHEN 'CP' THEN 0                                  
   END ,  
   0 'ACrAmt'                               
 from acc_bankdtls                                 
   INNER JOIN acc_bank ON acc_bank.EntryNo =  acc_bankdtls.EntryNo                                  
                                  
 where                                 
  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate --@Fin_StartDate                                
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  --@Fin_EndDate                                
  --and substring(acc_bank.EntryNo,1,2)  = @CompanyCode  --@CompanyCode                                
  --and substring(acc_bank.EntryNo,3,3)  = @CityCode  --@CityCode         
 /* STEP 3: CASH BOOK CHILD Table for Advance Amount*/     
 INSERT INTO #TRANSLOG    
 select  '2' + acc_bank.status as 'transtype' ,    
  acc_bankdtls.EntryNo 'transcode',     
  client 'Accode',    
  0 'dramt',    
  0 'cramt',      
  ACrAmt = CASE  acc_bank.status     
    WHEN 'BP' THEN convert (float, deduction)    
    WHEN 'CP' THEN convert (float, deduction)      
    WHEN 'BR' THEN convert (float, amount)    
    WHEN 'CR' THEN convert (float, amount)    
    WHEN 'CP' THEN 0         END    
 from acc_bankdtls     
  INNER JOIN acc_bank ON acc_bank.EntryNo =  acc_bankdtls.EntryNo     
 where     
  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate --@Fin_StartDate    
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  --@Fin_EndDate       
  and entrytype = 'AD'    
     
     
 /* STEP 4: JOURNAL VOUCHER Table */    
INSERT INTO #TRANSLOG                                
 select  '3JV' as 'transtype',                
  acc_JournalVoucDtls.jvcode 'transcode',                                
  jv_account 'Accode',                                 
  convert (float, jv_Debit)'dramt',                                 
  convert (float, jv_Credit) 'cramt',  
   0 'ACrAmt'                                
 from  acc_JournalVoucDtls                                 
  INNER JOIN acc_JournalVouc ON acc_JournalVouc.jvcode = acc_JournalVoucDtls.jvcode                                 
  LEFT OUTER JOIN dbo.exp_master ON acc_JournalVoucDtls.jv_account = dbo.exp_master.exp_code                                 
  LEFT OUTER JOIN dbo.supplier_master ON acc_JournalVoucDtls.jv_account = dbo.supplier_master.sup_code                                 
  LEFT OUTER JOIN dbo.genacct_master ON acc_JournalVoucDtls.jv_account = dbo.genacct_master.acctcode                                
 where  dbo.ConvertDate_IN_US(jv_Date,'/') >= @Fin_StartDate                                
  and dbo.ConvertDate_IN_US(jv_Date,'/') <= @Fin_EndDate                                
 -- and substring(acc_JournalVoucDtls.jvcode,1,2)  = @CompanyCode                                
  --and substring(acc_JournalVoucDtls.jvcode,3,3)  =  @CityCode   
    
 INSERT INTO #TRANSLOG    
 select  '3JV' as 'transtype',     
  acc_JournalVoucDtls.jvcode 'transcode',    
  jv_account 'Accode',     
  0 'dramt',     
  0 'cramt',    
  convert (float, jv_Credit)  'ACrAmt'    
 from  acc_JournalVoucDtls     
  INNER JOIN acc_JournalVouc ON acc_JournalVouc.jvcode = acc_JournalVoucDtls.jvcode     
  LEFT OUTER JOIN dbo.exp_master ON acc_JournalVoucDtls.jv_account = dbo.exp_master.exp_code     
  LEFT OUTER JOIN dbo.supplier_master ON acc_JournalVoucDtls.jv_account = dbo.supplier_master.sup_code     
  LEFT OUTER JOIN dbo.genacct_master ON acc_JournalVoucDtls.jv_account = dbo.genacct_master.acctcode    
 where  dbo.ConvertDate_IN_US(jv_Date,'/') >= @Fin_StartDate  --'1-Apr-2006' --    
  and dbo.ConvertDate_IN_US(jv_Date,'/') <= @Fin_EndDate -- '31-Mar-2007'--     
  and entrytype = 'AD'    
  --  and substring(acc_JournalVoucDtls.jvcode,1,2)  = '01'    
  --  and substring(acc_JournalVoucDtls.jvcode,3,3)  =  '102'    
     
     
     
   
 /* STEP 5: CREDIT NOTE Table */                                
                                
INSERT INTO #TRANSLOG                                
Select                                  
 '5CN' transtype,                                
 acc_creditnote.crt_no 'transcode',                                
 acc_creditnote.crt_client 'clientcode',                                 
 0 'DrAmt',                                
 (select                                 
  ISNULL(sum(convert(float,ISNULL(crt_amount,0))),0)                                
 from  acc_crtcharge                                 
 where  acc_crtcharge.crt_no = acc_creditnote.crt_no) +                                 
 (select                                 
  ISNULL(sum(convert(float,ISNULL(crt_amount,0))),0)                                
 from  acc_crtcharge1                                 
 where  acc_crtcharge1.crt_no = acc_creditnote.crt_no)                                
  'CrAmt'  ,  
   0 'ACrAmt'                                                     
From acc_creditnote                                
where                                
 (dbo.ConvertDate_IN_US(crt_date,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(crt_date,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(acc_creditnote.crt_no,1,2)  = @CompanyCode --@CompanyCode                            
 --and substring(acc_creditnote.crt_no,3,3)  = @CityCode                                
 --///////////////////////////////////////              
INSERT INTO #TRANSLOG                  
Select                                  
 '5CN' transtype,                                
 acc_creditnote.crt_no 'transcode',                                
 Vw_CrtInvCode.clientcode 'clientcode',                                 
 Vw_CrtInvCode.amt 'DrAmt',                                
 0  'CrAmt',  
   0 'ACrAmt'                                                       
From acc_creditnote inner join Vw_CrtInvCode on acc_creditnote.crt_no= Vw_CrtInvCode.crt_no                              
where                                
 (dbo.ConvertDate_IN_US(crt_date,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(crt_date,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(acc_creditnote.crt_no,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(acc_creditnote.crt_no,3,3)  = @CityCode               
--////////////////////////////////////////                               
                                
/* STEP 6: STORAGE INVOICE */                                
INSERT INTO #TRANSLOG                                
Select                                  
 '6SI' transtype,                                
 billno 'transcode',                                
 client 'clientcode',                                 
 (select ISNULL(sum(convert(float,ISNULL(amount,0))) ,0)                                
 from  ACC_STOREDTLS                                 
 where  ACC_STOREDTLS.BILLNO = ACC_STORAGE.billno) 'DrAmt',                                
 0 'CrAmt' ,  
   0 'ACrAmt'                                                      
From ACC_STORAGE                            
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                
 (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                                
               
INSERT INTO #TRANSLOG                                  
SELECT     '6SI' AS transtype, dbo.acc_storedtls.billno AS transcode, dbo.acc_storedtls.account AS clientcode, 0 AS DrAmt,               
                      dbo.acc_storedtls.amount AS CrAmt,  
   0 'ACrAmt'                                     
FROM         dbo.acc_storage INNER JOIN              
                      dbo.acc_storedtls ON dbo.acc_storage.billno = dbo.acc_storedtls.billno              
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'            
 (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                            
               
              
              
/* STEP 7: BROKERAGE INVOICE */                                
                                
INSERT INTO #TRANSLOG                                
Select                                  
 '7BI' transtype,                                
 acc_brokerage.brok_no 'transcode',                                
 brok_expcode 'clientcode',                                 
 (select ISNULL(sum(convert(float,ISNULL(brkamt,0))) ,0)                                
 from  acc_brkgdtl                                 
 where  acc_brokerage.brok_no = acc_brkgdtl.brok_no) 'DrAmt',                                
 0 'CrAmt',  
   0 'ACrAmt'                 
                                
From acc_brokerage                                
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                
 (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(acc_brokerage.brok_no,3,3)  = @CityCode                                
-- /////////////////////////////////////              
INSERT INTO #TRANSLOG                                
                                 
SELECT     '7BI' AS transtype, dbo.acc_brokerage.brok_no AS transcode, dbo.acc_brkgdtl.brkaccount AS clientcode, 0 AS DrAmt,               
                      dbo.acc_brkgdtl.brkamt AS CrAmt,  
   0 'ACrAmt'                                     
FROM         dbo.acc_brokerage INNER JOIN              
                      dbo.acc_brkgdtl ON dbo.acc_brokerage.brok_no = dbo.acc_brkgdtl.brok_no                                
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                
 (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(acc_brokerage.brok_no,3,3)  = @CityCode                                
--/////////////////////////////////////              
                                
                                
/* STEP 8: PURCHASE INVOICE - MAIN TABLE */                                
                               
INSERT INTO #TRANSLOG                                
Select                                  
 '1PI' transtype,                                
 PUR_CODE 'transcode',                                
 PUR_SUPPLIER 'clientcode',                                 
 0 'DrAmt',                                
 TOTALAMT 'CrAmt'  ,  
   0 'ACrAmt'                                                     
From acc_purchase                                
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                
 (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(PUR_CODE,3,3)  = @CityCode                      
              
              
INSERT INTO #TRANSLOG              
SELECT     '1PI' AS transtype,                
dbo.acc_purchasedtls.pur_code as 'transcode',                
dbo.acc_purchasedtls.pur_account AS clientcode,               
 convert(numeric(18,2),dbo.acc_purchasedtls.pur_amount) - convert(numeric(18,2),dbo.acc_purchasedtls.pur_deduction)  AS DrAmt,               
0 AS CrAmt         ,  
   0 'ACrAmt'                            
FROM         dbo.acc_purchase INNER JOIN              
                      dbo.acc_purchasedtls ON dbo.acc_purchase.pur_code = dbo.acc_purchasedtls.pur_code              
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                
 (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(acc_purchase.PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(acc_purchase.PUR_CODE,3,3)  = @CityCode    
  
INSERT INTO #TRANSLOG              
SELECT     '1PI' AS transtype,                
dbo.acc_purchasedtls.pur_code as 'transcode',                
dbo.acc_purchase.PUR_SUPPLIER AS clientcode,               
convert(numeric(18,2),dbo.acc_purchasedtls.pur_deduction) AS DrAmt,               
convert(numeric(18,2),dbo.acc_purchasedtls.pur_deduction) AS CrAmt ,  
   0 'ACrAmt'                                    
FROM         dbo.acc_purchase INNER JOIN              
                      dbo.acc_purchasedtls ON dbo.acc_purchase.pur_code = dbo.acc_purchasedtls.pur_code              
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                
 (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                                 
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'')                                 
 --and substring(acc_purchase.PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                                
 --and substring(acc_purchase.PUR_CODE,3,3)  = @CityCode                
   
     
    
 /********************************************/    
 if object_id('tempdb..#TRANSLOG1') is not null    
 drop table #TRANSLOG1    
     
 CREATE TABLE #TRANSLOG1    
 (    
  CmpCode nvarchar(50),     
  clientcode nvarchar(15),    
  OpDr  decimal(18,2),    
  OpCr  decimal(18,2),    
  DrAmt decimal(18,2),    
  CrAmt decimal(18,2),    
  ClDr decimal(18,2),    
  ClCr decimal(18,2),    
  ACrAmt decimal(18,2)    
 )      
     
 INSERT INTO #TRANSLOG1    
 Select  SUBSTRING (transcode, 1,5),    
  clientcode,     
  0.00,     
  0.00,    
  sum(DrAmt) DrAmt,     
  sum(CrAmt) CrAmt,    
  0.00,    
  0.00,    
  sum(ACrAmt) ACrAmt    
 From  #TRANSLOG     
 group by SUBSTRING (transcode, 1,5), clientcode    
     
  
 --****************************  CREATE TEMP TABLE '#det ' to store the data as per Cmp & cty    
     
  IF OBJECT_ID ('tempdb..##det') is not null    
   drop table ##det    
  declare @int int     
  declare @intchk int    
  declare @Error int    
  declare @TempString nvarchar(4000)    
  declare @Temp nvarchar(4000)    
  declare @Count int    
  declare @InnerTemp nvarchar(500)    
  declare @InnerCount int    
  declare @cmpcitycode nvarchar(10)    
  DECLARE @str varchar(4000)    
  declare @cmpcount int    
  Set @cmpcount = 0    
     
  set @str = ''    
    
  BEGIN TRANSACTION     
    
   SET @TempString = @CompanyCityCode    
   SET @count = CHARINDEX(',', @TempString)     
    
   Declare @cmdStr nvarchar(4000)    
   SET @cmdStr = ''    
    
   Declare @colString nvarchar(4000)    
   SET @colString = ''    
    
   Declare @colString1 nvarchar(4000)    
   SET @colString1 = ''    
    
   Declare @columnString nvarchar(4000)    
   SET @columnString = ''    
    
   Declare @columnString1 nvarchar(4000)    
   SET @columnString1 = ''    
    
   WHILE @count > 0       
   BEGIN     
     begin    
      SET @Temp = @TempString    
     end    
   
     SET @InnerCount = CHARINDEX(',', @temp)    
     SET @InnerTemp = SUBSTRING(@temp, 1, (@InnerCount - 1))     
     SET @cmpcitycode = @InnerTemp     
      
     SET @cmpcount = @cmpcount + 1    
      
     IF OBJECT_ID ('tempdb..##det') is not null    
     Begin    
      SET @cmdStr = 'Alter TABLE ##det Add [' + @cmpcitycode + 'OPDr]'  + ' DECIMAL(15,2), [' + @cmpcitycode  +  'OPCr]' + ' DECIMAL(15,2), [' + @cmpcitycode  +  'TDR]' + ' DECIMAL(15,2), ['  +  @cmpcitycode + 'TCR]' + ' DECIMAL(15,2), [' + @cmpcitycode 
 +  
        'ClDR]' + ' DECIMAL(15,2), [' + @cmpcitycode  +  'ClCR]' + ' DECIMAL(15,2)' --, [' + @cmpcitycode + 'AdCr]' + ' DECIMAL(15,2)         
      SET @colString = @colString + '##det.[' + @cmpcitycode + 'ClDR], ##det.[' + @cmpcitycode + 'ClCR],'-- ##det.['  + @cmpcitycode +  'AdCr],    
      SET @colString1 = @colString1 + '##det.[' + @cmpcitycode + 'OPDr], ##det.[' + @cmpcitycode + 'OPCr], ##det.[' + @cmpcitycode + 'TDR], ##det.['  + @cmpcitycode + 'TCR], ##det.['  + @cmpcitycode + 'ClDR], ##det.[' + @cmpcitycode + 'ClCR],'-- ##det.[' + @cmpcitycode +  'AdCr],             
      
      SET @colStringY = @colStringY + ',sum(##det.[' + @cmpcitycode + 'ClDR]) as [' + @cmpcitycode + 'ClDR], sum(##det.[' + @cmpcitycode + 'ClCR]) as [' + @cmpcitycode + 'ClCR]'-- ##det.['  + @cmpcitycode +  'AdCr],    
      SET @colStringX = @colStringX + ',sum(##det.[' + @cmpcitycode + 'OPDr]) as [' + @cmpcitycode + 'OPDr], sum(##det.[' + @cmpcitycode + 'OPCr]) as [' + @cmpcitycode + 'OPCr], sum(##det.[' + @cmpcitycode + 'TDR]) as [' + @cmpcitycode + 'TDR], sum(##det.['  + @cmpcitycode + 'TCR]) as ['  + @cmpcitycode + 'TCR], sum(##det.['  + @cmpcitycode + 'ClDR]) as ['  + @cmpcitycode + 'ClDR], sum(##det.[' + @cmpcitycode + 'ClCR]) as [' + @cmpcitycode + 'ClCR]'-- ##det.[' + @cmpcitycode +  'AdCr],             

      SET @columnString = @columnString + 'sum(isnull([' + @cmpcitycode + 'ClDR], 0)), sum(isnull([' + @cmpcitycode + 'ClCR], 0)), '    --sum(isnull(['  + @cmpcitycode +  'AdCr], 0)),
      SET @columnString1 = @columnString1 + 'sum(isnull([' + @cmpcitycode + 'OPDr], 0)), sum(isnull([' + @cmpcitycode + 'OPCr], 0)), sum(isnull([' + @cmpcitycode + 'TDR], 0)), sum(isnull(['  + @cmpcitycode + 'TCR], 0)), sum(isnull(['  + @cmpcitycode + 'ClDR], 0)), sum(isnull([' + @cmpcitycode + 'ClCR], 0)), '--sum(isnull(['  + @cmpcitycode +  'AdCr], 0)),             
     End    
     else    
     Begin    
       SET @cmdStr = 'Create TABLE ##det (Particulars varchar(100), [' + @cmpcitycode + 'OPDr]'  + ' DECIMAL(15,2), [' + @cmpcitycode  +  'OPCr]' + ' DECIMAL(15,2), [' + @cmpcitycode  +  'TDR]' + ' DECIMAL(15,2), ['  +  @cmpcitycode + 'TCR]' + ' DECIMAL(15,2), [' + @cmpcitycode  +  'ClDR]' + ' DECIMAL(15,2), [' + @cmpcitycode  +  'ClCR]' + ' DECIMAL(15,2) )'--, [' + @cmpcitycode + 'AdCr]' + ' DECIMAL(15,2)     
       SET @colString =   '##det.[' + @cmpcitycode + 'ClDR], ##det.[' + @cmpcitycode + 'ClCR], '--##det.['  + @cmpcitycode +  'AdCr],    
       SET @colString1 = '##det.[' + @cmpcitycode + 'OPDr], ##det.[' + @cmpcitycode + 'OPCr], ##det.[' + @cmpcitycode + 'TDR], ##det.['  + @cmpcitycode + 'TCR], ##det.['  + @cmpcitycode + 'ClDR], ##det.[' + @cmpcitycode + 'ClCR], ' --##det.['  + @cmpcitycode + 'AdCr],            
	
       SET @colStringY = 'sum(##det.[' + @cmpcitycode + 'ClDR]) as [' + @cmpcitycode + 'ClDR], sum(##det.[' + @cmpcitycode + 'ClCR]) as [' + @cmpcitycode + 'ClCR]'--##det.['  + @cmpcitycode +  'AdCr],    
       SET @colStringX = 'sum(##det.[' + @cmpcitycode + 'OPDr]) as [' + @cmpcitycode + 'OPDr], sum(##det.[' + @cmpcitycode + 'OPCr]) as [' + @cmpcitycode + 'OPCr], sum(##det.[' + @cmpcitycode + 'TDR]) as [' + @cmpcitycode + 'TDR], sum(##det.['  + @cmpcitycode + 'TCR]) as ['  + @cmpcitycode + 'TCR], sum(##det.['  + @cmpcitycode + 'ClDR]) as ['  + @cmpcitycode + 'ClDR], sum(##det.[' + @cmpcitycode + 'ClCR]) as [' + @cmpcitycode + 'ClCR] ' --##det.['  + @cmpcitycode + 'AdCr],            
       
       SET @columnString = 'sum(isnull([' + @cmpcitycode + 'ClDR], 0)), sum(isnull([' + @cmpcitycode + 'ClCR], 0)), '--sum(isnull(['  + @cmpcitycode +  'AdCr], 0)),    
       SET @columnString1 = 'sum(isnull([' + @cmpcitycode + 'OPDr], 0)), sum(isnull([' + @cmpcitycode + 'OPCr], 0)),sum(isnull([' + @cmpcitycode + 'TDR], 0)), sum(isnull(['  + @cmpcitycode + 'TCR], 0)), sum(isnull(['  + @cmpcitycode + 'ClDR], 0)), sum(isnull([' + @cmpcitycode + 'ClCR], 0)), '--sum(isnull(['  + @cmpcitycode +  'AdCr], 0)),     
     End    
         
        
     exec(@cmdStr)    
          
        --, ['  + @cmpcitycode + 'AdCr]' + '--------,           ACrAmt    
     Set @str = 'INSERT INTO ##det (Particulars, [' + @cmpcitycode + 'OPDr], [' +  @cmpcitycode + 'OPCr], ['  +  @cmpcitycode + 'TDR], [' + @cmpcitycode +  'TCR], ['  +  @cmpcitycode + 'ClDR], ['  +  @cmpcitycode + 'ClCR])  
         SELECT CLIENTCODE,           
         OpDr = case when (' + @optbl + '.[' + @cmpcitycode + 'OP]) > 0 then abs(' + @optbl + '.[' + @cmpcitycode + 'OP]) end ,    
         OpCr = case when (' + @optbl + '.[' + @cmpcitycode + 'OP]) < 0 then abs(' + @optbl + '.[' + @cmpcitycode + 'OP]) end ,    
         DrAmt,    
         CrAmt,     
         ClDr = case when ((( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) > 0) then (abs (( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) ) end,    
         ClCr = case when ((( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) < 0) then (abs (( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) ) end  
       FROM #TRANSLOG1 Left Outer Join ' + @optbl + '     
        ON ' + @optbl + '.Code = #TRANSLOG1.CLIENTCODE     
       WHERE  CmpCode = ' + @cmpcitycode + ' and CLIENTCODE not in ( Select Particulars from ##det ) ' + char(13)    
         
     Set @str = @str  + 'Update ##det     
       Set     [' + @cmpcitycode + 'OPDr] =  case when (' + @optbl + '.[' + @cmpcitycode + 'OP]) > 0 then abs(' + @optbl + '.[' + @cmpcitycode + 'OP]) end ,    
        [' + @cmpcitycode + 'OPCr] =  case when (' + @optbl + '.[' + @cmpcitycode + 'OP]) < 0 then abs(' + @optbl + '.[' + @cmpcitycode + 'OP]) end ,    
        [' + @cmpcitycode + 'TDR] = DrAmt,    
        [' + @cmpcitycode + 'TCR] = CrAmt,     
        [' + @cmpcitycode + 'ClDR] = case when ((( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) > 0) then (abs (( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) ) end,    
        [' + @cmpcitycode + 'ClCR] = case when ((( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) < 0) then (abs (( isnull(' + @optbl + '.[' + @cmpcitycode + 'OP], 0) + DrAmt) - CrAmt) ) end  
       FROM #TRANSLOG1  Left Outer Join ' + @optbl + '     
        ON ' + @optbl + '.Code = #TRANSLOG1.CLIENTCODE     
       WHERE  CmpCode = ' + @cmpcitycode + ' and #TRANSLOG1.CLIENTCODE = ##det.Particulars'    
     --,          [' + @cmpcitycode + 'AdCr] = ACrAmt    
     exec(@str)     
    
     SET @TempString = SUBSTRING(@TempString, (@count + 1), (LEN(@TempString) - @count))    
     SET @count = CHARINDEX(',', @TempString)     
     
   END     
  
  COMMIT TRANSACTION      
      
  if object_id('table3') is not null    
   drop table table3    
    
  Declare @str3 nvarchar(4000)    
  SET @str3 =''      
       
   
  SET @colString = substring(@colString, 1, len(@colString)-1)    
  SET @colString1 = substring(@colString1, 1, len(@colString1)-1)    
