 if object_id('tempdb..##TempAllCity') is not null    
   drop table ##TempAllCity    
 declare @StrSql123 nvarchar(4000)    
 set @StrSql123 = ''    
 If(@cmpcount > 1)    
 Begin    
      	declare @ColName varchar(50), @cnt int, @colStr  varchar(8000), @StrSql  varchar(8000)    
  	declare @colStr1  varchar(8000)    
  	declare @colStr2  varchar(8000)    
  	declare @colStrAdCr  varchar(8000)    
  	declare @colStrOP   varchar(8000)    
  	declare @colStrTDr  varchar(8000)    
  	declare @colStrTCr  varchar(8000)    
  	declare @colStrCl    varchar(8000)    
  	declare @condition  varchar(8000)    
  	declare @condition1 varchar(8000)    
  	declare @Coloumn  varchar(8000)     
  	set @cnt = 2    
  	set @colStr = ''    
  	set @colStr1 = ''    
  	set @colStrAdCr = ''    
  	set @colStrOP = ''    
  	set @colStrTDr = ''    
  	set @colStrTCr = ''    
  	set @colStrCl = ''    
  	set @condition = ''    
  	set @Coloumn = ''    
  If(@ShowOpBal = '1')    
  Begin    
   SELECT @ColName = COL_NAME(OBJECT_ID('table3'), 1)    
   While @ColName is not null    
   begin     
    if(right(@ColName, 4) = 'OPDr')    
    Begin    
     SET @colStrOP = @colStrOP + 'IsNull(['+ @ColName + '], 0) - '    
    End    
    if(right(@ColName, 4) = 'OPCr')    
    Begin    
     SET @colStrOP = @colStrOP + 'IsNull(['+ @ColName + '], 0) + '    
    End     
    if(right(@ColName, 3) = 'TDR')    
    Begin    
     SET @colStrTDr = @colStrTDr + 'IsNull(['+ @ColName + '], 0) + '    
    End    
    if(right(@ColName, 3) = 'TCR')    
    Begin    
     SET @colStrTCr = @colStrTCr + 'IsNull(['+ @ColName + '], 0) + '    
    End      
    if(right(@ColName, 4) = 'ClDR')    
    Begin    
     SET @colStrCl = @colStrCl + 'IsNull(['+ @ColName + '], 0) - '    
    End    
    if(right(@ColName, 4) = 'ClCR')    
    Begin    
     SET @colStrCl = @colStrCl + 'IsNull(['+ @ColName + '], 0) + '    
    End    
      
    SELECT @ColName = COL_NAME(OBJECT_ID('table3'), @cnt)     
       set @cnt = @cnt + 1    
        
    end    
   
   Set @colStrTDr = SUBSTRING(@colStrTDr, 1, LEN(@colStrTDr) - 1)    
   Set @colStrTCr = SUBSTRING(@colStrTCr, 1, LEN(@colStrTCr) - 1)    
   Set @colStrOP = SUBSTRING(@colStrOP, 1, LEN(@colStrOP) - 1)    
   Set @colStrCl = SUBSTRING(@colStrCl, 1, LEN(@colStrCl) - 1)    
       
   set @condition = @colStrTDr + ' <> 0 OR ' + @colStrTCr + ' <> 0  OR ' + @colStrOP + ' <> 0 OR ' + @colStrCl --OR ' + @colStrAdCr + ' <> 0   
   set @condition = replace(@condition, '+', '<> 0 OR')    
   set @condition = replace(@condition, '-', '<> 0 OR')    
   set @condition = @condition + ' <> 0'    
       
   Set @StrSql = 'Select *, case when (' + @colStrOP + ') > 0 then abs(' + @colStrOP + ') end  as TotalOPDr, case when (' + @colStrOP + ') < 0 then abs(' + @colStrOP + ') end  as TotalOPCr, ' + @colStrTDr + ' as TotalTDR, ' + @colStrTCr + ' as TotalTCR,  
  
    case when (' + @colStrCl + ') > 0 then abs(' + @colStrCl + ') end  as TotalClDr, case when (' + @colStrCl + ') < 0 then abs(' + @colStrCl + ') end  as TotalClCr  into ##TempAllCity from table3 where ' + @condition    
    print @StrSql 
    exec(@StrSql) 
    print @StrSql   
    select * from ##TempAllCity --order by exp_name      
    set @StrSql123 = 'Select '''',  ' + @columnString1 + ' sum(isnull(TotalOPDr, 0)) as TotalOPDr, sum(isnull(TotalOPCr, 0)) , sum(isnull(TotalTDR, 0)) as TotalTDR, sum(isnull(TotalTCR, 0)) as TotalTCR,  sum(isnull(TotalClDr, 0)) as TotalClDr, sum(isnull(TotalClCr, 0)) as TotalClCr   from ##TempAllCity  ' --, sum(isnull(TotalAdCr, 0)) as TotalAdCr   
    exec(@StrSql123)   
   End    
  else    
  Begin    
   SELECT @ColName = COL_NAME(OBJECT_ID('table3'), 1)    
     
   While @ColName is not null    
   begin     
    if(right(@ColName, 4) = 'ClDR')     
    Begin    
     SET @colStr = @colStr + 'IsNull(['+ @ColName + '], 0) + '    
     SET @condition = @condition + ' [' + @ColName +  '] is not null or'     
    End    
    if(right(@ColName, 4) = 'ClCR')    
    Begin    
     SET @colStr1 = @colStr1 + 'IsNull(['+ @ColName + '], 0) + '    
     SET @condition = @condition + ' [' + @ColName +  '] is not null or'     
    End    
    SELECT @ColName = COL_NAME(OBJECT_ID('table3'), @cnt)     
    set @cnt = @cnt + 1        
   end       
    
   Set @colStr = SUBSTRING(@colStr, 1, LEN(@colStr) - 1)    
   Set @colStr1 = SUBSTRING(@colStr1, 1, LEN(@colStr1) - 1)    
   Set @condition1 = REPLACE(@condition, 'is not null','<> 0')    
   Set @condition1 = SUBSTRING(rtrim(@condition1), 1, LEN(@condition1) - 3)    
    
   set @condition = @condition + ' ' + @condition1    
    
   Set @StrSql = 'Select *, ' + @colStr + ' as TotalClDR, ' + @colStr1 + ' as TotalClCR into ##TempAllCity  from  table3 where ' + @condition --, ' + @colStrAdCr + ' as TotalAdCr   
   exec(@StrSql)    
   select * from ##TempAllCity       
   set @StrSql123 = 'Select '''',  ' + @columnString + ' sum(isnull(TotalClDR, 0)) as TotalClDR, sum(isnull(TotalClCR, 0))  from ##TempAllCity  '  --, sum(isnull(TotalAdCr, 0)) as TotalAdCr  
   
   exec(@StrSql123)    
   
  End     
   
      
 End    
 else    
 Begin    
  set @condition = ''    
  set @cnt = 2       
  set @Coloumn = ''    
  SELECT @ColName = COL_NAME(OBJECT_ID('table3'), 1)    
      
  While @ColName is not null    
  begin      
   if(right(@ColName, 4) = 'ClDR') or (right(@ColName, 4) = 'ClCR') --or (right(@ColName, 4) = 'AdCr')    
   Begin    
    SET @condition = @condition + ' [' + @ColName +  '] is not null or'      
   End     
        
   SELECT @ColName = COL_NAME(OBJECT_ID('table3'), @cnt)    
   set @Coloumn = @Coloumn + ' sum(convert(decimal(15,2), isnull( ['+ @ColName + '] , 0))) as [' + @ColName + '] , '     
   set @cnt = @cnt + 1        
  end       
      
  set @Coloumn = substring(@Coloumn, 1, len(@Coloumn)-1)    
  print @Coloumn    
  --print @colStrAdCr      
  Set @condition1 = REPLACE(@condition, 'is not null','<> 0')    
  Set @condition1 = SUBSTRING(rtrim(@condition1), 1, LEN(@condition1) - 3)    
    
  set @condition = @condition + ' ' + @condition1    
  
  set @StrSql = 'Select * from table3 where ' + @condition    
  exec(@StrSql)    
    
  
  If(@ShowOpBal = '1')    
  Begin    
   set @columnString1 = substring(@columnString1, 1, len(@columnString1)-1)    
   set @StrSql123 = 'Select '''',  ' + @columnString1 + ' from table3  '    
  End    
  Else    
  Begin    
   set @columnString = substring(@columnString, 1, len(@columnString)-1)    
   set @StrSql123 = 'Select '''',  ' + @columnString + ' from table3  '    
  End      
  EXEC(@StrSql123)    
      
      
 End    
  
drop table table3    
drop table #group




