  acc_creditnote.crt_no 'Transcode',                    
  acc_crtcharge.crt_account 'clientcode',
  convert(float,isnull(acc_crtcharge.crt_inramt,0)) 'DrAmt',                     
   0 'CrAmt'                    
  
 FROM  acc_crtcharge                     
  LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge.crt_no                    
  
 WHERE  --acc_crtcharge.crt_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')                     
  and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
  AND acc_crtcharge.crt_inramt <> '0'  

