/* STEP 6: STORAGE INVOICE */                                      
INSERT INTO #TRANSLOG                                      
Select                                        
 '6SI' transtype,                                      
 billno 'transcode',                                      
 client 'clientcode',                                       
 (select ISNULL(sum(convert(float,ISNULL(amount,0))) ,0)                                      
 from  ACC_STOREDTLS                                       
 where  ACC_STOREDTLS.BILLNO = ACC_STORAGE.billno) 'DrAmt',                                      
 0 'CrAmt'                                      
From ACC_STORAGE                                  
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                                      
 (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                                       
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'')     
and dbo.ConvertDate_IN_US(billdt,'/') <=@User_EndDt                                        
 and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                                      
 and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                                      
                     
INSERT INTO #TRANSLOG                                        
SELECT     '6SI' AS transtype, dbo.acc_storedtls.billno AS transcode, dbo.acc_storedtls.account AS clientcode, 0 AS DrAmt,                     
                      dbo.acc_storedtls.amount AS CrAmt                    
FROM         dbo.acc_storage INNER JOIN                    
                      dbo.acc_storedtls ON dbo.acc_storage.billno = dbo.acc_storedtls.billno                    
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                  
 (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                                       
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'')     
and dbo.ConvertDate_IN_US(billdt,'/') <=@User_EndDt                                         
 and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                                      
 and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                                  
                     
                    
                    
