/*                                
 STEP : X   TABLE #TRANSLOG1  -  CALCULATE OPENING BALANCE, SUM OF TOTAL DEBIT, SUM OF TOTAL CREDIT,                                 
     AND CLOSING BALANCE                                
*/                                
CREATE TABLE #TRANSLOG1(                                
 clientcode nvarchar(15),                                
 DrAmt decimal(15,2),                                
 CrAmt decimal(15,2)                                
)               
INSERT INTO #TRANSLOG1                                
Select  clientcode,                                 
 isnull(sum(isnull(DrAmt,0)),0) DrAmt,                                 
 isnull(sum(isnull(CrAmt,0)),0) CrAmt                                 
From  #TRANSLOG                                 
group by clientcode                                
                                
                                
CREATE TABLE #TRANSLOG_ALL(                                
 CLIENTCODE nvarchar(15),                            
 cldr decimal(15,2),                                 
 clcr decimal(15,2),                                
 exp_sname NVARCHAR(500),                                
 sup_sname NVARCHAR(500),                                
 acctname NVARCHAR(500),                                
 ACCNAME NVARCHAR(500)                              
)                                
DECLARE @strText nvarchar(4000)                                
DECLARE @OPBALText nvarchar(4000)                                
SET @OPBALText = '                                
(isnull((                                
     select  [' + @CompanyCode + @CityCode  + 'OP]                                
     from '+ @OpBalTable +'                                
     where  ' + @OpBalTable + '.code =  #TRANSLOG1.CLIENTCODE),0)'        
set @strText =  '                                
INSERT INTO #TRANSLOG_ALL                              
SELECT  CLIENTCODE,                            
     cldr =  DrAmt ,                                
    clcr =  CrAmt,                                
    exp_master.exp_name + ' + char(39) + '<B>  </b>' + char(39) +  'exp_sname ,                                  
    supplier_master.sup_name + ' + char(39) + '<B> </b>' + char(39) + ' sup_sname,                                 
    genacct_master.acctname + ' + char(39) + '<B> </b>' + char(39) + ' acctname,                            
    exp_master.exp_name +  supplier_master.sup_name +   genacct_master.acctname AS ACCNAME                            
 FROM #TRANSLOG1                                
   LEFT OUTER JOIN dbo.exp_master ON #TRANSLOG1.clientCODE = dbo.exp_master.exp_code                                 
   LEFT OUTER JOIN dbo.supplier_master ON #TRANSLOG1.clientCODE = dbo.supplier_master.sup_code                                 
   LEFT OUTER JOIN dbo.genacct_master ON #TRANSLOG1.clientCODE = dbo.genacct_master.acctcode                                
                               
  order by genacct_master.acctname, supplier_master.sup_name, exp_master.exp_name                                 
                                
INSERT INTO #TRANSLOG_ALL                              
                                
  SELECT  ' + @OpBalTable + '.code ' + char(39) + 'CLIENTCODE' + char(39) + ',                              
    cldr = 0 ,                                
    clcr = 0 ,                                
    exp_master.exp_name  + ' + char(39) + '<B></b>' + char(39) + ' exp_sname,                                 
    supplier_master.sup_name + ' + char(39) + '<B></b>' + char(39) + ' sup_sname,                                 
    genacct_master.acctname + ' + char(39) + '<B></b>' + char(39) + ' acctname,                                
    exp_master.exp_name +  supplier_master.sup_name +   genacct_master.acctname AS ACCNAME                          
  from   ' + @OpBalTable + '                                 
     LEFT OUTER JOIN dbo.exp_master ON ' + @OpBalTable + '.code = dbo.exp_master.exp_code                                 
     LEFT OUTER JOIN dbo.supplier_master ON ' + @OpBalTable + '.code = dbo.supplier_master.sup_code                                 
     LEFT OUTER JOIN dbo.genacct_master ON ' + @OpBalTable + '.code = dbo.genacct_master.acctcode                                
     where  ' + @OpBalTable + '.code not in (select code from ' + @OpBalTable + ' where ' + @OpBalTable + '.code in (SELECT CLIENTCODE FROM #TRANSLOG1 )) and                                
(   ' + @OpBalTable + '.[' + @CompanyCode + @CityCode  + 'OP] is not null)'                                
                        
                             
                        
print @strText                                
exec(@strText)                            
create table   #tempOpbal (Client varchar(20) ,opbal varchar(25))                             
declare @temp varchar(1000)                            
set @temp ='insert into #tempOpbal (Client ,opbal )select  Code, [' + @CompanyCode + @CityCode  + 'OP]                               
     from  ' + @OpBalTable + '  '                            
exec (@temp)                          
                           
create table #tblReport (CLIENTCODE varchar(25),opDr varchar(25) ,OPCr varchar(25),cldr varchar(25),clcr varchar(25),exp_sname varchar(250),sup_sname varchar(250),acctname varchar(250),CloDr varchar(25),Clocr varchar(25),            
ACCNAME varchar(25), UNDERGRP varchar(30))                              
insert into #tblReport                            
( CLIENTCODE ,opDr  ,OPCr,cldr ,clcr ,exp_sname ,sup_sname ,acctname ,CloDr ,Clocr ,ACCNAME, UNDERGRP )                              
  SELECT  #TRANSLOG_ALL.CLIENTCODE ,                             
case   when  convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) > 0 then convert(numeric(18,2),isnull(#tempOpbal.opbal,0))  end as opDr,                              
case   when  convert(numeric(18,2),isnull(#tempOpbal.opbal,0))< 0 then convert(numeric(18,2),isnull(#tempOpbal.opbal,0))  end as OPCr ,                             
 #TRANSLOG_ALL.cldr , #TRANSLOG_ALL.clcr , #TRANSLOG_ALL.exp_sname ,#TRANSLOG_ALL.sup_sname , #TRANSLOG_ALL.acctname ,                             
case when convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0)) > 0                             
then convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0))  end as CloDr,       
case   when  convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0))< 0                             
then replace(convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0)),'-','')   end as Clocr ,#TRANSLOG_ALL.ACCNAME,                          
CASE  WHEN CLIENTCODE LIKE 'E%' THEN 'SUNDRY DEBTOR'                                 
    WHEN CLIENTCODE LIKE 'S%'  THEN  'SUNDRY CREDITOR'                                  
    WHEN CLIENTCODE LIKE 'G%'  THEN 'GENERAL ACCOUNT'  END as UNDERGRP                          
FROM #TRANSLOG_ALL                            
  LEFT OUTER JOIN #tempOpbal on  #TRANSLOG_ALL.CLIENTCODE = dbo.#tempOpbal.Client                            
        
select  CLIENTCODE ,opDr  ,replace(OPCr,'-','') as OPCr,cldr ,replace(clcr,'-','') as clcr,exp_sname,sup_sname ,acctname , acctname as  AccountName ,CloDr ,replace(Clocr,'-','')as Clocr  ,ACCNAME,UNDERGRP from #tblReport   where opDr  is not null or OPCr
  
    
 is not null or cldr is not      
        
null or clCr is not null                         
        
select  '' as CLIENTCODE , sum(convert(numeric(18,2),opDr)) as opDr ,replace(sum(convert(numeric(18,2),OPCr)),'-','') as OPCr,sum(convert(numeric(18,2),cldr)) as cldr,                            
replace(sum(convert(numeric(18,2),clcr)),'-','') as clcr,'' as exp_sname,'' as sup_sname ,' Total  ' as acctname ,sum(convert(numeric(18,2),CloDr)) as CloDr,replace(sum(convert(numeric(18,2),Clocr)),'-','')as Clocr ,'' as ACCNAME,            
'Amount : ' as UNDERGRP from #tblReport                            
