--usp_Acct_Rpt_Trialbalance_byGrp '1-Apr-2006', '31-Mar-2007', '01', '101','1','0'        
--exec usp_Acct_Rpt_Trialbalance_byGrp '1-Apr-2006', '31-Mar-2007', '01', '101','1','M000030'                      

ALTER PROCEDURE [dbo].[usp_Acct_Rpt_Trialbalance_byGrp] --'1-Apr-2006', '31-Mar-2007', '01', '101'             
--declare                    
 @Fin_StartDate datetime,                          
 @Fin_EndDate datetime,                          
 @CompanyCode nvarchar(20),                          
 @CityCode nvarchar(20),                    
  --@year     varchar(10)=Null ,                      
 @group varchar(10),
 @UsrEndDT datetime                        
                      
as                      
 /*                   
set @Fin_StartDate='1-Apr-2007'                      
set @Fin_EndDate='31-Mar-2008'                      
set @CompanyCode='03'                       
set @CityCode='101'          
SET @year ='2'          
set @group='0'        
   */   
/*Declare @OpBalTable varchar(32)                    
if @year='1'                    
set @OpBalTable ='tbl_Master_010420063103007_AllGL'                    
else if @year='2'                    
set @OpBalTable ='tbl_Master_010420073103008_AllGL'                    
print @OpBalTable                    
     */
declare @st varchar(20),@dd varchar(20),@mm varchar(20),@yy varchar(20),@opbalst varchar(40)      
  set @st=@Fin_StartDate             
  set @dd=day(@st)      
  if len(@dd)< 2      
 set @dd='0'+@dd              
  set @mm=month(@st)       
  if len(@mm)< 2      
 set @mm='0'+@mm             
  set @yy=substring(convert(varchar,year(@st)),1,4)              
  set @opbalst=@dd+@mm+@yy       
       
  set @st=@Fin_EndDate             
  set @dd=day(@st)      
  if len(@dd)< 2      
 set @dd='0'+@dd              
  set @mm=month(@st)       
  if len(@mm)< 2      
 set @mm='0'+@mm             
  set @yy=substring(convert(varchar,year(@st)),2,3)              
  set @opbalst=@opbalst+@dd+@mm+@yy      
      
      
declare @OpBalTable varchar(100)      
set @OpBalTable='tbl_Master_'+ @opbalst +'_AllGL'      
--////////////////////////////////                    
                          
/* Creat table where Client id's will be there and his total debit and total credit */                          
CREATE TABLE #TRANSLOG(                          
 transtype nvarchar(3),                          
 transcode nvarchar(15),                          
 clientcode nvarchar(15),                          
 DrAmt decimal(18,2),                           
 CrAmt decimal(18,2)                          
)                            
/* STEP 1: STANDARD INVOICE Only CREDIT all Charges                          
  CLIENT A/C          DR   XXXX.XX                          
    CHARGES A/C                      XXXX.XXX                          
                          
*/        
if @Fin_EndDate >= getdate()  
 set @Fin_EndDate= getdate()                      
INSERT INTO #TRANSLOG                        
Select                          
 '1II' transtype,                        
 acc_invoice.inv_no 'transcode',                        
 acc_invoice.inv_client 'clientcode',                         
 (select  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0)                        
 from  acc_invcharge                         
 where  acc_invcharge.inv_no = acc_invoice.inv_no) +                         
 (select                         
  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0)                        
 from  acc_invcharge1                         
 where  acc_invcharge1.inv_no = acc_invoice.inv_no) 'DrAmt',                        
 0                        
  'CrAmt'                        
From acc_invoice                        
where                        
 (dbo.ConvertDate_IN_US(inv_date,'/') >= @Fin_StartDate) --'')                         
 and (dbo.ConvertDate_IN_US(inv_date,'/') <= @Fin_EndDate ) --'')                         
 and (dbo.ConvertDate_IN_US(inv_date,'/') <= @UsrEndDT)
 and substring(acc_invoice.inv_no,1,2)  = @CompanyCode --@CompanyCode                        
 and substring(acc_invoice.inv_no,3,3)  = @CityCode                        
  ----------------------------------  
INSERT INTO #TRANSLOG  
sELECT  '2II' as 'transtype',                    
  acc_invoice.inv_no 'Transcode',                    
 acc_invcharge.inv_account 'clientcode',                    
  0 'DrAmt',                     
  convert(float,acc_invcharge.inv_inramt) 'CrAmt'                    
                      
 FROM  acc_invcharge                     
  LEFT OUTER JOIN acc_invoice ON acc_invoice.inv_no =  acc_invcharge.inv_no                    
   WHERE  --acc_invcharge.inv_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @Fin_EndDate) --'31-Mar-2007')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDT)
  and substring(acc_invoice.inv_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_invoice.inv_no,3,3)  = @CityCode --'101'                    
  AND acc_invcharge.inv_inramt <> '0'   
  
INSERT INTO #TRANSLOG  
sELECT  '3II' as 'transtype',                    
  acc_invoice.inv_no 'Transcode',                    
 acc_invcharge1.inv_account 'clientcode',                    
  0 'DrAmt',                     
  convert(float,acc_invcharge1.inv_inramt) 'CrAmt'                    
                      
 FROM  acc_invcharge1                     
  LEFT OUTER JOIN acc_invoice ON acc_invoice.inv_no =  acc_invcharge1.inv_no                    
   WHERE  --acc_invcharge.inv_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @Fin_EndDate) --'31-Mar-2007')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDT)
  and substring(acc_invoice.inv_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_invoice.inv_no,3,3)  = @CityCode --'101'                    
  AND acc_invcharge1.inv_inramt <> '0'   
                     
--////////////////////////////////////////                     
                 
                          
/* STEP 2: CASH BOOK MAIN Table   */                           
INSERT INTO #TRANSLOG                          
select   '2' + acc_bank.status as 'transtype',                          
  acc_bank.EntryNo AS 'Transcode',                           
  ourbank 'Accode',                          
  dramt = CASE  acc_bank.status                           
    WHEN 'BR' THEN convert (float, actualamount)                          
    WHEN 'CR' THEN convert (float, actualamount)                            
    WHEN 'BP' THEN 0                          
    WHEN 'CP' THEN 0                          
    WHEN 'CE' THEN 0                          
   END,                           
  cramt = CASE  acc_bank.status                           
    WHEN 'BP' THEN convert (float, actualamount)                          
    WHEN 'CP' THEN convert (float, actualamount)                            
    WHEN 'BR' THEN 0                          
    WHEN 'CR' THEN 0                          
    WHEN 'CE' THEN convert (float, actualamount)                          
   END                          
 from acc_bank                           
 LEFT OUTER JOIN dbo.genacct_master ON acc_bank.ourbank = dbo.genacct_master.acctcode                          
 where  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate                          
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @UsrEndDT                        
  and substring(acc_bank.EntryNo,1,2)  = @CompanyCode                          
  and substring(acc_bank.EntryNo,3,3)  = @CityCode                          
                          
                          
/* STEP 3: CASH BOOK CHILD Table */                          
INSERT INTO #TRANSLOG                          
 select  '2' + acc_bank.status as 'transtype' ,                          
  acc_bankdtls.EntryNo 'transcode',                  
  client 'Accode',                          
  dramt = CASE  acc_bank.status                           
    WHEN 'BR' THEN convert (float, deduction)                          
    WHEN 'CR' THEN convert (float, deduction)                            
    WHEN 'BP' THEN convert (float, amount)                          
    WHEN 'CP' THEN convert (float, amount)                          
    WHEN 'CE' THEN convert (float, amount)                          
   END,                        
  cramt = CASE  acc_bank.status                           
    WHEN 'BP' THEN convert (float, deduction)                          
    WHEN 'CP' THEN convert (float, deduction)                            
    WHEN 'BR' THEN convert (float, amount)                          
    WHEN 'CR' THEN convert (float, amount)                          
    WHEN 'CP' THEN 0                            
   END                          
 from acc_bankdtls                           
   INNER JOIN acc_bank ON acc_bank.EntryNo =  acc_bankdtls.EntryNo                            
                            
 where                           
  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate --@Fin_StartDate                          
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  --@Fin_EndDate   
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @UsrEndDT                               
  and substring(acc_bank.EntryNo,1,2)  = @CompanyCode  --@CompanyCode                          
  and substring(acc_bank.EntryNo,3,3)  = @CityCode  --@CityCode                          
                          
/* STEP 4: JOURNAL VOUCHER Table */                          
INSERT INTO #TRANSLOG                          
 select  '3JV' as 'transtype',                           
  acc_JournalVoucDtls.jvcode 'transcode',                          
  jv_account 'Accode',                           
  convert (float, jv_Debit)'dramt',                           
  convert (float, jv_Credit) 'cramt'             
 from  acc_JournalVoucDtls                           
  INNER JOIN acc_JournalVouc ON acc_JournalVouc.jvcode = acc_JournalVoucDtls.jvcode                           
  LEFT OUTER JOIN dbo.exp_master ON acc_JournalVoucDtls.jv_account = dbo.exp_master.exp_code                           
  LEFT OUTER JOIN dbo.supplier_master ON acc_JournalVoucDtls.jv_account = dbo.supplier_master.sup_code                           
  LEFT OUTER JOIN dbo.genacct_master ON acc_JournalVoucDtls.jv_account = dbo.genacct_master.acctcode                          
 where  dbo.ConvertDate_IN_US(jv_Date,'/') >= @Fin_StartDate                          
  and dbo.ConvertDate_IN_US(jv_Date,'/') <= @Fin_EndDate 
  and dbo.ConvertDate_IN_US(jv_Date,'/') <= @UsrEndDT                         
  and substring(acc_JournalVoucDtls.jvcode,1,2)  = @CompanyCode                          
  and substring(acc_JournalVoucDtls.jvcode,3,3)  =  @CityCode                          
                          
                          
/* STEP 5: CREDIT NOTE Table */           
                          
INSERT INTO #TRANSLOG                        
Select                          
 '4CN' transtype,                        
 acc_creditnote.crt_no 'transcode',                        
 acc_creditnote.crt_client 'clientcode',                         
 0 'DrAmt',                        
  convert(float,isnull(totalamt,0))                      
  'CrAmt'                        
From acc_creditnote                        
where                        
 (dbo.ConvertDate_IN_US(crt_date,'/') >= @Fin_StartDate) --'')                     
 and (dbo.ConvertDate_IN_US(crt_date,'/') <= @Fin_EndDate ) --'')                         
 and substring(acc_creditnote.crt_no,1,2)  = @CompanyCode --@CompanyCode                        
 and substring(acc_creditnote.crt_no,3,3)  = @CityCode       

INSERT INTO #TRANSLOG            
 sELECT  '4CN' as 'transtype',                    
  acc_creditnote.crt_no 'Transcode',                    
  acc_crtcharge.crt_account 'clientcode',
  convert(float,isnull(acc_crtcharge.crt_inramt,0)) 'DrAmt',                     
   0 'CrAmt'                    
  
 FROM  acc_crtcharge                     
  LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge.crt_no                    
  
 WHERE  --acc_crtcharge.crt_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')                     
  and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
  AND acc_crtcharge.crt_inramt <> '0'  

INSERT INTO #TRANSLOG            
 sELECT  '4CN' as 'transtype',                    
  acc_creditnote.crt_no 'Transcode',                    
  acc_crtcharge1.crt_account 'clientcode',
  convert(float,isnull(acc_crtcharge1.crt_inramt,0)) 'DrAmt',                     
   0 'CrAmt'                    
  
 FROM  acc_crtcharge1                     
  LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge1.crt_no                    
  
 WHERE  --acc_crtcharge.crt_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @UsrEndDT)                     
  and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
  AND acc_crtcharge1.crt_inramt <> '0' 
                 
--////////////////////////////////////////                         
                          
/* STEP 6: STORAGE INVOICE */                          
INSERT INTO #TRANSLOG                          
Select                            
 '6SI' transtype,                          
 billno 'transcode',                          
 client 'clientcode',                           
 (select ISNULL(sum(convert(float,ISNULL(amount,0))) ,0)                          
 from  ACC_STOREDTLS                           
 where  ACC_STOREDTLS.BILLNO = ACC_STORAGE.billno) 'DrAmt',                          
 0 'CrAmt'                          
From ACC_STORAGE                      
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                          
 (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                           
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'') 
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @UsrEndDT )                          
 and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                          
 and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                          
         
INSERT INTO #TRANSLOG                            
SELECT     '6SI' AS transtype, dbo.acc_storedtls.billno AS transcode, dbo.acc_storedtls.account AS clientcode, 0 AS DrAmt,         
                      dbo.acc_storedtls.amount AS CrAmt        
FROM         dbo.acc_storage INNER JOIN        
                      dbo.acc_storedtls ON dbo.acc_storage.billno = dbo.acc_storedtls.billno        
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                          
 (dbo.ConvertDate_IN_US(billdt,'/') >= @Fin_StartDate) --'')                           
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @Fin_EndDate ) --'')
 and (dbo.ConvertDate_IN_US(billdt,'/') <= @UsrEndDT )                           
 and substring(ACC_STORAGE.BILLNO,1,2)  = @CompanyCode --@CompanyCode                          
 and substring(ACC_STORAGE.BILLNO,3,3)  = @CityCode                      
         
        
        
/* STEP 7: BROKERAGE INVOICE */                          
                          
INSERT INTO #TRANSLOG                          
Select                            
 '7BI' transtype,                          
 acc_brokerage.brok_no 'transcode',                          
 brok_expcode 'clientcode',                           
 (select ISNULL(sum(convert(float,ISNULL(brkamt,0))) ,0)                          
 from  acc_brkgdtl                           
 where  acc_brokerage.brok_no = acc_brkgdtl.brok_no) 'DrAmt',                          
 0 'CrAmt'                          
                          
From acc_brokerage                          
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                          
 (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                           
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'')   
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @UsrEndDT )                        
 and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode                          
 and substring(acc_brokerage.brok_no,3,3)  = @CityCode                          
-- /////////////////////////////////////        
INSERT INTO #TRANSLOG                          
                           
SELECT     '7BI' AS transtype, dbo.acc_brokerage.brok_no AS transcode, dbo.acc_brkgdtl.brkaccount AS clientcode, 0 AS DrAmt,         
                      dbo.acc_brkgdtl.brkamt AS CrAmt        
FROM         dbo.acc_brokerage INNER JOIN        
                      dbo.acc_brkgdtl ON dbo.acc_brokerage.brok_no = dbo.acc_brkgdtl.brok_no                          
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                          
 (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                           
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'') 
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @UsrEndDT )                          
 and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode                          
 and substring(acc_brokerage.brok_no,3,3)  = @CityCode                          
--/////////////////////////////////////        
                          
                          
/* STEP 8: PURCHASE INVOICE - MAIN TABLE */                          
                          
INSERT INTO #TRANSLOG                          
Select                            
 '1PI' transtype,                          
 PUR_CODE 'transcode',                          
 PUR_SUPPLIER 'clientcode',                           
 0 'DrAmt',                          
 TOTALAMT 'CrAmt'                          
From acc_purchase                          
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                          
 (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                           
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'') 
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @UsrEndDT )                          
 and substring(PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                          
 and substring(PUR_CODE,3,3)  = @CityCode                
        
        
INSERT INTO #TRANSLOG        
SELECT     '2PI' AS transtype,          
dbo.acc_purchasedtls.pur_code as 'transcode',          
dbo.acc_purchasedtls.pur_account AS clientcode,         
 convert(numeric(18,2),dbo.acc_purchasedtls.pur_amount)  AS DrAmt,         
convert(numeric(18,2),dbo.acc_purchasedtls.pur_deduction) AS CrAmt        
FROM         dbo.acc_purchase INNER JOIN        
                      dbo.acc_purchasedtls ON dbo.acc_purchase.pur_code = dbo.acc_purchasedtls.pur_code        
where --substring(crt_date,7,4) = '2006' and substring(crt_date,4,2) = '04'                          
 (dbo.ConvertDate_IN_US(PUR_DATE,'/') >= @Fin_StartDate) --'')                           
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @Fin_EndDate ) --'')
 and (dbo.ConvertDate_IN_US(PUR_DATE,'/') <= @UsrEndDT )                           
 and substring(acc_purchase.PUR_CODE,1,2)  = @CompanyCode --@CompanyCode                          
 and substring(acc_purchase.PUR_CODE,3,3)  = @CityCode            
        
                  
/*                          
 STEP : X   TABLE #TRANSLOG1  -  CALCULATE OPENING BALANCE, SUM OF TOTAL DEBIT, SUM OF TOTAL CREDIT,              
     AND CLOSING BALANCE                          
*/                          
CREATE TABLE #TRANSLOG1(                          
 clientcode nvarchar(15),                          
 DrAmt decimal(18,2),                          
 CrAmt decimal(18,2)                          
)                            
INSERT INTO #TRANSLOG1                          
Select  clientcode,                           
 isnull(sum(isnull(DrAmt,0)),0) DrAmt,                           
 isnull(sum(isnull(CrAmt,0)),0) CrAmt                           
From  #TRANSLOG                           
group by clientcode                          
          
          
              
            
CREATE TABLE #TRANSLOG_ALL(                          
 CLIENTCODE nvarchar(15),                      
 cldr decimal(18,2),                           
 clcr decimal(18,2),                          
 exp_sname NVARCHAR(500),                          
 sup_sname NVARCHAR(500),                          
 acctname NVARCHAR(500),                          
 ACCNAME NVARCHAR(500)                          
)                          
DECLARE @strText nvarchar(4000)                          
DECLARE @OPBALText nvarchar(4000)                          
SET @OPBALText = '                          
(isnull((                          
     select  [' + @CompanyCode + @CityCode  + 'OP]                          
     from '+ @OpBalTable +'                          
     where  ' + @OpBalTable + '.code =  #TRANSLOG1.CLIENTCODE),0)'                          
set @strText =  '                          
INSERT INTO #TRANSLOG_ALL                        
SELECT  CLIENTCODE,                      
      cldr = DrAmt,                    
    clcr =CrAmt,                          
    exp_master.exp_name  + ' + char(39) + '<B>  </b>' + char(39) +  'exp_sname ,                            
    supplier_master.sup_name + ' + char(39) + '<B> </b>' + char(39) + ' sup_sname,                           
    genacct_master.acctname + ' + char(39) + '<B> </b>' + char(39) + ' acctname,                      
    exp_master.exp_name +  supplier_master.sup_name +   genacct_master.acctname AS ACCNAME                      
   FROM #TRANSLOG1                          
   LEFT OUTER JOIN dbo.exp_master ON #TRANSLOG1.clientCODE = dbo.exp_master.exp_code                           
   LEFT OUTER JOIN dbo.supplier_master ON #TRANSLOG1.clientCODE = dbo.supplier_master.sup_code                           
   LEFT OUTER JOIN dbo.genacct_master ON #TRANSLOG1.clientCODE = dbo.genacct_master.acctcode                          
         
  order by genacct_master.acctname, supplier_master.sup_name, exp_master.exp_name                           
                          
INSERT INTO #TRANSLOG_ALL                        
      
  SELECT  ' + @OpBalTable + '.code ' + char(39) + 'CLIENTCODE' + char(39) + ',                        
    cldr = 0 ,                          
    clcr = 0 ,                          
    exp_master.exp_name  + ' + char(39) + '<B></b>' + char(39) + ' exp_sname,                           
    supplier_master.sup_name + ' + char(39) + '<B></b>' + char(39) + ' sup_sname,                           
    genacct_master.acctname + ' + char(39) + '<B></b>' + char(39) + ' acctname,                          
    exp_master.exp_name +  supplier_master.sup_name +   genacct_master.acctname AS ACCNAME                    
  from   ' + @OpBalTable + '                           
     LEFT OUTER JOIN dbo.exp_master ON ' + @OpBalTable + '.code = dbo.exp_master.exp_code                      
     LEFT OUTER JOIN dbo.supplier_master ON ' + @OpBalTable + '.code = dbo.supplier_master.sup_code                           
     LEFT OUTER JOIN dbo.genacct_master ON ' + @OpBalTable + '.code = dbo.genacct_master.acctcode                          
     where  ' + @OpBalTable + '.code not in (select code from ' + @OpBalTable + ' where ' + @OpBalTable + '.code in (SELECT CLIENTCODE FROM #TRANSLOG1 )) and                          
(   ' + @OpBalTable + '.[' + @CompanyCode + @CityCode  + 'OP] is not null)'                          
             
 --DrAmt <> 0 or  CrAmt <> 0                       
                  
print @strText                          
exec(@strText)                      
create table   #tempOpbal (Client varchar(20) ,opbal varchar(25),fk_code varchar(20))                        
declare @temp varchar(1000)                      
set @temp ='insert into #tempOpbal (Client ,opbal,fk_code )select  Code, [' + @CompanyCode + @CityCode  + 'OP],fk_code                         
     from  ' + @OpBalTable --+ ' where [' + @CompanyCode + @CityCode  + 'OP] is not null '                      
exec (@temp)                    
        
-----------------------------------------------------------------------------------        
create table #group (clientcode varchar(20),groupcode varchar(200))        
insert into #group (clientcode,groupcode)        
 select  acctcode,undergroup from genacct_master where undergroup<>'0'        
insert into #group (clientcode,groupcode)      
 select sup_code,'M000029' from supplier_master      
insert into #group (clientcode,groupcode)      
 select exp_code,'M000028' from exp_master        
-----------------------------------------------------------------------        
create table #tblReport (CLIENTCODE varchar(25),opDr varchar(25) ,OPCr varchar(25),cldr varchar(25),clcr varchar(25),exp_sname varchar(250),sup_sname varchar(250),acctname varchar(250),CloDr varchar(25),Clocr varchar(25),ACCNAME varchar(25), UNDERGRP varchar(30),fk_code varchar(20))                        
insert into #tblReport                      
( CLIENTCODE ,opDr  ,OPCr,cldr ,clcr ,exp_sname ,sup_sname ,acctname ,CloDr ,Clocr ,ACCNAME, UNDERGRP,fk_code )                        
  SELECT  #TRANSLOG_ALL.CLIENTCODE ,                       
case   when  convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) > 0 then convert(numeric(18,2),isnull(#tempOpbal.opbal,0))  end as opDr,                        
case   when  convert(numeric(18,2),isnull(#tempOpbal.opbal,0))< 0 then convert(numeric(18,2),isnull(#tempOpbal.opbal,0))  end as OPCr ,                       
 #TRANSLOG_ALL.cldr , #TRANSLOG_ALL.clcr , #TRANSLOG_ALL.exp_sname ,#TRANSLOG_ALL.sup_sname , #TRANSLOG_ALL.acctname ,                       
case when convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0)) > 0                       
then convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0))  end as CloDr,                        
case   when  convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0))< 0                       
then replace(convert(numeric(18,2),isnull(convert(numeric(18,2),isnull(#tempOpbal.opbal,0)) + convert(numeric(18,2),isnull(cldr,0)) - convert(numeric(18,2),isnull(clcr,0)),0)),'-','')   end as Clocr ,#TRANSLOG_ALL.ACCNAME,                    
CASE  WHEN #TRANSLOG_ALL.CLIENTCODE LIKE 'E%' THEN 'SUNDRY DEBTOR'                           
    WHEN #TRANSLOG_ALL.CLIENTCODE LIKE 'S%'  THEN  'SUNDRY CREDITOR'                            
    WHEN #TRANSLOG_ALL.CLIENTCODE LIKE 'G%'  THEN 'GENERAL ACCOUNT'  END as UNDERGRP , #group.groupcode                 
FROM #TRANSLOG_ALL                      
  LEFT OUTER JOIN #tempOpbal on  #TRANSLOG_ALL.CLIENTCODE = dbo.#tempOpbal.Client        
  LEFT OUTER JOIN #group on #TRANSLOG_ALL.CLIENTCODE=#group.clientcode        
        
-----------------------------------------------------------------------------------        
create table #final (opDr varchar(25) ,OPCr varchar(25),cldr varchar(25),clcr varchar(25),CloDr varchar(25),Clocr varchar(25),fk_code varchar(20),name varchar(200))         
declare @finalstr varchar(7000)        
set @finalstr='insert into #final (opDr  ,OPCr,cldr ,clcr ,CloDr ,Clocr ,fk_code,name )        
                       
(select  sum(convert(numeric(18,2),opDr))  ,sum(convert(numeric(18,2),abs(OPCr))) as OPCr,sum(convert(numeric(18,2),cldr)) ,sum(convert(numeric(18,2),abs(clcr))) as clcr,sum(convert(numeric(18,2),CloDr)) ,        
sum(convert(numeric(18,2),abs(Clocr)))as Clocr  ,#tblReport.fk_code,'+@OpBalTable+'.name        
from #tblReport left outer join '+@OpBalTable+' on #tblReport.fk_code='+@OpBalTable+'.code        
where opDr  is not null or OPCr is not null or cldr is not null or clCr is not null          
group by #tblReport.fk_code,name)'        
exec(@finalstr)        
-----------------------------------------------------------------------------------                    
create table #final1 (opDr varchar(25) ,OPCr varchar(25),cldr varchar(25),clcr varchar(25),CloDr varchar(25),Clocr varchar(25),fk_code varchar(20),name varchar(200))         
insert into #final1 (opDr  ,OPCr,cldr ,clcr ,CloDr ,Clocr ,fk_code,name )        
      
select opDr,        
       opCr,        
 cldr,clcr,        
       CloDr,        
       CloDr,        
 fk_code,name        
from #final        
------------------------------------------------------------------------------------        
if @group='0'        
begin        
 select opDr  ,OPCr,cldr ,clcr ,CloDr ,Clocr ,fk_code as CLIENTCODE ,case when name is null then 'NOT GROUPED' else name end as Accountname from #final1        
 select 'Total : 'as total, sum(convert(numeric(18,2),opDr))as opDr,sum(convert(numeric(18,2),OPCr))as OPCr,sum(convert(numeric(18,2),cldr))as cldr ,sum(convert(numeric(18,2),clcr)) as clcr ,sum(convert(numeric(18,2),CloDr))as CloDr ,sum(convert(numeric(18,2),Clocr))as Clocr      
  from #final1        
end        
else        
begin        
 select CLIENTCODE ,opDr  ,abs(OPCr) as OPCr,cldr ,clcr ,case when exp_sname is not null then  exp_sname when  sup_sname is not null           
 then sup_sname when acctname is not null then acctname end as Accountname ,CloDr ,Clocr ,ACCNAME, UNDERGRP,fk_code        
 from #tblReport where fk_code=@group and (opdr is not null or opCr is not null or cldr is not null or ClCr is not null  )        
 select 'Total : 'as total,sum(convert(numeric(18,2),opDr)) as opDr ,abs(sum(convert(numeric(18,2),OPCr))) as OPCr,sum(convert(numeric(18,2),cldr)) as cldr ,sum(convert(numeric(18,2),clcr)) as clcr ,sum(convert(numeric(18,2),CloDr)) as CloDr ,sum(convert
(numeric(18,2),Clocr      
))as Clocr         
 from #tblReport where fk_code=@group and (opdr is not null or opCr is not null or cldr is not null or ClCr is not null  )        
end        
------------------------------------------------------------------------------------        
                  
/*drop table #TRANSLOG                         
drop table #TRANSLOG1                      
drop table  #TRANSLOG_ALL                      
drop table  #tempOpbal                      
drop table  #tblReport        
drop table #final1        
drop table #final        
drop table #group
select * from #TRANSLOG1 where clientcode='G100197'
select * from #TRANSLOG_ALL where clientcode='G100197'

*/





GO


ALTER PROCEDURE [dbo].[usp_Acct_Rpt_Trialbalance_byGrpDtls_For_PLAc] --'1-Apr-2006', '31-Mar-2007', '01', '101'               
--declare                    
 @Fin_StartDate datetime,                              
 @Fin_EndDate datetime,                              
 @CompanyCode nvarchar(20),                              
 @CityCode nvarchar(20),
 @UsrEndDt datetime     
--	 @year varchar(1)              
        
AS /*  
set @Fin_StartDate='1-Apr-2009'                          
set @Fin_EndDate='31-Mar-2010'                          
set @CompanyCode='01'                           
set @CityCode='101'              
--SET @year ='1' 
set  @UsrEndDt =getdate()    
 
--  */           
 /*        
Declare @OpBalTable varchar(32)                        
if @year='1'                        
set @OpBalTable ='tbl_Master_010420063103007_AllGL'                        
else if @year='2'                        
set @OpBalTable ='tbl_Master_010420073103008_AllGL'                        
print @OpBalTable                        
   */
declare @st varchar(20),@dd varchar(20),@mm varchar(20),@yy varchar(20),@opbalst varchar(40)      
  set @st=@Fin_StartDate             
  set @dd=day(@st)      
  if len(@dd)< 2      
 set @dd='0'+@dd              
  set @mm=month(@st)       
  if len(@mm)< 2      
 set @mm='0'+@mm             
  set @yy=substring(convert(varchar,year(@st)),1,4)              
  set @opbalst=@dd+@mm+@yy       
       
  set @st=@Fin_EndDate             
  set @dd=day(@st)      
  if len(@dd)< 2      
 set @dd='0'+@dd              
  set @mm=month(@st)       
  if len(@mm)< 2      
 set @mm='0'+@mm             
  set @yy=substring(convert(varchar,year(@st)),2,3)              
  set @opbalst=@opbalst+@dd+@mm+@yy      
      
      
declare @OpBalTable varchar(100)      
set @OpBalTable='tbl_Master_'+ @opbalst +'_AllGL'      
--////////////////////////////////                                 
                              
/* Creat table where Client id's will be there and his total debit and total credit */ 
IF OBJECT_ID('TEMPDB..#TRANSLOG') IS NOT NULL    
DROP TABLE #TRANSLOG    
                             
CREATE TABLE #TRANSLOG(                              
 transtype nvarchar(3),                              
 transcode nvarchar(15),                              
 clientcode nvarchar(15),                              
 DrAmt decimal(18,2),                               
 CrAmt decimal(18,2)                              
)                                
/* STEP 1: STANDARD INVOICE Only CREDIT all Charges                              
  CLIENT A/C          DR   XXXX.XX                              
    CHARGES A/C                      XXXX.XXX                              
                              
*/                                
INSERT INTO #TRANSLOG                        
Select                          
 '1II' transtype,                        
 acc_invoice.inv_no 'transcode',                        
 acc_invoice.inv_client 'clientcode',                         
 (select  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0)                        
 from  acc_invcharge                         
 where  acc_invcharge.inv_no = acc_invoice.inv_no) +                         
 (select                         
  ISNULL(sum(convert(float,ISNULL(inv_inramt,0))),0)                        
 from  acc_invcharge1                         
 where  acc_invcharge1.inv_no = acc_invoice.inv_no) 'DrAmt',                        
 0                        
  'CrAmt'                        
From acc_invoice                        
where                        
 (dbo.ConvertDate_IN_US(inv_date,'/') >= @Fin_StartDate) --'')                         
 and (dbo.ConvertDate_IN_US(inv_date,'/') <= @Fin_EndDate ) --'')                         
 and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDt )
 and substring(acc_invoice.inv_no,1,2)  = @CompanyCode --@CompanyCode                        
 and substring(acc_invoice.inv_no,3,3)  = @CityCode                        
  ----------------------------------  
INSERT INTO #TRANSLOG  
sELECT  '2II' as 'transtype',                    
  acc_invoice.inv_no 'Transcode',                    
 acc_invcharge.inv_account 'clientcode',                    
  0 'DrAmt',                     
  convert(float,acc_invcharge.inv_inramt) 'CrAmt'                    
                      
 FROM  acc_invcharge                     
  LEFT OUTER JOIN acc_invoice ON acc_invoice.inv_no =  acc_invcharge.inv_no                    
   WHERE  --acc_invcharge.inv_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @Fin_EndDate) --'31-Mar-2007')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDt )
  and substring(acc_invoice.inv_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_invoice.inv_no,3,3)  = @CityCode --'101'                    
  AND acc_invcharge.inv_inramt <> '0'   
  
INSERT INTO #TRANSLOG  
sELECT  '3II' as 'transtype',                    
  acc_invoice.inv_no 'Transcode',                    
 acc_invcharge1.inv_account 'clientcode',                    
  0 'DrAmt',                     
  convert(float,acc_invcharge1.inv_inramt) 'CrAmt'                    
                      
 FROM  acc_invcharge1                     
  LEFT OUTER JOIN acc_invoice ON acc_invoice.inv_no =  acc_invcharge1.inv_no                    
   WHERE  --acc_invcharge.inv_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @Fin_EndDate) --'31-Mar-2007')                     
  and (dbo.ConvertDate_IN_US(acc_invoice.inv_date,'/') <= @UsrEndDt )
  and substring(acc_invoice.inv_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_invoice.inv_no,3,3)  = @CityCode --'101'                    
  AND acc_invcharge1.inv_inramt <> '0'   
                     
--////////////////////////////////////////                    
                              
                              
/* STEP 2: CASH BOOK MAIN Table   */                               
INSERT INTO #TRANSLOG                              
select   '2' + acc_bank.status as 'transtype',                              
  acc_bank.EntryNo AS 'Transcode',                               
  ourbank 'Accode',                              
  dramt = CASE  acc_bank.status                               
    WHEN 'BR' THEN convert (float, actualamount)                              
    WHEN 'CR' THEN convert (float, actualamount)                                
    WHEN 'BP' THEN 0                              
    WHEN 'CP' THEN 0                              
    WHEN 'CE' THEN 0                              
   END,                               
  cramt = CASE  acc_bank.status                               
    WHEN 'BP' THEN convert (float, actualamount)                              
    WHEN 'CP' THEN convert (float, actualamount)                                
    WHEN 'BR' THEN 0                              
    WHEN 'CR' THEN 0                              
    WHEN 'CE' THEN convert (float, actualamount)                              
   END                              
 from acc_bank                               
 LEFT OUTER JOIN dbo.genacct_master ON acc_bank.ourbank = dbo.genacct_master.acctcode                              
 where  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate                              
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  
and (dbo.ConvertDate_IN_US(entrydt,'/') <= @UsrEndDt )                            
  and substring(acc_bank.EntryNo,1,2)  = @CompanyCode                              
  and substring(acc_bank.EntryNo,3,3)  = @CityCode                              
                              
                              
/* STEP 3: CASH BOOK CHILD Table */                              
INSERT INTO #TRANSLOG                              
 select  '2' + acc_bank.status as 'transtype' ,                              
  acc_bankdtls.EntryNo 'transcode',                      
  client 'Accode',                              
  dramt = CASE  acc_bank.status                               
    WHEN 'BR' THEN convert (float, deduction)                              
    WHEN 'CR' THEN convert (float, deduction)                                
    WHEN 'BP' THEN convert (float, amount)                              
    WHEN 'CP' THEN convert (float, amount)                              
    WHEN 'CE' THEN convert (float, amount)                              
   END,                            
  cramt = CASE  acc_bank.status                               
    WHEN 'BP' THEN convert (float, deduction)                              
    WHEN 'CP' THEN convert (float, deduction)                                
    WHEN 'BR' THEN convert (float, amount)                              
    WHEN 'CR' THEN convert (float, amount)                              
    WHEN 'CP' THEN 0                                
   END                              
 from acc_bankdtls                               
   INNER JOIN acc_bank ON acc_bank.EntryNo =  acc_bankdtls.EntryNo                                
                                
 where                               
  dbo.ConvertDate_IN_US(entrydt,'/') >= @Fin_StartDate --@Fin_StartDate                              
  and dbo.ConvertDate_IN_US(entrydt,'/') <= @Fin_EndDate  --@Fin_EndDate
and (dbo.ConvertDate_IN_US(entrydt,'/') <= @UsrEndDt )                              
  and substring(acc_bank.EntryNo,1,2)  = @CompanyCode  --@CompanyCode                              
  and substring(acc_bank.EntryNo,3,3)  = @CityCode  --@CityCode                              
                              
/* STEP 4: JOURNAL VOUCHER Table */                              
INSERT INTO #TRANSLOG   
 select  '3JV' as 'transtype',                               
  acc_JournalVoucDtls.jvcode 'transcode',                              
  jv_account 'Accode',                               
  convert (float, jv_Debit)'dramt',                               
  convert (float, jv_Credit) 'cramt'                        
 from  acc_JournalVoucDtls                               
  INNER JOIN acc_JournalVouc ON acc_JournalVouc.jvcode = acc_JournalVoucDtls.jvcode                               
  LEFT OUTER JOIN dbo.exp_master ON acc_JournalVoucDtls.jv_account = dbo.exp_master.exp_code                               
  LEFT OUTER JOIN dbo.supplier_master ON acc_JournalVoucDtls.jv_account = dbo.supplier_master.sup_code                               
  LEFT OUTER JOIN dbo.genacct_master ON acc_JournalVoucDtls.jv_account = dbo.genacct_master.acctcode                              
 where  dbo.ConvertDate_IN_US(jv_Date,'/') >= @Fin_StartDate                              
  and dbo.ConvertDate_IN_US(jv_Date,'/') <= @Fin_EndDate            
and (dbo.ConvertDate_IN_US(jv_Date,'/') <= @UsrEndDt )                  
  and substring(acc_JournalVoucDtls.jvcode,1,2)  = @CompanyCode                              
  and substring(acc_JournalVoucDtls.jvcode,3,3)  =  @CityCode                              
                              
                              
/* STEP 5: CREDIT NOTE Table */               
                              
INSERT INTO #TRANSLOG                        
Select                          
 '4CN' transtype,                        
 acc_creditnote.crt_no 'transcode',                        
 acc_creditnote.crt_client 'clientcode',                         
 0 'DrAmt',                        
  convert(float,isnull(totalamt,0))                      
  'CrAmt'                        
From acc_creditnote                        
where                        
 (dbo.ConvertDate_IN_US(crt_date,'/') >= @Fin_StartDate) --'')                     
 and (dbo.ConvertDate_IN_US(crt_date,'/') <= @Fin_EndDate ) --'')                         
 and (dbo.ConvertDate_IN_US(crt_date,'/') <= @UsrEndDt )
 and substring(acc_creditnote.crt_no,1,2)  = @CompanyCode --@CompanyCode                        
 and substring(acc_creditnote.crt_no,3,3)  = @CityCode       

INSERT INTO #TRANSLOG            
 sELECT  '4CN' as 'transtype',                    
  acc_creditnote.crt_no 'Transcode',                    
  acc_crtcharge.crt_account 'clientcode',
  convert(float,isnull(acc_crtcharge.crt_inramt,0)) 'DrAmt',                     
   0 'CrAmt'                    
  
 FROM  acc_crtcharge                     
  LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge.crt_no                    
  
 WHERE  --acc_crtcharge.crt_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @UsrEndDt )
  and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
  AND acc_crtcharge.crt_inramt <> '0'  

INSERT INTO #TRANSLOG            
 sELECT  '4CN' as 'transtype',                    
  acc_creditnote.crt_no 'Transcode',                    
  acc_crtcharge1.crt_account 'clientcode',
  convert(float,isnull(acc_crtcharge1.crt_inramt,0)) 'DrAmt',                     
   0 'CrAmt'                    
  
 FROM  acc_crtcharge1                     
  LEFT OUTER JOIN acc_creditnote ON acc_creditnote.crt_no =  acc_crtcharge1.crt_no                    
  
 WHERE  --acc_crtcharge.crt_account = @ClientCode and -- 'G100893' AND                     
  (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') >= @Fin_StartDate) --'1-Apr-2006')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @Fin_EndDate ) --'31-Mar-2007')                     
  and (dbo.ConvertDate_IN_US(acc_creditnote.crt_date,'/') <= @UsrEndDt )
  and substring(acc_creditnote.crt_no,1,2) = @CompanyCode --'01'                    
  and substring(acc_creditnote.crt_no,3,3)  = @CityCode --'101'                    
  AND acc_crtcharge1.crt_inramt <> '0' 
                 
