 (dbo.ConvertDate_IN_US(brok_dt,'/') >= @Fin_StartDate) --'')                               
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @Fin_EndDate ) --'')    
 and (dbo.ConvertDate_IN_US(brok_dt,'/') <= @UsrEndDt )                           
 and substring(acc_brokerage.brok_no,1,2)  = @CompanyCode --@CompanyCode                              
