IF OBJECT_ID('TEMPDB..#TblGrpTrailBal') IS NOT NULL    
DROP TABLE #TblGrpTrailBal    

CREATE TABLE #TBLGRPTRAILBAL (PK_ID INT IDENTITY NOT FOR REPLICATION PRIMARY KEY,        
GROUPNAME VARCHAR(50),OPDR VARCHAR(25) ,OPCR VARCHAR(25),CLDR VARCHAR(25),CLCR VARCHAR(25),CLODR VARCHAR(25),CLOCR VARCHAR(25),FK_CODE VARCHAR(20),NAME VARCHAR(200))             

CREATE TABLE #TBLGROUP        
(        
	PK_ID INT IDENTITY NOT FOR REPLICATION PRIMARY KEY,                  
	GROUPID  VARCHAR(20)          
)        
 
INSERT INTO #TBLGROUP (GROUPID) VALUES ('NOT GROUPED')         
INSERT INTO #TBLGROUP (GROUPID)SELECT DISTINCT FK_CODE FROM #TBLREPORT         
DECLARE @FCOUNT INT ,@FCOUNT1 INT ,@GROUPID VARCHAR(10)        
SET @FCOUNT=1        
SET @FCOUNT1=(SELECT COUNT(PK_ID) FROM #TBLGROUP )        
WHILE (@FCOUNT<=@FCOUNT1)        
BEGIN        
	IF @FCOUNT=1  
	BEGIN  
		INSERT INTO #TBLGRPTRAILBAL (GROUPNAME,FK_CODE) VALUES ('NOT GROUPED','') 
 
		INSERT INTO #TBLGRPTRAILBAL (OPDR ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )            
		SELECT	OPDR, 
				OPCR,
				CLDR,
				CLCR,
				CLODR,
				CLOCR, 
				FK_CODE,
				NAME            
		FROM	#FINAL 
		WHERE	FK_CODE IS NULL AND (CONVERT(NUMERIC,OPDR)<>0 OR CONVERT(NUMERIC,OPCR)<>0 OR CONVERT(NUMERIC,CLDR)<>0  OR CONVERT(NUMERIC,CLCR)<>0 OR CONVERT(NUMERIC,CLODR)<>0 OR CONVERT(NUMERIC,CLOCR)<>0)--(SELECT GROUPID FROM #TBLGROUP WHERE PK_ID= NULL )        
		
		INSERT INTO #TBLGRPTRAILBAL (OPDR  ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )VALUES('','','','','','','','')        

		INSERT INTO #TBLGRPTRAILBAL (OPDR  ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )            
		SELECT	SUM(CONVERT(DECIMAL(18,2),OPDR)),        
				SUM(CONVERT(DECIMAL(18,2),OPCR)),            
				SUM(CONVERT(DECIMAL(18,2),CLDR)),        
				SUM(CONVERT(DECIMAL(18,2),CLCR)),            
				SUM(CONVERT(DECIMAL(18,2),CLODR)),            
				SUM(CONVERT(DECIMAL(18,2),CLOCR)),        
				FK_CODE,        
				'TOTAL : ' AS NAME              
		FROM	#FINAL 
		WHERE FK_CODE IS NULL 
		GROUP BY FK_CODE    --(SELECT GROUPID FROM #TBLGROUP WHERE PK_ID= 1 )    
		
		INSERT INTO #TBLGRPTRAILBAL (OPDR  ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )VALUES('','','','','','','','')  
	END  
	ELSE  
	BEGIN  
		SET @FINALSTR='INSERT INTO #TBLGRPTRAILBAL (GROUPNAME,FK_CODE) SELECT NAME ,FK_CODE FROM  '+@OPBALTABLE+'  WHERE CODE =(SELECT GROUPID FROM #TBLGROUP WHERE PK_ID='+CONVERT(VARCHAR,@FCOUNT)+')'           
		EXEC(@FINALSTR)  
		--INSERT INTO #TBLGRPTRAILBAL (GROUPNAME) SELECT NAME  FROM TBL_MASTER_010420063103007_ALLGL WHERE CODE =(SELECT GROUPID FROM #TBLGROUP WHERE PK_ID=@FCOUNT)         
		INSERT INTO #TBLGRPTRAILBAL (OPDR ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )            
		SELECT	OPDR, 
				OPCR,
				CLDR,
				CLCR,
				CLODR,
				CLOCR, 
				FK_CODE,
				NAME            
		FROM	#FINAL 
		WHERE	FK_CODE=(SELECT GROUPID FROM #TBLGROUP WHERE PK_ID= @FCOUNT )
        
		INSERT INTO #TBLGRPTRAILBAL (OPDR  ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )VALUES('','','','','','','','')        

		INSERT INTO #TBLGRPTRAILBAL (OPDR  ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME)            
		SELECT	SUM(CONVERT(DECIMAL(18,2),OPDR)),        
				SUM(CONVERT(DECIMAL(18,2),OPCR)),            
				SUM(CONVERT(DECIMAL(18,2),CLDR)),        
				SUM(CONVERT(DECIMAL(18,2),CLCR)),            
				SUM(CONVERT(DECIMAL(18,2),CLODR)),            
				SUM(CONVERT(DECIMAL(18,2),CLOCR)),        
				FK_CODE,        
				'TOTAL : ' AS NAME              
		FROM	#FINAL 
		WHERE	FK_CODE=(SELECT GROUPID FROM #TBLGROUP WHERE PK_ID= @FCOUNT ) GROUP BY FK_CODE  
      
		INSERT INTO #TBLGRPTRAILBAL (OPDR  ,OPCR,CLDR ,CLCR ,CLODR ,CLOCR ,FK_CODE,NAME )VALUES('','','','','','','','')        
	END  
	SET @FCOUNT=@FCOUNT + 1         
END        

