drop table #TrailBal    

Create Table #TrailBal   
( pk_id int IDENTITY Not For Replication Primary Key,
  Code nvarchar(10),  
  Name nvarchar(250),  
  DrAmt decimal(18,2),  
  CrAmt decimal(18,2) 
)  

Declare @Cnt int, @cntr int
Declare @GrpId int, @GrpName varchar(100)
Declare @DrAmt varchar(25),@CrAmt Varchar(25),@DiffDrCrAmt decimal(18,2)
Declare @CLODrAmt varchar(25),@CLOCrAmt Varchar(25)

Declare @fk_code varchar(25)

--select * from  #TblGrpId
--select * from #Tbl_TB_Closing
--select pk_id,GroupName,fk_code from  #TblGrpTrailBal where GroupName is not null



Set @Cnt=(select count(pk_id) from  #TblGrpId )
Set @Cntr=1

While @Cntr<=@Cnt
Begin
--	Set @GrpId=(select Grp_Id from  #TblGrpId where pk_id=@Cntr )
	Set @GrpName=(select GroupName from  #TblGrpId where pk_id=@Cntr )
	Set @DrAmt=(select CloDr from #Tbl_TB_Closing where pk_id=@Cntr )
	Set @CrAmt=(select CloCr from #Tbl_TB_Closing where pk_id=@Cntr )
	Set @fk_code=(select fk_code from #Tbl_TB_Closing where pk_id=@Cntr )
	
	Set @DiffDrCrAmt=convert(decimal(18,2),@DrAmt)-convert(decimal(18,2),@CrAmt)
	If @DiffDrCrAmt >= 0
	Begin
		set @DrAmt = @DiffDrCrAmt
		Set @CrAmt=0
	End
	If @DiffDrCrAmt < 0
	Begin
		set @DrAmt =0
		Set @CrAmt = @DiffDrCrAmt
	End

	Insert Into #TrailBal
	Select @fk_code,@GrpName,abs(Isnull(@DrAmt,0)),abs(Isnull(@CrAmt,0))

	SET @Cntr=@Cntr+1
End

Declare @DrAmt1 decimal(18,2),@CrAmt1 decimal(18,2),@DiffInOpBal decimal(18,2)

set @DiffInOpBal=(select (SUM(DrAmt)-SUM(CrAmt)) from #TrailBal)

If @DiffInOpBal >= 0
Begin
	set @DrAmt1 = 0
	Set @CrAmt1=0
End
If @DiffInOpBal < 0
Begin
	set @DrAmt1 =(@DiffInOpBal)
	Set @CrAmt1 = 0
End
--select '','Diff In Opening Balance',(@DrAmt1),(@CrAmt1)
Insert Into #TrailBal (Code,Name,DrAmt,CrAmt)
select '','Diff In Opening Balance',abs(@DrAmt1),abs(@CrAmt1) --from #TrailBal

Insert Into #TrailBal (Code,Name,DrAmt,CrAmt)
select '','TOTAL',abs(SUM(Isnull(DrAmt,0))),abs(SUM(Isnull(CrAmt,0))) from #TrailBal

select * from #TrailBal

